/* ─────────────────────────────────────────────────────────────
   4. StatusFilterTabs: Clickable Filter Control (Semua, On Duty, Standby, Out of Reach)
   Container: flex, gap: 8px, overflow-x: auto, overflow-y: hidden
   Buttons: flex-shrink: 0, white-space: nowrap
───────────────────────────────────────────────────────────── */
export interface StatusFilterTabsProps {
  activeTab: FilterTabOption;
  onSelectTab: (tab: FilterTabOption) => void;
  counts: StatusCounts;
}

export function StatusFilterTabs({
  activeTab,
  onSelectTab,
  counts,
}: StatusFilterTabsProps) {
  const getTabIcon = (id: string, isSelected: boolean) => {
    const base = "tab-icon w-[14px] h-[14px] shrink-0 [transition:all] group-hover:opacity-100";
    const op = isSelected ? "opacity-100" : "opacity-85";
    if (id === "Semua") return <Users size={14} className={`${base} ${op}`} aria-hidden="true" />;
    if (id === "On Duty") return <UserCheck size={14} className={`tab-icon-onduty ${base} ${op} ${isSelected ? "text-[#22c55e]" : ""}`} aria-hidden="true" />;
    if (id === "Standby") return <Clock size={14} className={`tab-icon-standby ${base} ${op} ${isSelected ? "text-[#0ea5e9]" : ""}`} aria-hidden="true" />;
    return <UserX size={14} className={`tab-icon-offline ${base} ${op} ${isSelected ? "text-[#94a3b8]" : ""}`} aria-hidden="true" />;
  };

  const tabs: {
    id: FilterTabOption;
    label: string;
    count: number;
  }[] = [
    { id: "Semua", label: "Semua", count: counts.total },
    { id: "On Duty", label: "On Duty", count: counts.onDuty },
    { id: "Standby", label: "Standby", count: counts.standby },
    { id: "Offline", label: "Out of Reach", count: counts.offline },
  ];

  return (
    <div className="roster-filter-tabs-wrapper w-full box-border mt-[12px] p-[10px_12px_6px] [border-top:1px_solid_var(--line)] [.shift-panel-content_&]:p-0 [.shift-panel-content_&]:[border-top:none] [.shift-panel-content_&]:mb-[10px]">
      <div
        className="filter-tabs roster-filter-tabs grid grid-cols-[repeat(4,minmax(0,1fr))] gap-[4px] p-[3px] rounded-[7px] [.shift-panel-content_&]:rounded-[8px] bg-[var(--bg)] border border-[var(--line)] w-full box-border"
        role="tablist"
        aria-label="Filter status anggota roster"
      >
        {tabs.map((tab) => (
          <button
            key={tab.id}
            type="button"
            role="tab"
            aria-selected={activeTab === tab.id}
            className={`group min-w-0 p-[6px_3px] [.shift-panel-content_&]:p-[6px_4px] rounded-[5px] text-[10.5px] [.shift-panel-content_&]:text-[11px] font-semibold inline-flex items-center justify-center gap-[4px] whitespace-nowrap cursor-pointer [transition:all_0.15s_ease] border ${
              activeTab === tab.id
                ? "selected text-[var(--accent-blue)] bg-[var(--panel-bg)] border-[rgba(96,165,250,0.25)] [box-shadow:var(--shadow-sm)]"
                : "text-[var(--ink-muted)] bg-transparent border-transparent hover:text-[var(--ink-primary)] hover:bg-[rgba(255,255,255,0.04)]"
            }`}
            onClick={() => onSelectTab(tab.id)}
            title={`${tab.label} (${tab.count})`}
            aria-label={`${tab.label} (${tab.count})`}
          >
            {getTabIcon(tab.id, activeTab === tab.id)}
            <span className={`tab-count-badge inline-flex items-center justify-center min-w-[16px] h-[16px] px-[4px] rounded-[99px] text-[9.5px] font-mono font-bold shrink-0 ${
              activeTab === tab.id
                ? "bg-[rgba(96,165,250,0.2)] text-[var(--accent-blue)]"
                : "bg-[rgba(148,163,184,0.18)] text-inherit"
            }`}>{tab.count}</span>
          </button>
        ))}
      </div>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────
   5. RosterMemberRow: Two-Column Flex Layout
      Left: Avatar + Name + Role (flex: 1, min-width: 0)
      Right: StatusIndicator pill (flex-shrink: 0, white-space: nowrap)
───────────────────────────────────────────────────────────── */
export interface RosterMemberRowProps {
  member: TeamMemberItem;
  onClick: (member: TeamMemberItem) => void;
}

export function RosterMemberRow({ member, onClick }: RosterMemberRowProps) {
  const { userStatus } = useUserStatus();
  const isCurrentUser = member.name.toLowerCase().includes("galih");
  const ringStyle = getStatusRingStyle(member.status, isCurrentUser, userStatus);
  const ringColor = (ringStyle as any)["--status-ring-color"] || "#22c55e";

  const indicatorStatus = isCurrentUser
    ? userStatus === "Online"
      ? "bertugas"
      : userStatus === "Busy"
      ? "critical"
      : userStatus === "On Break"
      ? "online"
      : "offline"
    : member.status === "On Duty"
    ? "bertugas"
    : member.status === "Standby"
    ? "online"
    : "offline";

  const displayStatusLabel = isCurrentUser
    ? userStatus
    : member.status === "Offline"
    ? "Out of Reach"
    : member.status;

  return (
    <button
      type="button"
      className="roster-member-row flex items-center [.shift-coverage-card_&]:justify-between w-full gap-[12px] p-[7px_8px] [.shift-coverage-card_&]:p-[8px] m-0 text-[var(--ink-primary)] text-left bg-transparent border-none [.shift-coverage-card_&]:border-b [.shift-coverage-card_&]:border-solid [.shift-coverage-card_&]:border-[var(--line)] [.shift-coverage-card_&]:last:border-b-0 cursor-pointer rounded-[8px] [.shift-coverage-card_&]:rounded-[6px] [transition:background_0.15s_ease] box-border hover:bg-[rgba(148,163,184,0.08)]"
      onClick={() => onClick(member)}
    >
      <div className="roster-member-left flex items-center gap-[10px] flex-1 min-w-0">
        <div
          className="roster-avatar-ring-wrapper"
          style={ringStyle as React.CSSProperties}
          title={`${member.name} (${displayStatusLabel})`}
        >
          <Avatar size="sm" name={member.name} className="shift-coverage-avatar shrink-0" />
          <span
            className="roster-avatar-status-badge"
            style={{ backgroundColor: ringColor }}
          />
        </div>
        <div className="flex flex-col flex-1 min-w-0 gap-[2px]">
          <span className="roster-member-name text-[12.5px] [.shift-coverage-card_&]:text-[11.5px] font-semibold text-[var(--ink-primary)] whitespace-nowrap overflow-hidden text-ellipsis leading-[1.3]" title={member.name}>
            {member.name}
          </span>
          <small className="roster-member-role text-[10.5px] [.shift-coverage-card_&]:text-[10px] text-[var(--ink-muted)] font-normal whitespace-nowrap overflow-hidden text-ellipsis mt-[1px] leading-[1.2]">{member.role}</small>
        </div>
      </div>
      <div className="roster-member-right shrink-0 whitespace-nowrap flex items-center">
        <StatusIndicator status={indicatorStatus} label={displayStatusLabel} size="sm" />
      </div>
    </button>
  );
}

/* ─────────────────────────────────────────────────────────────
   6. MemberList: Scrollable List with Empty-State Handling
───────────────────────────────────────────────────────────── */
export interface MemberListProps {
  members: TeamMemberItem[];
  activeTab: FilterTabOption;
  onSelectMember?: (member: TeamMemberItem) => void;
}

export function MemberList({
  members,
  activeTab,
  onSelectMember,
}: MemberListProps) {
  const notify = useToast();

  const handleMemberClick = (member: TeamMemberItem) => {
    if (onSelectMember) {
      onSelectMember(member);
    } else {
      notify.info(`${member.name}: detail anggota shift dimuat.`, {
        id: `team-member-${member.name.toLowerCase().replace(/\s+/g, "-")}`,
      });
    }
  };

  if (members.length === 0) {
    const emptyMessage =
      activeTab === "On Duty"
        ? "Tidak ada anggota on duty saat ini."
        : activeTab === "Standby"
        ? "Tidak ada anggota standby saat ini."
        : activeTab === "Offline" || (activeTab as string) === "Out of Reach"
        ? "Tidak ada anggota out of reach saat ini."
        : "Tidak ada anggota tim ditemukan.";

    return (
      <div className="coverage-team shift-coverage-team-list flex items-center justify-center min-h-[120px]">
        <div className="p-[24px_16px] text-center text-[var(--ink-muted)] text-[11.5px] leading-[1.4] flex flex-col items-center justify-center">
          <p className="m-0 text-[11.5px] text-[var(--ink-muted)]">{emptyMessage}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="coverage-team shift-coverage-team-list [.shift-coverage-card_&]:p-[8px_16px] [.shift-coverage-card_&]:flex [.shift-coverage-card_&]:flex-col [.shift-coverage-card_&]:max-h-[320px] [.shift-coverage-card_&]:overflow-y-auto [.shift-coverage-card_&]:[scrollbar-width:thin] [.shift-coverage-card_&]:[scrollbar-color:rgba(56,189,248,0.25)_transparent] [.shift-coverage-card_&]:[&::-webkit-scrollbar]:w-[4px] [.shift-coverage-card_&]:[&::-webkit-scrollbar-track]:bg-[rgba(148,163,184,0.05)] [.shift-coverage-card_&]:[&::-webkit-scrollbar-track]:rounded-[4px] [.shift-coverage-card_&]:[&::-webkit-scrollbar-thumb]:bg-[rgba(56,189,248,0.25)] [.shift-coverage-card_&]:[&::-webkit-scrollbar-thumb]:rounded-[4px] [.shift-coverage-card_&]:[&::-webkit-scrollbar-thumb:hover]:bg-[rgba(56,189,248,0.45)]">
      {members.map((member) => (
        <RosterMemberRow
          key={member.id || member.name}
          member={member}
          onClick={handleMemberClick}
        />
      ))}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────
   7. PanelFooter: Fixed Action Button Anchor
───────────────────────────────────────────────────────────── */
export interface PanelFooterProps {
  onViewSchedule?: () => void;
}

export function PanelFooter({ onViewSchedule }: PanelFooterProps) {
  const notify = useToast();

  const handleClick = () => {
    if (onViewSchedule) {
      onViewSchedule();
    } else {
      notify.info("Jadwal shift roster dibuka.", { id: "view-shift-list" });
    }
  };

  return (
    <div className="shift-coverage-footer p-[12px_16px_16px] border-t border-[var(--line)] bg-[var(--panel-bg)]">
      <button type="button" className="full-width-button flex items-center justify-center w-full px-[14px] py-[9px] rounded-[7px] text-[12px] font-semibold text-[var(--accent-blue)] bg-[var(--accent-blue-soft)] border border-[var(--accent-blue-border)] cursor-pointer transition-all duration-150 no-underline hover:bg-[rgba(56,189,248,0.2)] hover:border-[var(--accent-blue)]" onClick={handleClick}>
        Lihat jadwal shift roster <span>→</span>
      </button>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────
   Main Export: RosterTeamPanel (with ShiftCoverageCard alias)
───────────────────────────────────────────────────────────── */
export interface ShiftCoverageCardProps {
  members?: { name: string; role: string; status?: string; initials?: string }[];
  onSelectMember?: (member: TeamMemberItem) => void;
  onViewSchedule?: () => void;
}

export function RosterTeamPanel({
  members,
  onSelectMember,
  onViewSchedule,
}: ShiftCoverageCardProps) {
  const activeShift = useActiveShift();
  const [activeTab, setActiveTab] = useState<FilterTabOption>("Semua");

  const rosterMembers: TeamMemberItem[] = useMemo(() => {
    if (members && members.length > 0) {
      return members.map((m) => ({
        id: (m as any).id || m.name,
        name: m.name,
        role: m.role,
        initials: m.initials || initials(m.name),
        status: resolveCanonicalStatus(m.status),
      }));
    }

    return defaultRosterMembers;
  }, [members]);

  const counts: StatusCounts = useMemo(() => {
    let onDuty = 0;
    let standby = 0;
    let offline = 0;

    for (const m of rosterMembers) {
      if (m.status === "On Duty") onDuty++;
      else if (m.status === "Standby") standby++;
      else offline++;
    }

    return {
      total: rosterMembers.length,
      onDuty,
      standby,
      offline,
      bertugas: onDuty,
    };
  }, [rosterMembers]);

  const filteredMembers = useMemo(() => {
    if (activeTab === "Semua") return rosterMembers;
    if (activeTab === "Offline" || (activeTab as string) === "Out of Reach") {
      return rosterMembers.filter((m) => m.status === "Offline");
    }
    return rosterMembers.filter((m) => m.status === activeTab);
  }, [rosterMembers, activeTab]);

  return (
    <article className="panel shift-coverage-card flex flex-col bg-[var(--panel-bg)] border border-[var(--panel-border)] rounded-[10px] overflow-hidden shadow-[var(--shadow-panel)]">
      <PanelHeader shift={activeShift} />
      <CoverageDonutChart counts={counts} />
      <StatsRow counts={counts} />
      <StatusFilterTabs
        activeTab={activeTab}
        onSelectTab={setActiveTab}
        counts={counts}
      />
      <MemberList
        members={filteredMembers}
        activeTab={activeTab}
        onSelectMember={onSelectMember}
      />
      <PanelFooter onViewSchedule={onViewSchedule} />
    </article>
  );
}

export const ShiftCoverageCard = RosterTeamPanel;

export const RosterCoverageDonut = CoverageDonutChart;
export const RosterStatsRow = StatsRow;
export const RosterStatusFilterTabs = StatusFilterTabs;
export const RosterMemberList = MemberList;
export const RosterPanelFooter = PanelFooter;
export const RosterPanelHeader = PanelHeader;

"use client";

import { useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import {
  ArrowLeft,
  X,
  BarChart3,
  Table,
  SlidersHorizontal,
  TrendingUp,
} from "lucide-react";
import type { PanelId } from "@/app/lib/query-state";
import { TicketVolumeView } from "./TicketVolumeView";
import { TicketMomView } from "./TicketMomView";
import { UserRecapView } from "./UserRecapView";
import { CategoryDistributionView } from "./CategoryDistributionView";
import { SeverityDistributionView } from "./SeverityDistributionView";
import { ShiftTrafficView } from "./ShiftTrafficView";
import { ResolutionTrendView } from "./ResolutionTrendView";
import type { TicketSeverity } from "@/app/lib/types";
import { useNarrowTouchLayout } from "@/app/hooks/useMobileLayout";

interface ActiveFilterItem {
  label: string;
  value: string;
}

interface PanelViewerProps {
  panelId: PanelId | null;
  mode: "chart" | "table";
  onModeChange: (mode: "chart" | "table") => void;
  onClose: () => void;
  onNavigatePanel: (nextPanel: PanelId) => void;

  // Active filters info
  activeFilters: ActiveFilterItem[];
  analyticsTicketCount: number;
  totalTicketCount: number;

  // Shared Data Sources
  volumeByDate: any[];
  allProjects: string[];
  projectColors: Record<string, string>;
  selectedDate: string | null;
  onSelectDate: (date: string | null) => void;

  momData: any;
  userSummaries: any[];
  onSelectUserDetail: (user: any) => void;

  typeCounts: [string, number][];
  totalTickets: number;
  categoryColors: readonly string[];
  renderDonutSlices: any;

  priorityCounts: { Critical: number; High: number; Medium: number; Low: number };
  priorityColors: Record<TicketSeverity, string>;
  severityStyles: Record<TicketSeverity, { borderLeft: string; dot: string; bar: string }>;

  shiftTrafficData: any;
  activeShiftLineFilter: "all" | "Pagi" | "Malam" | "Subuh";
  onShiftLineFilterChange: (filter: "all" | "Pagi" | "Malam" | "Subuh") => void;
}

const PANEL_METADATA: Record<
  PanelId,
  { title: string; subtitle: string; allowTable: boolean }
> = {
  "ticket-volume": {
    title: "Ticket Volume per Project",
    subtitle: "Tiket / hari",
    allowTable: true,
  },
  "ticket-mom": {
    title: "Perbandingan Tiket MoM",
    subtitle: "Agu vs Sep",
    allowTable: true,
  },
  "user-recap": {
    title: "Rekap Tiket per User",
    subtitle: "14 staf",
    allowTable: false, // user-recap is table-first
  },
  "category-distribution": {
    title: "Distribusi Kategori Tiket",
    subtitle: "Rasio kategori",
    allowTable: false, // has donut + table inline
  },
  "severity-distribution": {
    title: "Distribusi Berdasarkan Severity",
    subtitle: "Rasio severity",
    allowTable: false, // has donut + 2x2 cards + table inline
  },
  "shift-traffic": {
    title: "Tren Trafik Beban per Shift",
    subtitle: "Beban shift",
    allowTable: true,
  },
  "resolution-trend": {
    title: "Tren Durasi Penyelesaian",
    subtitle: "Menit / hari",
    allowTable: true,
  },
};

export function PanelViewer({
  panelId,
  mode,
  onModeChange,
  onClose,
  onNavigatePanel,
  activeFilters,
  analyticsTicketCount,
  totalTicketCount,
  volumeByDate,
  allProjects,
  projectColors,
  selectedDate,
  onSelectDate,
  momData,
  userSummaries,
  onSelectUserDetail,
  typeCounts,
  totalTickets,
  categoryColors,
  renderDonutSlices,
  priorityCounts,
  priorityColors,
  severityStyles,
  shiftTrafficData,
  activeShiftLineFilter,
  onShiftLineFilterChange,
}: PanelViewerProps) {
  const narrow = useNarrowTouchLayout();
  const modalRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLElement | null>(null);
  const closeRef = useRef(onClose);
  useEffect(() => { closeRef.current = onClose; }, [onClose]);

  // Focus trap, trigger restoration, and Escape key (ZERO JS SCROLL LOCKING LEAK)
  useEffect(() => {
    if (!panelId) return;

    triggerRef.current = (document.activeElement as HTMLElement) || null;
    const frame = requestAnimationFrame(() => {
      if (panelId === "user-recap" || panelId === "category-distribution" || panelId === "severity-distribution") modalRef.current?.querySelector<HTMLElement>("button")?.focus({ preventScroll: true });
    });

    const handleKeyDown = (e: KeyboardEvent) => {
      if (document.querySelector('[data-user-modal="true"]')) return;
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        closeRef.current();
        return;
      }

      if (e.key === "Tab" && modalRef.current) {
        const focusables = Array.from(
          modalRef.current.querySelectorAll<HTMLElement>(
            'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
          )
        ).filter((el) => el.getBoundingClientRect().width > 0 && el.getBoundingClientRect().height > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[inert], [aria-hidden="true"]'));

        if (focusables.length === 0) return;

        const first = focusables[0];
        const last = focusables[focusables.length - 1];

        if (e.shiftKey) {
          if (document.activeElement === first || !modalRef.current.contains(document.activeElement)) {
            e.preventDefault();
            last.focus();
          }
        } else {
          if (document.activeElement === last || !modalRef.current.contains(document.activeElement)) {
            e.preventDefault();
            first.focus();
          }
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);

    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("keydown", handleKeyDown);
      triggerRef.current?.focus?.({ preventScroll: true });
    };
  }, [panelId]);

  if (!panelId || typeof document === "undefined") return null;

  const meta = PANEL_METADATA[panelId] || {
    title: "Detail Panel",
    subtitle: "",
    allowTable: false,
  };

  const hasCustomFilters = activeFilters.length > 0;
  const isDistribution = panelId === "category-distribution" || panelId === "severity-distribution";
  const smallRecap = panelId === "user-recap" && narrow;

  return createPortal(
    <div
      ref={modalRef}
      data-panel-viewer
      role="dialog"
      aria-modal="true"
      aria-labelledby="panel-viewer-title"
      className="fixed inset-0 z-[100] flex flex-col bg-[#0f172a] text-[#f8fafc] overflow-hidden select-none sm:select-auto panel-viewer-modal"
    >
      {/* ── 1. Top Header Bar (56px) ── */}
      <header className={`${smallRecap ? "h-[52px] min-h-[52px]" : "h-14 min-h-14"} px-3 sm:px-6 flex items-center justify-between border-b border-[#334155] bg-slate-900/95 sticky top-0 z-30 shrink-0 ${isDistribution || smallRecap ? "max-lg:[&_button]:min-h-11 max-lg:[&_button]:min-w-11" : ""}`}>
        {/* Left: Back Button + Title + Subtitle + Default Filter Badge */}
        <div className="flex items-center gap-2.5 sm:gap-4 min-w-0">
          <button
            type="button"
            onClick={onClose}
            className="inline-flex items-center gap-1.5 h-8 px-2.5 sm:px-3 rounded-lg text-xs font-semibold bg-slate-800/80 hover:bg-slate-700/80 text-slate-300 hover:text-white border border-slate-700/80 transition-colors cursor-pointer shrink-0"
            aria-label="Kembali ke Dashboard"
          >
            <ArrowLeft size={15} />
            <span className={smallRecap ? "hidden" : "hidden sm:inline"}>Dashboard</span>
          </button>

          <div className="flex items-center gap-2 min-w-0">
            <h1 id="panel-viewer-title" title={meta.title} className="text-sm sm:text-base lg:text-[17px] font-bold text-white truncate">
              {smallRecap ? "Rekap per User" : meta.title}
            </h1>
            <span className={`${smallRecap ? "hidden" : "hidden md:inline-block"} px-2.5 py-0.5 rounded-full text-[11px] font-mono bg-sky-500/10 border border-sky-500/25 text-sky-400 shrink-0`}>
              {meta.subtitle}
            </span>
            {!hasCustomFilters && (
              <span className="hidden lg:inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[11px] font-mono bg-slate-800/80 border border-slate-700/70 text-slate-400 shrink-0">
                Semua data · <strong className="text-sky-400">{analyticsTicketCount} tiket</strong>
              </span>
            )}
          </div>
        </div>

        {/* Right: Controls + Mode Segmented Control + Close */}
        <div className="flex items-center gap-2 sm:gap-3 shrink-0">
          {/* Tab Switcher for Volume vs MoM */}
          {(panelId === "ticket-volume" || panelId === "ticket-mom") && (
            <div className="hidden sm:flex items-center p-0.5 bg-slate-800/80 border border-slate-700/80 rounded-lg text-xs font-semibold">
              <button
                type="button"
                onClick={() => onNavigatePanel("ticket-volume")}
                className={`px-2.5 py-1 rounded-md transition-all cursor-pointer ${
                  panelId === "ticket-volume"
                    ? "bg-sky-500 text-slate-950 font-bold shadow-sm"
                    : "text-slate-400 hover:text-slate-200"
                }`}
              >
                Volume per Project
              </button>
              <button
                type="button"
                onClick={() => onNavigatePanel("ticket-mom")}
                className={`px-2.5 py-1 rounded-md transition-all cursor-pointer flex items-center gap-1 ${
                  panelId === "ticket-mom"
                    ? "bg-sky-500 text-slate-950 font-bold shadow-sm"
                    : "text-slate-400 hover:text-slate-200"
                }`}
              >
                <TrendingUp size={12} /> MoM
              </button>
            </div>
          )}

          {/* Segmented Control: Grafik | Tabel */}
          {meta.allowTable && (
            <div className="flex items-center p-0.5 bg-slate-800/80 border border-slate-700/80 rounded-lg text-xs font-semibold">
              <button
                type="button"
                onClick={() => onModeChange("chart")}
                className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md transition-all cursor-pointer ${
                  mode === "chart"
                    ? "bg-sky-500 text-slate-950 font-bold shadow-sm"
                    : "text-slate-400 hover:text-slate-200"
                }`}
                title="Tampilkan grafik"
              >
                <BarChart3 size={13} />
                <span className="hidden sm:inline">Grafik</span>
              </button>
              <button
                type="button"
                onClick={() => onModeChange("table")}
                className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md transition-all cursor-pointer ${
                  mode === "table"
                    ? "bg-sky-500 text-slate-950 font-bold shadow-sm"
                    : "text-slate-400 hover:text-slate-200"
                }`}
                title="Tampilkan tabel data"
              >
                <Table size={13} />
                <span className="hidden sm:inline">Tabel</span>
              </button>
            </div>
          )}

          {/* Close button (X) */}
          <button
            type="button"
            onClick={onClose}
            className="w-8 h-8 rounded-lg flex items-center justify-center text-slate-400 hover:text-white hover:bg-slate-800 transition-colors cursor-pointer"
            aria-label="Tutup Tampilan Penuh"
            title="Tutup (Esc)"
          >
            <X size={18} />
          </button>
        </div>
      </header>

      {/* ── 2. Slim Filter Bar (Only if non-default filter is active) ── */}
      {hasCustomFilters && (
        <div className="px-3 sm:px-6 py-1.5 bg-slate-950/80 border-b border-[#334155]/60 flex items-center justify-between flex-wrap gap-2 text-xs shrink-0 max-h-9">
          <div className="flex items-center gap-1.5 flex-wrap">
            <span className="font-semibold text-slate-400 flex items-center gap-1 text-[11px] mr-1">
              <SlidersHorizontal size={11} className="text-sky-400" />
              Filter:
            </span>
            {activeFilters.map((f, idx) => (
              <span
                key={idx}
                className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full font-mono text-[10.5px] bg-slate-800/80 border border-slate-700/80 text-slate-300"
              >
                <span className="text-slate-400">{f.label}:</span>
                <strong className="text-sky-400">{f.value}</strong>
              </span>
            ))}
            <span className="text-slate-500 font-mono text-[10.5px] ml-1.5">
              ({analyticsTicketCount}/{totalTicketCount} tiket)
            </span>
          </div>
        </div>
      )}

      {/* ── 3. Main Viewer Body (Full width up to 1920px, no dead side space) ── */}
      <main className={`flex-1 min-h-0 min-w-0 ${smallRecap ? "p-0" : "p-3 sm:p-5"} flex flex-col max-w-[1920px] w-full mx-auto ${isDistribution ? "overflow-y-auto overscroll-contain lg:overflow-hidden" : "overflow-hidden"}`}>
        {panelId === "ticket-volume" && (
          <TicketVolumeView
            volumeByDate={volumeByDate}
            allProjects={allProjects}
            mode={mode}
            projectColors={projectColors}
            selectedDate={selectedDate}
            onSelectDate={onSelectDate}
          />
        )}

        {panelId === "ticket-mom" && (
          <TicketMomView momData={momData} mode={mode} />
        )}

        {panelId === "user-recap" && (
          <UserRecapView
            userSummaries={userSummaries}
            onSelectUserDetail={onSelectUserDetail}
            projectColors={projectColors}
          />
        )}

        {panelId === "category-distribution" && (
          <CategoryDistributionView
            typeCounts={typeCounts}
            total={totalTickets}
            categoryColors={categoryColors}
            renderDonutSlices={renderDonutSlices}
          />
        )}

        {panelId === "severity-distribution" && (
          <SeverityDistributionView
            priorityCounts={priorityCounts}
            total={totalTickets}
            priorityColors={priorityColors}
            severityStyles={severityStyles}
            renderDonutSlices={renderDonutSlices}
          />
        )}

        {panelId === "shift-traffic" && (
          <ShiftTrafficView
            shiftTrafficData={shiftTrafficData}
            activeLineFilter={activeShiftLineFilter}
            onLineFilterChange={onShiftLineFilterChange}
            mode={mode}
          />
        )}

        {panelId === "resolution-trend" && (
          <ResolutionTrendView volumeByDate={volumeByDate} mode={mode} />
        )}
      </main>
    </div>,
    document.body
  );
}

