"use client";
import Link from "next/link";
import { paths, isActivePath } from "@/app/lib/routes";
import { usePathname } from "next/navigation";

import { useEffect, useState } from "react";
import { X } from "lucide-react";
import { BrandLogo } from "@/app/components/ui/BrandLogo";
import { Avatar } from "@/app/components/ui/Avatar";
import { navItems, USER_STATUS_CONFIG, type UserPresenceStatus } from "./Sidebar";
import { useActiveShift } from "@/app/hooks/useLiveClock";
import type { HandoverRecordData } from "@/app/lib/types";

interface MobileNavProps {
  open: boolean;
  onClose: () => void;
  activeNav: string;
  onPrepareHandover: () => void;
  handoverRecord: HandoverRecordData;
  openTicketCount?: number;
}

export function MobileNav({
  open,
  onClose,
  activeNav,
  onPrepareHandover,
  handoverRecord,
  openTicketCount = 0,
}: MobileNavProps) {
  const activeShift = useActiveShift();
  const pathname = usePathname();
  const [userStatus, setUserStatus] = useState<UserPresenceStatus>("Online");

  useEffect(() => {
    if (typeof window !== "undefined") {
      const saved = localStorage.getItem("ctd.user.status") as string | null;
      if (saved === "On Leave") {
        setUserStatus("AFK");
      } else if (saved && USER_STATUS_CONFIG[saved as UserPresenceStatus]) {
        setUserStatus(saved as UserPresenceStatus);
      }
    }
  }, [open]);

  const currentStatusConfig = USER_STATUS_CONFIG[userStatus] || USER_STATUS_CONFIG["Online"];

  useEffect(() => {
    if (!open) return;
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [open, onClose]);

  if (!open) return null;


  return (
    <div
      className="mobile-nav-backdrop anim-fade [position:fixed] [inset:0] [z-index:70] [display:flex] [justify-content:flex-start] [background:var(--overlay-bg)]"
      role="presentation"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <div className="mobile-drawer anim-slide-right [display:flex] [flex-direction:column] [gap:14px] [width:min(300px,_86vw)] [height:100%] [padding:20px_14px_18px] [overflow-y:auto] [color:var(--sidebar-text)] [background:var(--sidebar-bg)] [box-shadow:var(--shadow-elevated)]" role="dialog" aria-modal="true" aria-label="Navigasi mobile">
        <div className="mobile-drawer-head [display:flex] [align-items:center] [justify-content:space-between] [gap:8px]">
          <BrandLogo size={26} />
          <button className="mobile-drawer-close [display:grid] [place-items:center] [width:44px] [height:44px] [min-width:44px] [padding:0] [color:var(--sidebar-muted)] [border:1px_solid_rgba(56,_189,_248,_0.2)]! [border-radius:7px]" onClick={onClose} aria-label="Tutup menu">
            <X size={18} strokeWidth={2.2} aria-hidden="true" />
          </button>
        </div>

        {/* ── Main Navigation List ── */}
        <div className="nav-list">
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = isActivePath(pathname, item.path);

            return (
              <Link href={item.path} onClick={onClose}
                key={item.label}
                aria-current={isActive ? "page" : undefined}
                className={`nav-item [min-height:44px] ${isActive ? "active" : ""}`}
              >
                <span className="nav-icon" aria-hidden="true">
                  <Icon size={18} strokeWidth={1.8} aria-hidden="true" />
                </span>
                <span>{item.label}</span>
                {item.label === "Tickets" && openTicketCount > 0 && (
                  <span className="nav-count nav-count-tickets" suppressHydrationWarning>{openTicketCount}</span>
                )}
              </Link>
            );
          })}

          {/* Runbooks — standalone nav item */}
          <Link aria-current={activeNav === "Runbooks" ? "page" : undefined} href={paths.runbooks} onClick={onClose}
            className={`nav-item [min-height:44px] ${activeNav === "Runbooks" ? "active" : ""}`}
          >
            <span className="nav-icon" aria-hidden="true">
              <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/></svg>
            </span>
            <span>Runbooks</span>
          </Link>
        </div>

        {/* ── Bottom Active Shift Card ── */}
        <section className={`shift-card [margin:auto_0_12px] shift-card-${activeShift.id}`}>
          <div className="shift-card-top">
            <span className="live-dot live-dot-pulse" /> ACTIVE SHIFT
          </div>
          <strong>{activeShift.label}</strong>
          <p>{activeShift.period} · {handoverRecord.sourceShift} → {handoverRecord.targetShift}</p>
          <button
            onClick={() => {
              onPrepareHandover();
              onClose();
            }}
          >
            Siapkan Handover <span>→</span>
          </button>
        </section>

        <Link href={paths.profile} onClick={onClose}
          className="profile"
          title="Buka Profil Pengguna"
        >
          <div
            className="profile-avatar-ring-wrapper"
            style={{
              "--status-ring-color": currentStatusConfig.color,
              "--status-ring-glow": currentStatusConfig.glow,
            } as React.CSSProperties}
          >
            <Avatar size="md" initials="GK" shape="circle" className="profile-avatar" />
            <span
              className="profile-status-badge"
              style={{ backgroundColor: currentStatusConfig.color }}
            />
          </div>
          <span>
            <strong>Galih Khairi</strong>
            <small className="profile-status-row">
              <span
                className="profile-status-indicator-dot"
                style={{ backgroundColor: currentStatusConfig.color }}
              />
              <span style={{ color: currentStatusConfig.color, fontWeight: 600 }}>{userStatus}</span>
              <span className="profile-status-sep">·</span>
              <span>Operator NOC</span>
            </small>
          </span>
        </Link>
      </div>
    </div>
  );
}

"use client";
import Link from "next/link";
import { paths } from "@/app/lib/routes";


import { useEffect, useMemo, useRef, useState } from "react";
import { Users, ChevronLeft, ChevronRight } from "lucide-react";
import { useActiveShift } from "@/app/hooks/useLiveClock";
import {
  defaultRosterMembers,
  CoverageDonutChart,
  StatsRow,
  StatusFilterTabs,
  MemberList,
  type TeamMemberItem,
  type StatusCounts,
  type FilterTabOption,
} from "@/app/components/dashboard/ShiftCoverageCard";

interface ShiftCoveragePanelProps {
  isOpen: boolean;
  onToggle: () => void;
  onNavigateToRoster?: () => void;
}

export function ShiftCoveragePanel({
  isOpen,
  onToggle,
}: ShiftCoveragePanelProps) {
  const activeShift = useActiveShift();
  const [activeTab, setActiveTab] = useState<FilterTabOption>("Semua");

  const listScrollRef = useRef<HTMLDivElement>(null);
  const panelContentRef = useRef<HTMLDivElement>(null);

  // ── 1. Lock Main Page Scroll, Compensate Scrollbar, & Listen for ESC ──
  useEffect(() => {
    if (!isOpen) return;

    // Hitung lebar scrollbar utama sebelum dikunci untuk mencegah pergeseran layout
    const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;
    const originalBodyOverflow = document.body.style.overflow;
    const originalBodyPaddingRight = document.body.style.paddingRight;
    const originalHtmlOverflow = document.documentElement.style.overflow;

    // Kunci scroll halaman di belakang drawer
    document.documentElement.style.overflow = "hidden";
    document.body.style.overflow = "hidden";
    if (scrollbarWidth > 0) {
      document.body.style.paddingRight = `${scrollbarWidth}px`;
    }

    // Tangani penutupan drawer dengan tombol ESC
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        onToggle();
      }
    };

    window.addEventListener("keydown", handleKeyDown);

    // Cleanup: kembalikan overflow dan padding saat drawer ditutup atau unmount
    return () => {
      document.documentElement.style.overflow = originalHtmlOverflow;
      document.body.style.overflow = originalBodyOverflow;
      document.body.style.paddingRight = originalBodyPaddingRight;
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [isOpen, onToggle]);

  // ── 2. Reset Scroll Daftar ke Atas Saat Tab Filter Berubah ──
  useEffect(() => {
    if (listScrollRef.current) {
      listScrollRef.current.scrollTop = 0;
    }
    if (panelContentRef.current) {
      panelContentRef.current.scrollTop = 0;
    }
  }, [activeTab]);

  const rosterMembers: TeamMemberItem[] = useMemo(() => {
    return defaultRosterMembers;
  }, []);

  const counts: StatusCounts = useMemo(() => {
    let onDuty = 0;
    let standby = 0;
    let offline = 0;

    for (const m of rosterMembers) {
      if (m.status === "On Duty") onDuty++;
      else if (m.status === "Standby") standby++;
      else offline++;
    }

    return {
      total: rosterMembers.length,
      onDuty,
      standby,
      offline,
      bertugas: onDuty,
    };
  }, [rosterMembers]);

  const filteredMembers = useMemo(() => {
    if (activeTab === "Semua") return rosterMembers;
    if (activeTab === "Offline" || (activeTab as string) === "Out of Reach") {
      return rosterMembers.filter((m) => m.status === "Offline");
    }
    return rosterMembers.filter((m) => m.status === activeTab);
  }, [rosterMembers, activeTab]);

  return (
    <>
      {/* ── Toggle Tab Handle (di sisi kanan, GPU-transformed) ── */}
      <button
        type="button"
        className={`shift-panel-toggle-tab max-lg:hidden fixed right-0 top-1/2 z-[80] flex flex-col items-center gap-[6px] p-[12px_6px] max-[660px]:p-[10px_5px] rounded-l-[10px] cursor-pointer bg-[var(--panel-bg,#1e293b)] border border-[var(--line,rgba(255,255,255,0.08))] text-[var(--ink-muted,#94a3b8)] font-['Plus_Jakarta_Sans',sans-serif] text-[10px] font-semibold will-change-transform [transition:transform_0.35s_cubic-bezier(0.16,_1,_0.3,_1),_background_0.2s_ease,_color_0.2s_ease,_border-color_0.2s_ease] [box-shadow:-2px_0_12px_rgba(0,_0,_0,_0.15)] hover:bg-[var(--panel-bg-hover,#283548)] hover:text-[var(--ink-primary,#e2e8f0)] hover:pr-[10px] focus-visible:outline-2 focus-visible:outline-[var(--accent-blue,#38bdf8)] focus-visible:outline-offset-2 ${
          isOpen
            ? "shift-panel-toggle-active [transform:translate3d(-300px,_-50%,_0)] max-[940px]:[transform:translate3d(-280px,_-50%,_0)] max-[660px]:[transform:translate3d(-260px,_-50%,_0)]"
            : "[transform:translate3d(0,_-50%,_0)]"
        }`}
        onClick={onToggle}
        aria-label={isOpen ? "Tutup panel roster tim" : "Buka panel roster tim"}
        title={isOpen ? "Tutup Roster Tim" : "Buka Roster Tim"}
      >
        <Users size={16} strokeWidth={2} />
        <span className="shift-panel-toggle-badge flex items-center justify-center w-[20px] h-[20px] max-[660px]:w-[18px] max-[660px]:h-[18px] rounded-[50%] bg-[linear-gradient(135deg,#22c55e,#16a34a)] text-[#ffffff] text-[10px] max-[660px]:text-[9px] font-bold leading-none [box-shadow:0_2px_6px_rgba(34,_197,_94,_0.3)]">
          {counts.onDuty}
        </span>
        {isOpen ? (
          <ChevronRight size={12} className="shift-panel-toggle-chevron opacity-50 [transition:opacity_0.2s] hover:opacity-100" />
        ) : (
          <ChevronLeft size={12} className="shift-panel-toggle-chevron opacity-50 [transition:opacity_0.2s] hover:opacity-100" />
        )}
      </button>

      {/* ── Overlay Backdrop (dismiss on outside click) ── */}
      {isOpen && (
        <div
          className="shift-panel-backdrop fixed inset-0 z-[74] bg-[rgba(10,15,29,0.45)] backdrop-blur-[4px] [-webkit-backdrop-filter:blur(4px)] animate-[shift-backdrop-in_0.25s_ease] cursor-pointer"
          onClick={onToggle}
          aria-hidden="true"
        />
      )}

      {/* ── Panel Drawer ── */}
      <aside
        className={`shift-coverage-panel fixed right-0 top-0 h-dvh w-[300px] max-[940px]:w-[280px] z-[75] flex flex-col bg-[var(--panel-bg,#1e293b)] [border-left:1px_solid_var(--line,rgba(255,255,255,0.08))] [box-shadow:-6px_0_32px_rgba(0,_0,_0,_0.35)] will-change-transform [backface-visibility:hidden] [transition:transform_0.35s_cubic-bezier(0.16,_1,_0.3,_1)] overflow-hidden ${
          isOpen ? "shift-panel-open [transform:translateX(0)]" : "shift-panel-closed [transform:translateX(100%)] pointer-events-none"
        }`}
        aria-label="Panel Roster Tim & Shift Coverage"
        role="complementary"
      >
        {/* Header Drawer (Tetap diam di atas) */}
        <div className="shift-panel-header shift-coverage-header flex flex-col items-center justify-center text-center p-[16px_20px_14px] [border-bottom:1px_solid_var(--line)] bg-[var(--panel-bg,#1e293b)] shrink-0">
          <div className="shift-panel-header-text flex flex-col items-center gap-[3px]">
            <h3 className="shift-panel-title text-[15px] font-bold text-[var(--ink-primary,#e2e8f0)] m-0 tracking-[0.01em]">
              Roster Tim
            </h3>
            <span className="shift-panel-subtitle text-[11.5px] font-semibold text-[var(--ink-muted,#94a3b8)] uppercase tracking-[0.08em]">
              Shift Coverage
            </span>
          </div>
        </div>

        {/* Panel Content Body */}
        <div
          ref={panelContentRef}
          className="shift-panel-content flex-1 min-h-0 flex flex-col overflow-hidden p-[12px_14px_8px] [@media(max-height:700px)]:overflow-y-auto [@media(max-height:700px)]:overscroll-contain [scrollbar-width:thin] [scrollbar-color:#334155_transparent] [&::-webkit-scrollbar]:w-[6px] [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar-thumb]:bg-slate-700 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb:hover]:bg-slate-600"
        >
          {/* Top Controls: Donut Chart, Stats, & Status Filter Tabs (Diam di atas, fleksibel di layar pendek) */}
          <div className="shift-panel-top-controls shrink-0 flex flex-col [@media(max-height:700px)]:flex-none">
            <CoverageDonutChart counts={counts} />
            <StatsRow counts={counts} />
            <div className="[@media(max-height:700px)]:sticky [@media(max-height:700px)]:top-0 [@media(max-height:700px)]:z-10 [@media(max-height:700px)]:bg-[var(--panel-bg,#1e293b)] [@media(max-height:700px)]:pt-1 [@media(max-height:700px)]:pb-1">
              <StatusFilterTabs
                activeTab={activeTab}
                onSelectTab={setActiveTab}
                counts={counts}
              />
            </div>
          </div>

          {/* Area Khusus Scroll Daftar Anggota */}
          <div
            ref={listScrollRef}
            className="shift-panel-user-list-scroll flex-1 min-h-0 overflow-y-auto overscroll-contain mt-[8px] pr-2 [@media(max-height:700px)]:overflow-visible [@media(max-height:700px)]:flex-none [scrollbar-width:thin] [scrollbar-color:#334155_transparent] [&::-webkit-scrollbar]:w-[6px] [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar-thumb]:bg-slate-700 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb:hover]:bg-slate-600"
          >
            <MemberList
              members={filteredMembers}
              activeTab={activeTab}
            />
          </div>
        </div>

        {/* Panel Footer (Tetap menempel di bawah) */}
        <div className="shift-panel-footer shift-coverage-footer p-[12px_14px_14px] [border-top:1px_solid_var(--line,rgba(255,255,255,0.08))] shrink-0 box-border w-full bg-[var(--panel-bg,#1e293b)]">
          <Link href={paths.teamRoster} onClick={() => { if (window.innerWidth <= 940) onToggle(); }}
            className="full-width-button flex items-center justify-center gap-[8px] w-full h-auto min-h-[38px] m-0 p-[10px_14px] box-border border border-[rgba(99,102,241,0.35)] rounded-[10px] cursor-pointer bg-[linear-gradient(135deg,rgba(99,102,241,0.22),rgba(139,92,246,0.16))] text-[#c7d2fe] font-['Plus_Jakarta_Sans',sans-serif] text-[12.5px] font-semibold text-center [transition:background_0.2s_ease,_border-color_0.2s_ease,_color_0.2s_ease] [box-shadow:none] [transform:none] hover:bg-[linear-gradient(135deg,rgba(99,102,241,0.32),rgba(139,92,246,0.25))] hover:text-[#ffffff] hover:border-[rgba(99,102,241,0.55)] active:bg-[rgba(99,102,241,0.28)]"
          >
            <span>Lihat jadwal shift roster</span>
            <span className="shift-panel-btn-arrow text-[14px] inline-block [transform:none]" aria-hidden="true">
              →
            </span>
          </Link>
        </div>
      </aside>
    </>
  );
}

"use client";
import Link from "next/link";
import { paths } from "@/app/lib/routes";

import { useEffect, useRef, useState } from "react";
import { ArrowRight, ArrowRightLeft, CheckCircle2, ChevronDown, Clock, ExternalLink, Moon, Sun, Sunset, Users } from "lucide-react";
import { useMobileLayout } from "@/app/hooks/useMobileLayout";
import { useShiftTransition } from "@/app/hooks/useLiveClock";


interface ShiftTransitionBadgeProps {
  onOpenHandover?: () => void;
  onNavigate?: (label: string) => void;
}

function getShiftIcon(id: string) {
  if (id === "subuh") return Moon;
  if (id === "pagi") return Sun;
  return Sunset;
}

export function ShiftTransitionBadge({ onOpenHandover, onNavigate }: ShiftTransitionBadgeProps) {
  const transition = useShiftTransition();
  const mobile = useMobileLayout();
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Close when clicking outside
  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    }

    if (isOpen) {
      document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isOpen]);

  // Close on Escape key
  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape" && isOpen) {
        setIsOpen(false);
      }
    }
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen]);

  // Only render if inside active handover window or upcoming window
  if (!transition.isActive && !transition.isUpcoming) {
    return null;
  }

  const FromIcon = getShiftIcon(transition.fromShift.id);
  const ToIcon = getShiftIcon(transition.toShift.id);

  const handleOpenHandover = () => {
    setIsOpen(false);
    if (onOpenHandover) {
      onOpenHandover();
    } else if (onNavigate) {
      onNavigate("Shift Log");
    }
  };

  const fromShiftName = transition.fromShift.name.replace("Shift ", "");
  const toShiftName = transition.toShift.name.replace("Shift ", "");

  return (
    <div
      className="shift-transition-container relative inline-flex items-center"
      ref={containerRef}
    >
      <button
        type="button"
        className={`app-transition-pill inline-flex max-lg:min-h-10 max-md:size-10 max-md:min-h-10 max-md:p-0 max-md:justify-center max-md:[&_.transition-info-stack]:hidden max-md:[&_.transition-badge-actions]:hidden items-center gap-[12px] px-[12px] py-[5px] min-h-[38px] rounded-[8px] cursor-pointer select-none text-[#ffffff] transition-[background-color_0.18s_ease,border-color_0.18s_ease] shadow-none [&:hover_.transition-chevron]:text-[rgba(255,255,255,0.85)] ${
          transition.isActive
            ? isOpen
              ? "active-window open border border-[#f59e0b] bg-[rgba(245,158,11,0.18)]"
              : "active-window border border-[rgba(245,158,11,0.32)] bg-[rgba(245,158,11,0.08)] hover:border-[rgba(245,158,11,0.55)] hover:bg-[rgba(245,158,11,0.14)]"
            : "upcoming-window border border-[rgba(56,189,248,0.3)] bg-[rgba(56,189,248,0.08)] hover:border-[rgba(56,189,248,0.55)] hover:bg-[rgba(56,189,248,0.14)]"
        }`}
        onClick={() => mobile ? handleOpenHandover() : setIsOpen((prev) => !prev)}
        aria-label={`Transisi shift ${transition.label}`}
        aria-expanded={isOpen}
        aria-haspopup="dialog"
        title={
          transition.isActive
            ? `Pergantian Shift Aktif: ${transition.label} (${transition.windowPeriod}) - Sisa ${transition.minutesRemaining} menit`
            : `Pergantian Shift Akan Datang: ${transition.label} dalam ${transition.minutesUntilStart} menit`
        }
      >
        {/* Lead Icon with subtle live glow */}
        <div
          className={`transition-icon-container relative flex items-center justify-center w-[24px] h-[24px] rounded-[6px] shrink-0 ${
            transition.isActive
              ? "bg-[rgba(245,158,11,0.14)] border border-[rgba(245,158,11,0.3)]"
              : "bg-[rgba(56,189,248,0.14)] border border-[rgba(56,189,248,0.3)]"
          }`}
          aria-hidden="true"
        >
          <ArrowRightLeft
            size={13}
            className={`transition-lead-icon ${transition.isActive ? "text-[#fbbf24]" : "text-[#38bdf8]"}`}
          />
          {transition.isActive && (
            <span className="transition-live-dot absolute -top-[2px] -right-[2px] w-[6px] h-[6px] rounded-[50%] bg-[#f59e0b] [box-shadow:0_0_6px_#f59e0b] animate-[liveDotPulse_2s_infinite_ease-in-out]" />
          )}
        </div>

        {/* Clean 2-line textual hierarchy */}
        <div className="transition-info-stack flex flex-col items-start text-left leading-[1.15] min-w-0">
          <div className="transition-meta-row transition-meta-line flex items-center gap-[4px] max-[900px]:hidden">
            <span className={`transition-kicker-label text-[8.5px] max-lg:text-[11px] font-extrabold tracking-[0.6px] uppercase font-[var(--font-mono)] ${transition.isActive ? "text-[#fbbf24]" : "text-[#38bdf8]"}`}>
              {transition.isActive ? "TRANSISI SHIFT" : "MENUJU TRANSISI"}
            </span>
            <span className="transition-meta-dot text-[rgba(255,255,255,0.35)] text-[9px] max-lg:text-[11px]">·</span>
            <span className="transition-time-range text-[9.5px] max-lg:text-[11px] font-[var(--font-mono)] text-[rgba(255,255,255,0.7)] font-medium">{transition.windowStart}–{transition.windowEnd}</span>
          </div>

          <div className="transition-flow-row transition-names-label flex items-center gap-[4px] mt-[1px] text-[11.5px] font-bold text-[#f8fafc] whitespace-nowrap max-[640px]:hidden">
            <span className="shift-name-from text-[#e2e8f0]">{fromShiftName}</span>
            <ArrowRight size={10} className={`shift-flow-arrow opacity-85 ${transition.isActive ? "text-[#fbbf24]" : "text-[#38bdf8]"}`} />
            <span className="shift-name-to text-[#ffffff]">{toShiftName}</span>
          </div>
        </div>

        {/* Countdown Badge & Chevron */}
        <div className="transition-badge-actions inline-flex items-center gap-[8px] ml-auto shrink-0">
          <span className={`transition-timer-badge inline-flex items-center justify-center h-[24px] min-w-[64px] px-[10px] rounded-[999px] text-[10.5px] max-lg:text-[11px] font-bold font-[var(--font-mono)] leading-none tracking-[0.2px] text-center whitespace-nowrap box-border ${transition.isActive ? "bg-[rgba(245,158,11,0.18)] text-[#fbbf24] border border-[rgba(245,158,11,0.4)]" : "bg-[rgba(56,189,248,0.15)] text-[#38bdf8] border border-[rgba(56,189,248,0.4)]"}`}>
            {transition.isActive
              ? `Sisa ${transition.minutesRemaining}m`
              : `dlm ${transition.minutesUntilStart}m`}
          </span>
          <ChevronDown size={12} className={`transition-chevron inline-flex items-center justify-center text-[rgba(255,255,255,0.55)] transition-[transform_0.2s_ease,color_0.15s_ease] shrink-0 ${isOpen ? "rotate-180" : ""}`} />
        </div>
      </button>

      {isOpen && (
        <div
          className="shift-transition-popover absolute top-[calc(100%+8px)] right-0 w-[420px] max-w-[calc(100vw-24px)] max-[640px]:w-[calc(100vw-20px)] max-[640px]:-right-[40px] bg-[#111520] border border-[rgba(245,158,11,0.35)] rounded-[12px] [box-shadow:0_16px_40px_rgba(0,0,0,0.75),_0_0_28px_rgba(245,158,11,0.15)] p-[16px] z-[100] backdrop-blur-[16px] flex flex-col gap-[13px] animate-[transitionPopoverFade_0.18s_cubic-bezier(0.16,1,0.3,1)]"
          role="dialog"
          aria-label="Detail Jendela Pergantian Shift"
        >
          {/* Popover Header */}
          <div className="transition-popover-header flex items-start justify-between gap-[10px] pb-[10px] border-b border-[rgba(255,255,255,0.08)]">
            <div className="transition-header-title-box flex flex-col gap-[2px]">
              <span className="transition-header-kicker inline-flex items-center gap-[5px] text-[9.5px] max-lg:text-[11px] font-extrabold tracking-[0.8px] text-[#fbbf24] uppercase font-[var(--font-mono)]">
                <ArrowRightLeft size={13} />
                <span>HANDOVER WINDOW</span>
              </span>
              <h4 className="transition-header-heading m-0 text-[14px] font-bold text-[#ffffff]">
                {transition.isActive
                  ? `Pergantian Shift: ${transition.label}`
                  : `Persiapan Shift: ${transition.label}`}
              </h4>
            </div>
            <span
              className={`transition-status-pill text-[10px] max-lg:text-[11px] font-bold px-[8px] py-[3px] rounded-[999px] whitespace-nowrap font-[var(--font-mono)] ${
                transition.isActive
                  ? "status-overlap-active bg-[rgba(245,158,11,0.2)] text-[#fbbf24] border border-[rgba(245,158,11,0.4)]"
                  : "status-upcoming bg-[rgba(56,189,248,0.15)] text-[#38bdf8] border border-[rgba(56,189,248,0.35)]"
              }`}
            >
              {transition.isActive ? "Overlap Aktif (30m)" : `Mulai dlm ${transition.minutesUntilStart}m`}
            </span>
          </div>

          {/* Overlap Progress Meter */}
          <div className="transition-timeline-box flex flex-col gap-[6px] bg-[rgba(255,255,255,0.03)] p-[9px_11px] rounded-[8px] border border-[rgba(255,255,255,0.06)]">
            <div className="transition-timeline-labels flex items-center justify-between text-[10px] max-lg:text-[11px] font-[var(--font-mono)] text-[var(--ink-muted)]">
              <span className="timeline-start-time inline-flex items-center gap-[4px] text-[#cbd5e1] font-semibold">
                <Clock size={11} /> {transition.windowStart} WIB
              </span>
              <span className="timeline-info-center text-[#fbbf24] font-semibold">
                {transition.isActive
                  ? `Sisa ${transition.minutesRemaining} menit dari total 30 menit`
                  : `Mulai pada pukul ${transition.windowStart} WIB`}
              </span>
              <span className="timeline-end-time inline-flex items-center gap-[4px] text-[#cbd5e1] font-semibold">{transition.windowEnd} WIB</span>
            </div>
            <div className="transition-progress-track w-full h-[6px] rounded-[999px] bg-[rgba(255,255,255,0.08)] overflow-hidden">
              <div
                className="transition-progress-fill h-full bg-[linear-gradient(90deg,#f59e0b_0%,#a855f7_100%)] rounded-[999px] transition-[width] duration-300 ease-out [box-shadow:0_0_10px_rgba(245,158,11,0.5)]"
                style={{ width: `${transition.isActive ? transition.progressPercent : 0}%` }}
              />
            </div>
          </div>

          {/* Visual Shift Handover Cards (From Shift -> To Shift) */}
          <div className="transition-shifts-grid grid grid-cols-[1fr_auto_1fr] items-center gap-[8px]">
            {/* Outgoing Shift Card */}
            <div className={`transition-shift-card from-card shift-theme-${transition.fromShift.id} flex flex-col p-[10px] rounded-[9px] ${
              transition.fromShift.id === "pagi"
                ? "border border-[rgba(245,158,11,0.3)] bg-[rgba(245,158,11,0.05)]"
                : transition.fromShift.id === "malam"
                  ? "border border-[rgba(168,85,247,0.3)] bg-[rgba(168,85,247,0.05)]"
                  : transition.fromShift.id === "subuh"
                    ? "border border-[rgba(56,189,248,0.3)] bg-[rgba(56,189,248,0.05)]"
                    : "border border-[rgba(255,255,255,0.08)] bg-[rgba(255,255,255,0.03)]"
            }`}>
              <div className="shift-card-header flex items-center justify-between mb-[4px]">
                <span className="shift-card-role-tag text-[8px] max-lg:text-[11px] font-extrabold tracking-[0.6px] text-[var(--ink-muted)] font-[var(--font-mono)]">SHIFT KELUAR</span>
                <FromIcon size={14} className={`shift-card-icon ${transition.fromShift.id === "malam" ? "text-[#c084fc]" : transition.fromShift.id === "subuh" ? "text-[#38bdf8]" : "text-[#fbbf24]"}`} />
              </div>
              <strong className="shift-card-name text-[12px] font-bold text-[#ffffff]">{transition.fromShift.label}</strong>
              <span className="shift-card-hours text-[9.5px] max-lg:text-[11px] font-[var(--font-mono)] text-[#94a3b8] mt-[1px]">{transition.fromShift.period}</span>
              <p className="shift-card-desc m-[6px_0_0] text-[9.5px] max-lg:text-[11px] leading-[1.35] text-[var(--ink-muted)]">
                Penyelesaian checklist monitoring, update tiket kendala, & transfer informasi operasional.
              </p>
            </div>

            {/* Connecting Transfer Indicator */}
            <div className="transition-connector flex flex-col items-center gap-[3px]">
              <span className="connector-line w-[1px] h-[8px] bg-[rgba(255,255,255,0.15)]" />
              <span className="connector-badge w-[24px] h-[24px] rounded-[50%] grid place-items-center bg-[rgba(245,158,11,0.18)] text-[#fbbf24] border border-[rgba(245,158,11,0.4)]">
                <ArrowRight size={14} />
              </span>
              <span className="connector-line w-[1px] h-[8px] bg-[rgba(255,255,255,0.15)]" />
            </div>

            {/* Incoming Shift Card */}
            <div className={`transition-shift-card to-card shift-theme-${transition.toShift.id} flex flex-col p-[10px] rounded-[9px] ${
              transition.toShift.id === "pagi"
                ? "border border-[rgba(245,158,11,0.3)] bg-[rgba(245,158,11,0.05)]"
                : transition.toShift.id === "malam"
                  ? "border border-[rgba(168,85,247,0.3)] bg-[rgba(168,85,247,0.05)]"
                  : transition.toShift.id === "subuh"
                    ? "border border-[rgba(56,189,248,0.3)] bg-[rgba(56,189,248,0.05)]"
                    : "border border-[rgba(255,255,255,0.08)] bg-[rgba(255,255,255,0.03)]"
            }`}>
              <div className="shift-card-header flex items-center justify-between mb-[4px]">
                <span className="shift-card-role-tag text-[8px] max-lg:text-[11px] font-extrabold tracking-[0.6px] text-[var(--ink-muted)] font-[var(--font-mono)]">SHIFT MASUK</span>
                <ToIcon size={14} className={`shift-card-icon ${transition.toShift.id === "malam" ? "text-[#c084fc]" : transition.toShift.id === "subuh" ? "text-[#38bdf8]" : "text-[#fbbf24]"}`} />
              </div>
              <strong className="shift-card-name text-[12px] font-bold text-[#ffffff]">{transition.toShift.label}</strong>
              <span className="shift-card-hours text-[9.5px] max-lg:text-[11px] font-[var(--font-mono)] text-[#94a3b8] mt-[1px]">{transition.toShift.period}</span>
              <p className="shift-card-desc m-[6px_0_0] text-[9.5px] max-lg:text-[11px] leading-[1.35] text-[var(--ink-muted)]">
                Verifikasi checklist serah-terima, periksa tiket terbuka, & ambil alih pemantauan sistem.
              </p>
            </div>
          </div>

          {/* SOP Checklist / Note Hint */}
          <div className="transition-hint-banner flex items-start gap-[8px] p-[8px_10px] rounded-[8px] bg-[rgba(56,189,248,0.06)] border border-[rgba(56,189,248,0.18)] text-[10.5px] max-lg:text-[11px] leading-[1.4] text-[#cbd5e1]">
            <CheckCircle2 size={14} className="hint-banner-icon text-[#38bdf8] shrink-0 mt-[2px]" />
            <div className="hint-banner-text">
              <strong className="block text-[#38bdf8] text-[10.5px] max-lg:text-[11px] mb-[2px]">SOP Temu Shift 30 Menit:</strong>
              <span>
                Kedua PIC shift bertugas bersama selama {transition.windowPeriod} untuk memastikan
                kesinambungan pemantauan tanpa kendala terlewat.
              </span>
            </div>
          </div>

          {/* Popover Actions */}
          <div className="transition-popover-actions flex items-center gap-[8px] pt-[6px]">
            <button
              type="button"
              className="transition-btn-primary flex-1 inline-flex items-center justify-center gap-[6px] p-[8px_12px] bg-[linear-gradient(135deg,#f59e0b_0%,#d97706_100%)] text-[#090d16] font-bold text-[11px] rounded-[7px] border-none cursor-pointer transition-[filter,background] duration-150 [box-shadow:0_1px_3px_rgba(0,0,0,0.2)] hover:brightness-110"
              onClick={handleOpenHandover}
            >
              <ExternalLink size={13} />
              <span>Buka Catatan Serah Terima (Handover)</span>
            </button>
            <Link href={paths.teamRoster}
              
              className="transition-btn-secondary inline-flex items-center justify-center gap-[5px] p-[8px_12px] bg-[rgba(255,255,255,0.05)] border border-[rgba(255,255,255,0.1)] text-[#e2e8f0] font-semibold text-[11px] rounded-[7px] cursor-pointer transition-all duration-150 hover:bg-[rgba(255,255,255,0.1)] hover:border-[rgba(255,255,255,0.2)] hover:text-[#ffffff]"
              onClick={() => setIsOpen(false)}
            >
              <Users size={13} />
              <span>Lihat Jadwal Tim</span>
            </Link>
          </div>
        </div>
      )}
    </div>
  );
}

