        </div>
      ) : viewMode === "card" ? (
        /* ── Cards View ── */
        <div className="grid grid-cols-3 max-[1200px]:grid-cols-2 max-[700px]:grid-cols-1 gap-4">
          {filteredClients.map((client) => {
            const isArchived = client.status === "archived";
