"use client";

import React, { useId } from "react";
import { AlertTriangle, Archive, RefreshCw, X } from "lucide-react";
import { Modal } from "@/app/components/ui/Modal";

interface ConfirmArchiveDialogProps {
  open: boolean;
  title: string;
  itemName: string;
  itemType: "klien" | "proyek" | "sistem";
  action: "archive" | "restore" | "deactivate";
  activeTicketsCount?: number;
  activeCheckpointsCount?: number;
  subItemsCount?: number;
  subItemLabel?: string;
  consequenceText?: string;
  onConfirm: () => void;
  onClose: () => void;
  isLoading?: boolean;
}

export function ConfirmArchiveDialog({
  open,
  title,
  itemName,
  itemType,
  action,
  activeTicketsCount = 0,
  activeCheckpointsCount = 0,
  subItemsCount = 0,
  subItemLabel = "proyek",
  consequenceText,
  onConfirm,
  onClose,
  isLoading = false,
}: ConfirmArchiveDialogProps) {
  const descId = useId();
  const isArchive = action === "archive" || action === "deactivate";
  const hasImpact = activeTicketsCount > 0 || activeCheckpointsCount > 0 || subItemsCount > 0;

  return (
    <Modal open={open} onClose={onClose} label={title} variant="centered" width={480}>
      <div className="flex flex-col gap-4">
        {/* Header */}
        <div className="flex items-start justify-between gap-3 pb-3 border-b border-slate-700/60">
          <div className="flex items-center gap-2.5">
            <span
              className={`inline-flex items-center justify-center w-8 h-8 rounded-lg ${
                isArchive
                  ? "bg-rose-500/15 border border-rose-500/30 text-rose-400"
                  : "bg-emerald-500/15 border border-emerald-500/30 text-emerald-400"
              }`}
            >
              {isArchive ? <AlertTriangle size={18} /> : <RefreshCw size={18} />}
            </span>
            <div>
              <h3 className="text-[15px] font-bold text-slate-100 leading-snug">{title}</h3>
              <p className="text-[12px] text-slate-400">
                Konfirmasi perubahan status {itemType}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-md text-slate-400 hover:text-slate-200 hover:bg-slate-800/80 transition-colors cursor-pointer"
            aria-label="Batal dan tutup"
          >
            <X size={16} />
          </button>
        </div>

        {/* Content Body */}
        <div className="flex flex-col gap-3 text-[13px] text-slate-300" id={descId}>
          <p>
            Apakah Anda yakin ingin {isArchive ? "mengarsipkan" : "mengaktifkan kembali"}{" "}
            <strong className="text-slate-100 font-semibold">{itemName}</strong>?
          </p>

          {isArchive && hasImpact && (
            <div className="p-3 rounded-lg bg-rose-950/40 border border-rose-500/30 flex flex-col gap-1.5 text-[12px]">
              <div className="flex items-center gap-1.5 font-bold text-rose-400">
                <AlertTriangle size={14} className="shrink-0" />
                <span>Peringatan Entitas Terkait:</span>
              </div>
              <ul className="list-disc list-inside space-y-1 text-slate-300 pl-1">
                {subItemsCount > 0 && (
                  <li>
                    Terdapat <strong className="text-amber-300">{subItemsCount} {subItemLabel}</strong> di bawah klien ini yang akan ikut disembunyikan dari pemilih.
                  </li>
                )}
                {activeTicketsCount > 0 && (
                  <li>
                    Terdapat <strong className="text-rose-300">{activeTicketsCount} tiket aktif</strong> yang masih merujuk ke entitas ini.
                  </li>
                )}
                {activeCheckpointsCount > 0 && (
                  <li>
                    Terdapat <strong className="text-amber-300">{activeCheckpointsCount} checkpoint jadwal shift</strong> terkait.
                  </li>
                )}
              </ul>
              <p className="text-[11.5px] text-slate-400 mt-1 italic">
                {consequenceText || "Entitas tidak akan dihapus permanen. Data historis, tiket lama, dan log audit tetap tersimpan utuh berlabel 'Arsip'."}
              </p>
            </div>
          )}

          {!isArchive && (
            <div className="p-3 rounded-lg bg-emerald-950/30 border border-emerald-500/30 text-[12px] text-slate-300">
              {itemType.toUpperCase()} ini akan kembali aktif dan langsung muncul di pemilih header, filter tiket, serta modul monitoring.
            </div>
          )}
        </div>

        {/* Footer Actions */}
        <div className="flex items-center justify-end gap-2.5 pt-3 border-t border-slate-700/60 mt-2">
          <button
            type="button"
            onClick={onClose}
            disabled={isLoading}
            className="px-3.5 py-2 rounded-lg text-[12.5px] font-semibold text-slate-300 bg-slate-800/80 border border-slate-700 hover:bg-slate-700 hover:text-white transition-all cursor-pointer"
          >
            Batal
          </button>
          <button
            type="button"
            onClick={onConfirm}
            disabled={isLoading}
            className={`inline-flex items-center gap-1.5 px-4 py-2 rounded-lg text-[12.5px] font-bold text-white transition-all cursor-pointer ${
              isArchive
                ? "bg-rose-600 hover:bg-rose-500 shadow-[0_0_12px_rgba(244,63,94,0.3)]"
                : "bg-emerald-600 hover:bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.3)]"
            } disabled:opacity-50 disabled:cursor-not-allowed`}
          >
            {isArchive ? <Archive size={14} /> : <RefreshCw size={14} />}
            <span>{isLoading ? "Memproses..." : isArchive ? "Ya, Arsipkan" : "Ya, Aktifkan"}</span>
          </button>
        </div>
      </div>
    </Modal>
  );
}

"use client";
import { useState, type KeyboardEvent } from "react";
import { Check, ChevronDown, Layers } from "lucide-react";
import { BottomSheet } from "@/app/components/ui/BottomSheet";
import { MASTER_LABELS, MASTER_GROUPS } from "@/app/lib/master-data-route";
import type { MasterEntity } from "@/app/types/master-data";
const groups: { key: keyof typeof MASTER_GROUPS; entities: MasterEntity[] }[] = [{ key: "services", entities: ["organization", "project", "system"] }, { key: "tickets", entities: ["category", "severity"] }];
function keyboard(event: KeyboardEvent<HTMLDivElement>) {
  if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
  const tabs = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('button[role="tab"]:not(:disabled)')];
  const index = tabs.indexOf(document.activeElement as HTMLButtonElement);
  const next = event.key === "Home" ? 0 : event.key === "End" ? tabs.length - 1 : (index + (event.key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length;
  event.preventDefault(); tabs[next]?.focus(); tabs[next]?.click();
}
export function MasterNavigation({ entity, onSelect }: { entity: MasterEntity; onSelect: (entity: MasterEntity) => void }) {
  const [open, setOpen] = useState(false);
  const group = groups.find(g => g.entities.includes(entity))!;
  return <>
    <div className="hidden space-y-3 lg:block">
      <div role="tablist" aria-label="Kelompok Master Data" onKeyDown={keyboard} className="inline-flex rounded-xl border border-slate-700 bg-slate-900 p-1">
        {groups.map(g => <button key={g.key} type="button" role="tab" aria-selected={group.key === g.key} tabIndex={group.key === g.key ? 0 : -1} onClick={() => onSelect(g.entities[0])} className={group.key === g.key ? "rounded-lg bg-slate-700 px-4 py-2.5 text-sm font-semibold text-slate-50" : "rounded-lg px-4 py-2.5 text-sm text-slate-300 hover:bg-slate-800"}>{MASTER_GROUPS[g.key]}</button>)}
        <button type="button" role="tab" disabled aria-disabled="true" aria-selected="false" tabIndex={-1} className="flex items-center gap-2 px-4 py-2.5 text-sm text-slate-400">Operasional <span className="rounded bg-slate-800 px-1.5 py-0.5 text-[11px]">Segera</span></button>
      </div>
      <div role="tablist" aria-label="Jenis Master Data" onKeyDown={keyboard} className="flex gap-1 border-b border-slate-700">
        {group.entities.map(key => <button type="button" key={key} role="tab" aria-selected={key === entity} tabIndex={key === entity ? 0 : -1} onClick={() => onSelect(key)} className={key === entity ? "border-b-2 border-sky-400 px-4 py-2.5 text-sm font-semibold text-sky-300" : "border-b-2 border-transparent px-4 py-2.5 text-sm text-slate-300 hover:text-slate-50"}>{MASTER_LABELS[key]}</button>)}
      </div>
    </div>
    <button type="button" onClick={() => setOpen(true)} aria-haspopup="dialog" aria-expanded={open} className="flex min-h-11 w-full items-center gap-2 rounded-xl border border-slate-600 bg-slate-800 px-3 text-left text-sm font-semibold text-slate-50 lg:hidden"><Layers size={17} className="shrink-0 text-sky-300" /><span className="min-w-0 flex-1 truncate">{MASTER_LABELS[entity]}</span><ChevronDown size={17} /></button>
    <BottomSheet open={open} onClose={() => setOpen(false)} title="Kategori Master Data" dataSheetId="master-category">
      <div className="space-y-5 px-1 pb-4">{groups.map(g => <section key={g.key}><h2 className="mb-2 px-3 text-xs font-semibold text-slate-400">{MASTER_GROUPS[g.key]}</h2>{g.entities.map(key => <button key={key} type="button" aria-current={entity === key ? "true" : undefined} onClick={() => { setOpen(false); onSelect(key); }} className="flex min-h-12 w-full items-center justify-between rounded-lg px-3 text-sm text-slate-100 hover:bg-slate-700"><span>{MASTER_LABELS[key]}</span>{entity === key && <Check size={18} className="text-sky-300" />}</button>)}</section>)}<button type="button" disabled aria-disabled="true" className="flex min-h-11 w-full justify-between px-3 text-sm text-slate-400">Operasional <span>Segera</span></button></div>
    </BottomSheet>
  </>;
}

"use client";

import React, { useEffect } from "react";
import { X, Layers, Building2, User, Cpu, ShieldCheck, Edit3, Archive, RefreshCw } from "lucide-react";
import type {
  ClientOrganization,
  ProjectMaster,
  SystemMaster,
} from "@/app/types/master-data";

interface ProjectDetailDrawerProps {
  project: ProjectMaster | null;
  client?: ClientOrganization;
  systems: SystemMaster[];
  checkpointCount?: number;
  onClose: () => void;
  onEdit: (project: ProjectMaster) => void;
  onToggleArchive: (project: ProjectMaster) => void;
}

export function ProjectDetailDrawer({
  project,
  client,
  systems,
  checkpointCount = 0,
  onClose,
  onEdit,
  onToggleArchive,
}: ProjectDetailDrawerProps) {
  useEffect(() => {
    if (!project) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [project, onClose]);

  if (!project) return null;

  const isArchived = project.status === "archived";

  return (
    <div
      className="fixed inset-0 z-[80] flex justify-end bg-black/60 backdrop-blur-[3px] animate-fade-in"
      role="dialog"
      aria-modal="true"
      aria-label={`Detail Proyek: ${project.name}`}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="w-[min(480px,calc(100vw-24px))] h-full bg-[#1e293b] border-l border-slate-700/80 shadow-2xl flex flex-col animate-slide-left text-slate-100 overflow-hidden">
        {/* Drawer Header */}
        <div className="p-4 border-b border-slate-700/70 bg-slate-900/60 flex items-start justify-between gap-3 shrink-0">
          <div className="flex items-center gap-2.5">
            <span className="p-2 rounded-lg bg-sky-500/10 border border-sky-500/25 text-sky-400">
              <Layers size={18} />
            </span>
            <div>
              <div className="flex items-center gap-2">
                <span className="text-[11px] font-mono font-bold text-sky-400 px-1.5 py-0.5 rounded bg-sky-500/10 border border-sky-500/20">
                  {project.code}
                </span>
                <span
                  className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider ${
                    isArchived
                      ? "bg-rose-500/15 text-rose-400 border border-rose-500/30"
                      : "bg-emerald-500/15 text-emerald-400 border border-emerald-500/30"
                  }`}
                >
                  {isArchived ? "Archived" : "Active"}
                </span>
              </div>
              <h2 className="text-[16px] font-bold text-slate-100 mt-1">{project.name}</h2>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-md text-slate-400 hover:text-white hover:bg-slate-800 transition-colors cursor-pointer"
            aria-label="Tutup panel detail"
          >
            <X size={16} />
          </button>
        </div>

        {/* Drawer Content */}
        <div className="flex-1 overflow-y-auto p-5 flex flex-col gap-5 [scrollbar-width:thin]">
          {/* Client Reference Card */}
          {client && (
            <div className="p-3.5 rounded-xl bg-slate-900/60 border border-slate-700/60 flex items-center justify-between gap-3">
              <div className="flex items-center gap-2.5 min-w-0">
                <span className="w-8 h-8 rounded-lg grid place-items-center bg-slate-800 text-slate-300 shrink-0">
                  <Building2 size={16} />
                </span>
                <div className="min-w-0">
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider block">Klien</span>
                  <span className="text-[12.5px] font-bold text-slate-200 truncate block">
                    {client.name}
                  </span>
                </div>
              </div>
              <span className="text-[11px] font-mono px-2 py-0.5 rounded bg-slate-800 text-sky-400 shrink-0">
                {client.code}
              </span>
            </div>
          )}

          {/* Key Properties */}
          <div className="grid grid-cols-2 gap-3 text-[12.5px]">
            <div className="p-3 rounded-lg bg-slate-900/40 border border-slate-800">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider block mb-1">
                Lead Engineer
              </span>
              <div className="flex items-center gap-1.5 text-slate-200 font-medium">
                <User size={13} className="text-sky-400 shrink-0" />
                <span className="truncate">{project.leadEngineer || "NOC Specialist"}</span>
              </div>
            </div>

            <div className="p-3 rounded-lg bg-slate-900/40 border border-slate-800">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider block mb-1">
                Checkpoints Shift
              </span>
              <div className="flex items-center gap-1.5 text-slate-200 font-medium">
                <ShieldCheck size={13} className="text-emerald-400 shrink-0" />
                <span>{checkpointCount} Checkpoint Terjadwal</span>
              </div>
            </div>
          </div>

          {/* Scope & Description */}
          <div>
            <h3 className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1.5">
              Lingkup Layanan &amp; Deskripsi
            </h3>
            <div className="p-3.5 rounded-lg bg-slate-900/50 border border-slate-700/60 text-[12.5px] text-slate-300 leading-relaxed">
              <p className="font-semibold text-slate-200 mb-1">{project.fullName}</p>
              <p>{project.detail || "Tidak ada rincian tambahan untuk proyek ini."}</p>
            </div>
          </div>

          {/* Linked Systems */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <h3 className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                Sistem Terkait ({systems.length})
              </h3>
            </div>
            {systems.length === 0 ? (
              <div className="p-4 rounded-lg border border-dashed border-slate-700 text-center text-[12px] text-slate-400">
                Belum ada sub-layanan/sistem yang didaftarkan untuk proyek ini.
              </div>
            ) : (
              <div className="flex flex-col gap-2">
                {systems.map((sys) => {
                  const critBadge =
                    sys.criticality === "critical"
                      ? "text-rose-400 bg-rose-500/10 border-rose-500/30"
                      : sys.criticality === "high"
                      ? "text-amber-400 bg-amber-500/10 border-amber-500/30"
                      : "text-sky-400 bg-sky-500/10 border-sky-500/30";

                  return (
                    <div
                      key={sys.id}
                      className="p-2.5 rounded-lg bg-slate-900/40 border border-slate-700/50 flex items-center justify-between gap-3 text-[12px]"
                    >
                      <div className="flex items-center gap-2 min-w-0">
                        <Cpu size={14} className="text-slate-400 shrink-0" />
                        <span className="font-semibold text-slate-200 truncate">{sys.name}</span>
                      </div>
                      <div className="flex items-center gap-1.5 shrink-0">
                        <span className="text-[10px] px-1.5 py-0.5 rounded bg-slate-800 text-slate-300 font-mono">
                          {sys.environment}
                        </span>
                        <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border uppercase ${critBadge}`}>
                          {sys.criticality}
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Drawer Footer Actions */}
        <div className="p-4 border-t border-slate-700/70 bg-slate-900/60 flex items-center justify-between gap-2 shrink-0">
          <button
            type="button"
            onClick={() => onToggleArchive(project)}
            className={`inline-flex items-center gap-1.5 px-3 py-2 rounded-lg text-[12px] font-semibold transition-colors cursor-pointer border ${
              isArchived
                ? "border-emerald-500/30 text-emerald-400 hover:bg-emerald-500/10"
                : "border-rose-500/30 text-rose-400 hover:bg-rose-500/10"
            }`}
          >
            {isArchived ? <RefreshCw size={13} /> : <Archive size={13} />}
            <span>{isArchived ? "Pulihkan Proyek" : "Arsipkan Proyek"}</span>
          </button>

          <button
            type="button"
            onClick={() => onEdit(project)}
            className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg text-[12px] font-bold text-white bg-sky-500 hover:bg-sky-400 shadow-[0_0_12px_rgba(56,189,248,0.25)] transition-all cursor-pointer"
          >
            <Edit3 size={13} />
            <span>Ubah Proyek</span>
          </button>
        </div>
      </div>
    </div>
  );
}

