"use client";

import { Select } from "@/app/components/ui/Select";

import React, { useState, useEffect, useRef } from "react";
import { Layers, X, Check, AlertCircle } from "lucide-react";
import { Modal } from "@/app/components/ui/Modal";
import type { ClientOrganization, ProjectMaster, CreateProjectInput, UpdateProjectInput, ProjectHealthDefault } from "@/app/types/master-data";

interface ProjectFormModalProps {
  open: boolean;
  initialData?: ProjectMaster | null;
  defaultClientId?: string;
  clients: readonly ClientOrganization[];
  existingProjects: readonly ProjectMaster[];
  onSave: (data: CreateProjectInput | UpdateProjectInput) => Promise<void>;
  onClose: () => void;
}

const HEALTH_OPTIONS: { value: ProjectHealthDefault; label: string; tone: string }[] = [
  { value: "healthy", label: "Healthy (Normal)", tone: "text-emerald-400" },
  { value: "degraded", label: "Degraded (Perlu Perhatian)", tone: "text-amber-400" },
  { value: "critical", label: "Critical (Gangguan)", tone: "text-rose-400" },
];

export function ProjectFormModal({
  open,
  initialData,
  defaultClientId,
  clients,
  existingProjects,
  onSave,
  onClose,
}: ProjectFormModalProps) {
  const isEdit = Boolean(initialData);

  const [clientId, setClientId] = useState(defaultClientId || clients[0]?.id || "tritronik");
  const [code, setCode] = useState("");
  const [name, setName] = useState("");
  const [fullName, setFullName] = useState("");
  const [detail, setDetail] = useState("");
  const [leadEngineer, setLeadEngineer] = useState("");
  const [healthDefault, setHealthDefault] = useState<ProjectHealthDefault>("healthy");

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const nameInputRef = useRef<HTMLInputElement>(null);
  const codeInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (open) {
      if (initialData) {
        setClientId(initialData.clientId);
        setCode(initialData.code);
        setName(initialData.name);
        setFullName(initialData.fullName || initialData.name);
        setDetail(initialData.detail || "");
        setLeadEngineer(initialData.leadEngineer || "");
        setHealthDefault(initialData.healthDefault || "healthy");
      } else {
        setClientId(defaultClientId || clients[0]?.id || "tritronik");
        setCode("");
        setName("");
        setFullName("");
        setDetail("");
        setLeadEngineer("NOC Lead Specialist");
        setHealthDefault("healthy");
      }
      setErrors({});
      setIsSubmitting(false);
    }
  }, [open, initialData, defaultClientId, clients]);

  const handleNameChange = (val: string) => {
    setName(val);
    if (!isEdit && (!code || code === name.toUpperCase().slice(0, 6))) {
      setCode(val.trim().toUpperCase().slice(0, 8));
    }
    if (errors.name) setErrors((prev) => ({ ...prev, name: "" }));
  };

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!clientId) {
      newErrors.clientId = "Klien wajib dipilih";
    }

    if (!name.trim()) {
      newErrors.name = "Nama proyek wajib diisi";
    }

    const codeTrimmed = code.trim().toUpperCase();
    if (!codeTrimmed) {
      newErrors.code = "Kode proyek wajib diisi";
    } else {
      // Check duplicate within the selected client
      const isDuplicate = existingProjects.some(
        (p) =>
          p.id !== initialData?.id &&
          p.clientId === clientId &&
          p.code.toUpperCase() === codeTrimmed,
      );
      if (isDuplicate) {
        newErrors.code = `Kode "${codeTrimmed}" sudah digunakan pada klien ini`;
      }
    }

    if (!detail.trim()) {
      newErrors.detail = "Deskripsi / lingkup layanan wajib diisi";
    }

    setErrors(newErrors);

    if (newErrors.name && nameInputRef.current) {
      nameInputRef.current.focus();
    } else if (newErrors.code && codeInputRef.current) {
      codeInputRef.current.focus();
    }

    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!validate() || isSubmitting) return;

    setIsSubmitting(true);
    try {
      const payload: CreateProjectInput | UpdateProjectInput = isEdit
        ? {
            name: name.trim(),
            fullName: fullName.trim() || name.trim(),
            code: code.trim().toUpperCase(),
            detail: detail.trim(),
            leadEngineer: leadEngineer.trim() || undefined,
            healthDefault,
          }
        : {
            clientId,
            name: name.trim(),
            fullName: fullName.trim() || name.trim(),
            code: code.trim().toUpperCase(),
            detail: detail.trim(),
            leadEngineer: leadEngineer.trim() || undefined,
            healthDefault,
          };

      await onSave(payload);
      onClose();
    } catch {
      // Handled in parent
    } finally {
      setIsSubmitting(false);
    }
  };

  const isDirty = isEdit
    ? clientId !== initialData?.clientId ||
      name !== initialData?.name ||
      fullName !== (initialData?.fullName || initialData?.name) ||
      code !== initialData?.code ||
      detail !== (initialData?.detail || "") ||
      leadEngineer !== (initialData?.leadEngineer || "") ||
      healthDefault !== (initialData?.healthDefault || "healthy")
    : name.length > 0 || code.length > 0 || detail.length > 0;

  const handleClose = () => {
    if (isDirty) {
      if (window.confirm("Ada perubahan data yang belum disimpan. Yakin ingin menutup form?")) {
        onClose();
      }
    } else {
      onClose();
    }
  };

  const isValid = name.trim().length > 0 && code.trim().length > 0 && detail.trim().length > 0;

  return (
    <Modal
      open={open}
      onClose={handleClose}
      label={isEdit ? "Ubah Data Proyek" : "Tambah Proyek Baru"}
      variant="form"
      width={600}
    >
      <form onSubmit={handleSubmit} className="flex flex-col h-full bg-[#1e293b] text-slate-100">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-slate-700/70 bg-slate-900/60 shrink-0">
          <div className="flex items-center gap-2.5">
            <span className="p-2 rounded-lg bg-sky-500/10 border border-sky-500/25 text-sky-400">
              <Layers size={18} />
            </span>
            <div>
              <h2 className="text-[15px] font-bold text-slate-100 leading-snug">
                {initialData ? `Ubah Proyek: ${initialData.name}` : "Tambah Proyek Layanan Baru"}
              </h2>
              <p className="text-[11.5px] text-slate-400">
                {initialData ? "Sesuaikan parameter proyek" : "Daftarkan proyek baru di bawah organisasi klien"}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={handleClose}
            className="p-1.5 rounded-md text-slate-400 hover:text-white hover:bg-slate-800 transition-colors cursor-pointer"
            aria-label="Tutup modal"
          >
            <X size={16} />
          </button>
        </div>

        {/* Body */}
        <div className="p-5 flex flex-col gap-4 overflow-y-auto max-h-[70vh] [scrollbar-width:thin]">
          {/* Baris 1: Klien Terkait & Status */}
          <div className="grid grid-cols-2 max-[540px]:grid-cols-1 gap-3.5">
            <div>
              <label htmlFor="project-client-select" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
                Organisasi Klien <span className="text-rose-400">*</span>
              </label>
              <Select
                id="project-client-select"
                value={clientId}
                onChange={(e) => {
                  setClientId(e.target.value);
                  if (errors.clientId) setErrors((prev) => ({ ...prev, clientId: "" }));
                }}
                disabled={isEdit}
                className="w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border border-slate-700 text-white focus:outline-none focus:border-sky-400 disabled:opacity-50 disabled:bg-slate-800 cursor-pointer"
              >
                {clients.map((c) => (
                  <option key={c.id} value={c.id} className="bg-slate-800 text-white">
                    {c.shortName || c.name} ({c.code})
                  </option>
                ))}
              </Select>
              {initialData && (
                <p className="text-[10px] text-slate-400 mt-1 font-mono">
                  ID: <span className="text-slate-300">{initialData.id}</span>
                </p>
              )}
            </div>

            <div>
              <label htmlFor="project-health-select" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
                Status Kesehatan Standar
              </label>
              <Select
                id="project-health-select"
                value={healthDefault}
                onChange={(e) => setHealthDefault(e.target.value as ProjectHealthDefault)}
                className="w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border border-slate-700 text-white focus:outline-none focus:border-sky-400 cursor-pointer"
              >
                {HEALTH_OPTIONS.map((h) => (
                  <option key={h.value} value={h.value} className="bg-slate-800 text-white">
                    {h.label}
                  </option>
                ))}
              </Select>
            </div>
          </div>

          {/* Baris 2: Nama & Kode Proyek */}
          <div className="grid grid-cols-2 max-[540px]:grid-cols-1 gap-3.5">
            <div>
              <label htmlFor="project-name-input" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
                Nama Singkat Proyek <span className="text-rose-400">*</span>
              </label>
              <input
                id="project-name-input"
                ref={nameInputRef}
                type="text"
                value={name}
                onChange={(e) => handleNameChange(e.target.value)}
                placeholder="Contoh: SM, EPC Core, B2B"
                aria-invalid={Boolean(errors.name)}
                className={`w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border ${
                  errors.name ? "border-rose-500" : "border-slate-700 focus:border-sky-400"
                } text-white focus:outline-none`}
              />
              {errors.name && <p className="text-[11px] text-rose-400 mt-1">{errors.name}</p>}
            </div>

            <div>
              <label htmlFor="project-code-input" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5 font-mono">
                Kode Proyek <span className="text-rose-400">*</span>
              </label>
              <input
                id="project-code-input"
                ref={codeInputRef}
                type="text"
                value={code}
                onChange={(e) => {
                  setCode(e.target.value.toUpperCase());
                  if (errors.code) setErrors((prev) => ({ ...prev, code: "" }));
                }}
                placeholder="Misal: SM, EPC"
                maxLength={10}
                aria-invalid={Boolean(errors.code)}
                className={`w-full h-[38px] px-3 rounded-lg text-[13px] font-mono font-bold bg-slate-900/80 border ${
                  errors.code ? "border-rose-500" : "border-slate-700 focus:border-sky-400"
                } text-white focus:outline-none`}
              />
              {errors.code && (
                <p className="text-[11px] text-rose-400 mt-1 flex items-center gap-1">
                  <AlertCircle size={12} /> {errors.code}
                </p>
              )}
            </div>
          </div>

          {/* Baris 3: Nama Lengkap & Lead Engineer */}
          <div className="grid grid-cols-2 max-[540px]:grid-cols-1 gap-3.5">
            <div>
              <label htmlFor="project-fullname-input" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
                Nama Lengkap Layanan
              </label>
              <input
                id="project-fullname-input"
                type="text"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                placeholder="Contoh: Service Management & Middleware"
                className="w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border border-slate-700 text-white focus:outline-none focus:border-sky-400"
              />
            </div>

            <div>
              <label htmlFor="project-lead-input" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
                Lead Engineer / PIC Teknis
              </label>
              <input
                id="project-lead-input"
                type="text"
                value={leadEngineer}
                onChange={(e) => setLeadEngineer(e.target.value)}
                placeholder="Contoh: Muhammad Ihsanul Arifin"
                className="w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border border-slate-700 text-white focus:outline-none focus:border-sky-400"
              />
            </div>
          </div>

          {/* Baris 4: Detail / Lingkup */}
          <div>
            <label htmlFor="project-detail-input" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
              Lingkup / Observasi Health Default <span className="text-rose-400">*</span>
            </label>
            <textarea
              id="project-detail-input"
              rows={2}
              value={detail}
              onChange={(e) => {
                setDetail(e.target.value);
                if (errors.detail) setErrors((prev) => ({ ...prev, detail: "" }));
              }}
              placeholder="Contoh: ActiveMQ queue buffer normal, throughput stabil 1.2k/s"
              aria-invalid={Boolean(errors.detail)}
              className={`w-full p-2.5 rounded-lg text-[12.5px] bg-slate-900/80 border ${
                errors.detail ? "border-rose-500" : "border-slate-700 focus:border-sky-400"
              } text-white focus:outline-none resize-none`}
            />
            {errors.detail && <p className="text-[11px] text-rose-400 mt-1">{errors.detail}</p>}
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between p-4 border-t border-slate-700/70 bg-slate-900/60 shrink-0">
          <p className="text-[11px] text-slate-400">
            <span className="text-rose-400">*</span> Wajib diisi
          </p>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handleClose}
              disabled={isSubmitting}
              className="px-3.5 py-1.5 rounded-lg text-[12px] font-semibold text-slate-300 bg-slate-800 border border-slate-700 hover:bg-slate-700 transition-colors cursor-pointer"
            >
              Batal
            </button>
            <button
              type="submit"
              disabled={!isValid || isSubmitting}
              className="inline-flex items-center gap-1.5 px-4 py-1.5 rounded-lg text-[12px] font-bold text-white bg-sky-500 hover:bg-sky-400 disabled:opacity-40 disabled:cursor-not-allowed transition-all shadow-[0_0_12px_rgba(56,189,248,0.3)] cursor-pointer"
            >
              <Check size={14} />
              <span>{isSubmitting ? "Menyimpan..." : isEdit ? "Perbarui Proyek" : "Simpan Proyek"}</span>
            </button>
          </div>
        </div>
      </form>
    </Modal>
  );
}

"use client";

import { Select } from "@/app/components/ui/Select";

import { useMemo } from "react";
import { Search, Plus, Layers, Edit3, Archive, RefreshCw, Eye, Building2, User, ShieldCheck } from "lucide-react";
import type { ClientOrganization, ProjectMaster, SystemMaster } from "@/app/types/master-data";
import type { MonitoringEntry } from "@/app/lib/types";

interface ProjectListTabProps {
  projects: readonly ProjectMaster[];
  clients: readonly ClientOrganization[];
  systems: readonly SystemMaster[];
  schedules?: MonitoringEntry[];
  selectedClientId: string;
  onSelectedClientIdChange: (id: string) => void;
  search: string;
  onSearchChange: (val: string) => void;
  statusFilter: string;
  onStatusFilterChange: (val: string) => void;
  onAddProject: () => void;
  onEditProject: (project: ProjectMaster) => void;
  onViewProjectDetail: (project: ProjectMaster) => void;
  onToggleArchive: (project: ProjectMaster) => void;
}

export function ProjectListTab({
  projects,
  clients,
  systems,
  schedules = [],
  selectedClientId,
  onSelectedClientIdChange,
  search,
  onSearchChange,
  statusFilter,
  onStatusFilterChange,
  onAddProject,
  onEditProject,
  onViewProjectDetail,
  onToggleArchive,
}: ProjectListTabProps) {
  // Clients map for quick lookup
  const clientsMap = useMemo(() => {
    return new Map(clients.map((c) => [c.id, c]));
  }, [clients]);

  // Compute checkpoints count per project
  const checkpointCounts = useMemo(() => {
    const map = new Map<string, number>();
    for (const item of schedules) {
      const current = map.get(item.project) || 0;
      map.set(item.project, current + 1);
    }
    return map;
  }, [schedules]);

  // Filtered projects
  const filteredProjects = useMemo(() => {
    return projects.filter((p) => {
      // Client filter
      if (selectedClientId && selectedClientId !== "all" && p.clientId !== selectedClientId) {
        return false;
      }
      // Status filter
      if (statusFilter !== "all" && p.status !== statusFilter) {
        return false;
      }
      // Search
      if (search.trim()) {
        const q = search.toLowerCase();
        const matchesName = p.name.toLowerCase().includes(q) || p.fullName.toLowerCase().includes(q);
        const matchesCode = p.code.toLowerCase().includes(q);
        const matchesDetail = p.detail.toLowerCase().includes(q);
        const matchesLead = (p.leadEngineer || "").toLowerCase().includes(q);
        return matchesName || matchesCode || matchesDetail || matchesLead;
      }
      return true;
    });
  }, [projects, selectedClientId, statusFilter, search]);

  const selectedClient = selectedClientId && selectedClientId !== "all" ? clientsMap.get(selectedClientId) : null;

  return (
    <div className="flex flex-col gap-4 w-full">
      {/* ── Toolbar ── */}
      <div className="flex items-center justify-between gap-3 flex-wrap p-3 rounded-xl bg-slate-900/60 border border-slate-700/60">
        <div className="flex items-center gap-2.5 flex-1 min-w-[260px] max-w-[500px]">
          {/* Client Filter */}
          <div className="w-[180px] shrink-0">
            <Select
              value={selectedClientId || "all"}
              onChange={(e) => onSelectedClientIdChange(e.target.value)}
              aria-label="Filter berdasarkan klien"
              className="w-full h-[36px] px-3 rounded-lg text-[12px] bg-slate-800/80 border border-slate-700/80 text-slate-200 focus:outline-none focus:border-sky-400 cursor-pointer font-medium"
            >
              <option value="all">Semua Klien ({clients.length})</option>
              {clients.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.shortName || c.name} ({c.code})
                </option>
              ))}
            </Select>
          </div>

          {/* Search */}
          <div className="relative w-full">
            <Search
              size={15}
              className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"
              aria-hidden="true"
            />
            <input
              type="text"
              value={search}
              onChange={(e) => onSearchChange(e.target.value)}
              placeholder="Cari kode, nama proyek, lingkup..."
              aria-label="Cari proyek"
              className="w-full h-[36px] pl-9 pr-3 rounded-lg text-[12.5px] bg-slate-800/80 border border-slate-700/80 text-white placeholder-slate-400 focus:outline-none focus:border-sky-400 transition-colors"
            />
          </div>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          {/* Status Filter */}
          <Select
            value={statusFilter}
            onChange={(e) => onStatusFilterChange(e.target.value)}
            aria-label="Filter status proyek"
            className="h-[36px] px-3 rounded-lg text-[12px] bg-slate-800/80 border border-slate-700/80 text-slate-200 focus:outline-none focus:border-sky-400 cursor-pointer"
          >
            <option value="all">Semua Status ({projects.length})</option>
            <option value="active">Aktif ({projects.filter((p) => p.status === "active").length})</option>
            <option value="archived">Arsip ({projects.filter((p) => p.status === "archived").length})</option>
          </Select>

          {/* Add Project Button */}
          <button
            type="button"
            onClick={onAddProject}
            className="inline-flex items-center gap-1.5 h-[36px] px-3.5 rounded-lg text-[12px] font-bold text-white bg-sky-500 hover:bg-sky-400 transition-all shadow-[0_0_12px_rgba(56,189,248,0.25)] cursor-pointer"
          >
            <Plus size={15} />
            <span>Proyek Baru</span>
          </button>
        </div>
      </div>

      {/* ── Table & Cards View ── */}
      {filteredProjects.length === 0 ? (
        <div className="p-12 text-center rounded-xl bg-slate-900/40 border border-slate-800 flex flex-col items-center justify-center gap-3">
          <span className="p-3 rounded-full bg-slate-800 text-slate-400">
            <Layers size={24} />
          </span>
          <p className="text-[14px] font-bold text-slate-200">
            {selectedClient ? `Belum ada proyek untuk ${selectedClient.name}` : "Tidak ada proyek ditemukan"}
          </p>
          <p className="text-[12px] text-slate-400 max-w-sm">
            {search || statusFilter !== "all"
              ? "Coba ubah kata kunci pencarian atau sesuaikan filter status."
              : selectedClient
              ? "Mulai dengan membuat proyek pertama untuk klien ini agar muncul pada monitoring dashboard."
              : "Belum ada data proyek terdaftar."}
          </p>
          {selectedClient && !search && statusFilter === "all" ? (
            <button
              type="button"
              onClick={onAddProject}
              className="mt-1 inline-flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-[12px] font-bold text-white bg-sky-500 hover:bg-sky-400 transition-all shadow-[0_0_12px_rgba(56,189,248,0.25)] cursor-pointer"
            >
              <Plus size={14} />
              <span>Buat Proyek Pertama</span>
            </button>
          ) : (
            (search || statusFilter !== "all") && (
              <button
                type="button"
                onClick={() => {
                  onSearchChange("");
                  onStatusFilterChange("all");
                }}
                className="mt-1 px-3 py-1.5 rounded-lg text-[12px] font-semibold text-sky-400 bg-sky-500/10 border border-sky-500/25 hover:bg-sky-500/20 transition-colors cursor-pointer"
              >
                Reset Filter
              </button>
            )
          )}
        </div>
      ) : (
        <div className="rounded-xl border border-slate-700/60 bg-slate-900/60 overflow-hidden shadow-lg">
          <div className="overflow-x-auto [scrollbar-width:thin]">
            <table className="w-full text-left border-collapse text-[12.5px]">
              <thead>
                <tr className="border-b border-slate-700/80 bg-slate-900/90 text-slate-400 font-bold text-[11px] uppercase tracking-wider">
                  <th className="p-3.5">Kode &amp; Proyek</th>
                  <th className="p-3.5">Klien Terkait</th>
                  <th className="p-3.5">Lead / PIC</th>
                  <th className="p-3.5">Lingkup Layanan</th>
                  <th className="p-3.5 text-center">Checkpoint</th>
                  <th className="p-3.5">Status</th>
                  <th className="p-3.5 text-right">Aksi</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/80">
                {filteredProjects.map((project) => {
                  const client = clientsMap.get(project.clientId);
                  const isArchived = project.status === "archived";
                  const checkpoints = checkpointCounts.get(project.name) || 0;

                  return (
                    <tr key={project.id} className="hover:bg-slate-800/40 transition-colors">
                      <td className="p-3.5">
                        <div className="flex items-center gap-2">
                          <span className="font-mono text-[11px] font-bold px-1.5 py-0.5 rounded bg-sky-500/10 text-sky-400 border border-sky-500/20">
                            {project.code}
                          </span>
                          <span className="font-bold text-slate-100">{project.name}</span>
                        </div>
                      </td>

                      <td className="p-3.5">
                        {client ? (
                          <span className="inline-flex items-center gap-1.5 text-[12px] text-slate-300 font-medium">
                            <Building2 size={12} className="text-slate-400 shrink-0" />
                            <span>{client.shortName || client.name}</span>
                          </span>
                        ) : (
                          <span className="text-slate-400">-</span>
                        )}
                      </td>

                      <td className="p-3.5">
                        <span className="text-slate-300 font-medium flex items-center gap-1.5">
                          <User size={12} className="text-sky-400 shrink-0" />
                          <span>{project.leadEngineer || "NOC Specialist"}</span>
                        </span>
                      </td>

                      <td className="p-3.5 max-w-[280px]">
                        <span className="text-slate-300 line-clamp-1 text-[12px]" title={project.detail}>
                          {project.detail}
                        </span>
                      </td>

                      <td className="p-3.5 text-center">
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-slate-800 text-slate-300 text-[11px] font-mono font-medium">
                          <ShieldCheck size={11} className="text-emerald-400" />
                          <span>{checkpoints}</span>
                        </span>
                      </td>

                      <td className="p-3.5">
                        <span
                          className={`text-[10px] font-bold px-2 py-0.5 rounded uppercase tracking-wider ${
                            isArchived
                              ? "bg-rose-500/20 text-rose-300 border border-rose-500/40"
                              : "bg-emerald-500/20 text-emerald-300 border border-emerald-500/40"
                          }`}
                        >
                          {project.status}
                        </span>
                      </td>

                      <td className="p-3.5 text-right">
                        <div className="inline-flex items-center gap-1.5 justify-end">
                          <button
                            type="button"
                            onClick={() => onViewProjectDetail(project)}
                            className="p-1.5 rounded-md text-slate-400 hover:text-sky-400 hover:bg-slate-800 transition-colors cursor-pointer"
                            title="Rincian Proyek"
                            aria-label={`Rincian proyek ${project.name}`}
                          >
                            <Eye size={14} />
                          </button>
                          <button
                            type="button"
                            onClick={() => onEditProject(project)}
                            className="p-1.5 rounded-md text-slate-400 hover:text-white hover:bg-slate-800 transition-colors cursor-pointer"
                            title="Ubah Proyek"
                            aria-label={`Ubah proyek ${project.name}`}
                          >
                            <Edit3 size={14} />
                          </button>
                          <button
                            type="button"
                            onClick={() => onToggleArchive(project)}
                            className={`p-1.5 rounded-md transition-colors cursor-pointer ${
                              isArchived
                                ? "text-emerald-400 hover:bg-emerald-500/10"
                                : "text-rose-400 hover:bg-rose-500/10"
                            }`}
                            title={isArchived ? "Pulihkan proyek" : "Arsipkan proyek"}
                            aria-label={isArchived ? "Pulihkan proyek" : "Arsipkan proyek"}
                          >
                            {isArchived ? <RefreshCw size={14} /> : <Archive size={14} />}
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

