"use client";

import { Select } from "@/app/components/ui/Select";

import React, { useState, useEffect, useRef, useMemo } from "react";
import { Cpu, X, Check, AlertCircle } from "lucide-react";
import { Modal } from "@/app/components/ui/Modal";
import type { ClientOrganization, ProjectMaster, SystemMaster, CreateSystemInput, UpdateSystemInput, SystemCriticality, SystemEnvironment, SystemStatus } from "@/app/types/master-data";

interface SystemFormModalProps {
  open: boolean;
  initialData?: SystemMaster | null;
  defaultClientId?: string;
  defaultProjectId?: string;
  clients: readonly ClientOrganization[];
  projects: readonly ProjectMaster[];
  onSave: (data: CreateSystemInput | UpdateSystemInput) => Promise<void>;
  onClose: () => void;
}

const CRITICALITY_OPTIONS: { value: SystemCriticality; label: string; badge: string }[] = [
  { value: "critical", label: "Critical", badge: "bg-rose-500/20 text-rose-400 border border-rose-500/30" },
  { value: "high", label: "High", badge: "bg-amber-500/20 text-amber-400 border border-amber-500/30" },
  { value: "medium", label: "Medium", badge: "bg-sky-500/20 text-sky-400 border border-sky-500/30" },
  { value: "low", label: "Low", badge: "bg-slate-500/20 text-slate-400 border border-slate-500/30" },
];

const ENVIRONMENT_OPTIONS: SystemEnvironment[] = ["Production", "Staging", "DRC"];
const STATUS_OPTIONS: SystemStatus[] = ["active", "maintenance", "deprecated"];

export function SystemFormModal({
  open,
  initialData,
  defaultClientId,
  defaultProjectId,
  clients,
  projects,
  onSave,
  onClose,
}: SystemFormModalProps) {
  const isEdit = Boolean(initialData);

  const [clientId, setClientId] = useState(defaultClientId || clients[0]?.id || "tritronik");
  const [projectId, setProjectId] = useState(defaultProjectId || "");
  const [name, setName] = useState("");
  const [criticality, setCriticality] = useState<SystemCriticality>("high");
  const [environment, setEnvironment] = useState<SystemEnvironment>("Production");
  const [status, setStatus] = useState<SystemStatus>("active");

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const nameInputRef = useRef<HTMLInputElement>(null);

  // Available projects for the selected client
  const availableProjects = useMemo(() => {
    return projects.filter((p) => p.clientId === clientId && p.status === "active");
  }, [projects, clientId]);

  useEffect(() => {
    if (open) {
      if (initialData) {
        setClientId(initialData.clientId);
        setProjectId(initialData.projectId);
        setName(initialData.name);
        setCriticality(initialData.criticality);
        setEnvironment(initialData.environment);
        setStatus(initialData.status);
      } else {
        const initClient = defaultClientId || clients[0]?.id || "tritronik";
        setClientId(initClient);
        const clientProjs = projects.filter((p) => p.clientId === initClient && p.status === "active");
        setProjectId(defaultProjectId || clientProjs[0]?.id || "");
        setName("");
        setCriticality("high");
        setEnvironment("Production");
        setStatus("active");
      }
      setErrors({});
      setIsSubmitting(false);
    }
  }, [open, initialData, defaultClientId, defaultProjectId, clients, projects]);

  // When client changes, auto-select first available project if current project doesn't belong to it
  const handleClientChange = (newClientId: string) => {
    setClientId(newClientId);
    const matched = projects.filter((p) => p.clientId === newClientId && p.status === "active");
    if (!matched.some((p) => p.id === projectId)) {
      setProjectId(matched[0]?.id || "");
    }
  };

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!clientId) newErrors.clientId = "Klien wajib dipilih";
    if (!projectId) newErrors.projectId = "Proyek wajib dipilih";
    if (!name.trim()) newErrors.name = "Nama sistem wajib diisi";

    setErrors(newErrors);

    if (newErrors.name && nameInputRef.current) {
      nameInputRef.current.focus();
    }

    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!validate() || isSubmitting) return;

    setIsSubmitting(true);
    try {
      const payload: CreateSystemInput | UpdateSystemInput = isEdit
        ? {
            name: name.trim(),
            projectId,
            criticality,
            environment,
            status,
          }
        : {
            clientId,
            projectId,
            name: name.trim(),
            criticality,
            environment,
            status,
          };

      await onSave(payload);
      onClose();
    } catch {
      // Error handled in parent
    } finally {
      setIsSubmitting(false);
    }
  };

  const isDirty = isEdit
    ? clientId !== initialData?.clientId ||
      projectId !== initialData?.projectId ||
      name !== initialData?.name ||
      criticality !== initialData?.criticality ||
      environment !== initialData?.environment ||
      status !== (initialData?.status || "active")
    : name.length > 0;

  const handleClose = () => {
    if (isDirty) {
      if (window.confirm("Ada perubahan data yang belum disimpan. Yakin ingin menutup form?")) {
        onClose();
      }
    } else {
      onClose();
    }
  };

  const isValid = name.trim().length > 0 && Boolean(projectId);

  return (
    <Modal
      open={open}
      onClose={handleClose}
      label={isEdit ? "Ubah Data Sistem" : "Tambah Sistem Baru"}
      variant="form"
      width={560}
    >
      <form onSubmit={handleSubmit} className="flex flex-col h-full bg-[#1e293b] text-slate-100">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-slate-700/70 bg-slate-900/60 shrink-0">
          <div className="flex items-center gap-2.5">
            <span className="p-2 rounded-lg bg-sky-500/10 border border-sky-500/25 text-sky-400">
              <Cpu size={18} />
            </span>
            <div>
              <h2 className="text-[15px] font-bold text-slate-100 leading-snug">
                {initialData ? `Ubah Sistem: ${initialData.name}` : "Tambah Sistem / Modul Baru"}
              </h2>
              <p className="text-[11.5px] text-slate-400">
                {initialData ? "Perbarui informasi sub-layanan" : "Daftarkan komponen sistem yang dimonitor"}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={handleClose}
            className="p-1.5 rounded-md text-slate-400 hover:text-white hover:bg-slate-800 transition-colors cursor-pointer"
            aria-label="Tutup modal"
          >
            <X size={16} />
          </button>
        </div>

        {/* Body */}
        <div className="p-5 flex flex-col gap-4 overflow-y-auto max-h-[70vh] [scrollbar-width:thin]">
          {/* Cascaded Row: Klien & Proyek */}
          <div className="grid grid-cols-2 max-[540px]:grid-cols-1 gap-3.5">
            <div>
              <label htmlFor="system-client-select" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
                Klien <span className="text-rose-400">*</span>
              </label>
              <Select
                id="system-client-select"
                value={clientId}
                onChange={(e) => handleClientChange(e.target.value)}
                disabled={isEdit}
                className="w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border border-slate-700 text-white focus:outline-none focus:border-sky-400 disabled:opacity-50 cursor-pointer"
              >
                {clients.map((c) => (
                  <option key={c.id} value={c.id} className="bg-slate-800 text-white">
                    {c.shortName || c.name}
                  </option>
                ))}
              </Select>
            </div>

            <div>
              <label htmlFor="system-project-select" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
                Proyek Terkait <span className="text-rose-400">*</span>
              </label>
              <Select
                id="system-project-select"
                value={projectId}
                onChange={(e) => {
                  setProjectId(e.target.value);
                  if (errors.projectId) setErrors((prev) => ({ ...prev, projectId: "" }));
                }}
                className="w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border border-slate-700 text-white focus:outline-none focus:border-sky-400 cursor-pointer"
              >
                {availableProjects.length === 0 ? (
                  <option value="" disabled>Belum ada proyek aktif</option>
                ) : (
                  availableProjects.map((p) => (
                    <option key={p.id} value={p.id} className="bg-slate-800 text-white">
                      {p.name} ({p.code})
                    </option>
                  ))
                )}
              </Select>
              {errors.projectId && <p className="text-[11px] text-rose-400 mt-1">{errors.projectId}</p>}
            </div>
          </div>

          {/* Nama Sistem */}
          <div>
            <label htmlFor="system-name-input" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
              Nama Sistem / Sub-Layanan <span className="text-rose-400">*</span>
            </label>
            <input
              id="system-name-input"
              ref={nameInputRef}
              type="text"
              value={name}
              onChange={(e) => {
                setName(e.target.value);
                if (errors.name) setErrors((prev) => ({ ...prev, name: "" }));
              }}
              placeholder="Contoh: OCS Billing, Switching ATM, Kafka SIEM"
              aria-invalid={Boolean(errors.name)}
              className={`w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border ${
                errors.name ? "border-rose-500" : "border-slate-700 focus:border-sky-400"
              } text-white focus:outline-none`}
            />
            {errors.name && (
              <p className="text-[11px] text-rose-400 mt-1 flex items-center gap-1">
                <AlertCircle size={12} /> {errors.name}
              </p>
            )}
          </div>

          {/* Baris 3: Kriticalitas & Environment */}
          <div className="grid grid-cols-2 max-[540px]:grid-cols-1 gap-3.5">
            <div>
              <label htmlFor="system-criticality-select" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
                Kriticalitas Layanan
              </label>
              <Select
                id="system-criticality-select"
                value={criticality}
                onChange={(e) => setCriticality(e.target.value as SystemCriticality)}
                className="w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border border-slate-700 text-white focus:outline-none focus:border-sky-400 cursor-pointer"
              >
                {CRITICALITY_OPTIONS.map((c) => (
                  <option key={c.value} value={c.value} className="bg-slate-800 text-white">
                    {c.label}
                  </option>
                ))}
              </Select>
            </div>

            <div>
              <label htmlFor="system-env-select" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
                Environment
              </label>
              <Select
                id="system-env-select"
                value={environment}
                onChange={(e) => setEnvironment(e.target.value as SystemEnvironment)}
                className="w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border border-slate-700 text-white focus:outline-none focus:border-sky-400 cursor-pointer"
              >
                {ENVIRONMENT_OPTIONS.map((env) => (
                  <option key={env} value={env} className="bg-slate-800 text-white">
                    {env}
                  </option>
                ))}
              </Select>
            </div>
          </div>

          {/* Status jika edit */}
          {isEdit && (
            <div>
              <label htmlFor="system-status-select" className="block text-[11px] font-bold uppercase tracking-wider text-slate-300 mb-1.5">
                Status Operasional
              </label>
              <Select
                id="system-status-select"
                value={status}
                onChange={(e) => setStatus(e.target.value as SystemStatus)}
                className="w-full h-[38px] px-3 rounded-lg text-[13px] bg-slate-900/80 border border-slate-700 text-white focus:outline-none focus:border-sky-400 cursor-pointer"
              >
                {STATUS_OPTIONS.map((s) => (
                  <option key={s} value={s} className="bg-slate-800 text-white capitalize">
                    {s}
                  </option>
                ))}
              </Select>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between p-4 border-t border-slate-700/70 bg-slate-900/60 shrink-0">
          <p className="text-[11px] text-slate-400">
            <span className="text-rose-400">*</span> Wajib diisi
          </p>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handleClose}
              disabled={isSubmitting}
              className="px-3.5 py-1.5 rounded-lg text-[12px] font-semibold text-slate-300 bg-slate-800 border border-slate-700 hover:bg-slate-700 transition-colors cursor-pointer"
            >
              Batal
            </button>
            <button
              type="submit"
              disabled={!isValid || isSubmitting}
              className="inline-flex items-center gap-1.5 px-4 py-1.5 rounded-lg text-[12px] font-bold text-white bg-sky-500 hover:bg-sky-400 disabled:opacity-40 disabled:cursor-not-allowed transition-all shadow-[0_0_12px_rgba(56,189,248,0.3)] cursor-pointer"
            >
              <Check size={14} />
              <span>{isSubmitting ? "Menyimpan..." : isEdit ? "Perbarui Sistem" : "Simpan Sistem"}</span>
            </button>
          </div>
        </div>
      </form>
    </Modal>
  );
}

"use client";
import { paths } from "@/app/lib/routes";
import { useUrlQuery, useUrlSearch } from "@/app/hooks/useUrlQuery";
import { monitoringSchema } from "@/app/lib/query-state";
import { getClientProjects } from "@/app/lib/clientData";
import { CLIENT_MONITORING_SYSTEMS } from "@/app/components/dashboard/MonitoringSchedule";

import { useMemo, useCallback } from "react";
import { Search, Download, User, X, Check } from "lucide-react";
import { DatePicker } from "@/app/components/ui/DatePicker";
import { ProjectMark } from "@/app/components/ui/ProjectMark";
import { EmptyState } from "@/app/components/ui/EmptyState";
import { PaginationBar } from "@/app/components/ui/PaginationBar";
import { useToast } from "@/app/components/ui/Toast";
import { getOwnerRole } from "@/app/lib/data";
import type { CheckpointAssessment, HistoricalAssessmentEntry, MonitoringEntry } from "@/app/lib/types";
import { useClient } from "@/app/context/ClientContext";
import { getClientHistoricalAssessments } from "@/app/lib/clientData";

interface MonitoringHistorySectionProps {
  todayEntries: MonitoringEntry[];
  todayAssessments: Record<string, CheckpointAssessment>;
}

const MONTH_NAMES_ID = [
  "Januari",
  "Februari",
  "Maret",
  "April",
  "Mei",
  "Juni",
  "Juli",
  "Agustus",
  "September",
  "Oktober",
  "November",
  "Desember",
];

function formatDateHeader(dateStr: string) {
  const today = "2026-08-31";
  const yesterday = "2026-08-30";
  if (dateStr === today) return "Hari Ini · 31 Agustus 2026 (Shift Malam)";
  if (dateStr === yesterday) return "Kemarin · 30 Agustus 2026 (Shift Pagi & Malam)";

  const parts = dateStr.split("-");
  if (parts.length === 3) {
    const day = parseInt(parts[2], 10);
    const mIdx = parseInt(parts[1], 10) - 1;
    const year = parts[0];
    const month = MONTH_NAMES_ID[mIdx] || parts[1];
    return `${day} ${month} ${year}`;
  }
  return dateStr;
}

export function MonitoringHistorySection({ todayEntries, todayAssessments }: MonitoringHistorySectionProps) {
  const { activeClientId } = useClient();
  const seedHistorical = useMemo(() => getClientHistoricalAssessments(activeClientId), [activeClientId]);
  const notify = useToast();
  const schema = useMemo(() => monitoringSchema(getClientProjects(activeClientId).map(p => p.name), CLIENT_MONITORING_SYSTEMS[activeClientId] ?? CLIENT_MONITORING_SYSTEMS.tritronik), [activeClientId]);
  const url = useUrlQuery(schema, paths.monitoring);
  const searchDraft = useUrlSearch(url.values.q, url.field("q"));
  const searchQuery = searchDraft.effective;
  const setSearchQuery = searchDraft.set;
  const verdictFilter = url.values.verdict;
  const setVerdictFilter = url.field("verdict", "replace");
  const dateFilter = url.values.date;
  const setDateFilter = url.field("date", "replace");

  // Pagination state (default: 10 rows per page)
  const pageSize = url.values.size;
  const setPageSize = url.field("size", "replace");
  const currentPage = url.values.page;
  const setCurrentPage = url.field("page", "push");

  // Reset pagination to page 1 whenever any filter changes


  // Merge today's live assessments into the history list
  const allHistory = useMemo(() => {
    const liveTodayRecords: HistoricalAssessmentEntry[] = [];

    // Generate records from today's live assessments
    Object.entries(todayAssessments).forEach(([key, assessment]) => {
      const match = todayEntries.find((e) => `${e.time}-${e.project}-${e.task}` === key);
      if (match) {
        liveTodayRecords.push({
          id: `live-${key}`,
          date: "2026-08-31",
          time: match.time,
          project: match.project,
          task: match.task,
          owner: match.owner,
          verdict: assessment.verdict === "ok" || assessment.verdict === "adequate" ? "ok" : "nok",
          note: assessment.note || (assessment.verdict === "ok" ? "Evaluasi status normal terverifikasi." : "Anomali terdeteksi."),
        });
      }
    });

    // Combine with seed historical assessments (avoid duplicates if matching today's key)
    const filteredSeed = seedHistorical.filter(
      (seed) => !liveTodayRecords.some((live) => live.time === seed.time && live.project === seed.project && live.date === seed.date)
    );

    const merged = [...liveTodayRecords, ...filteredSeed];

    // Sort by date DESC, then time DESC
    return merged.sort((a, b) => {
      if (a.date !== b.date) return b.date.localeCompare(a.date);
      return b.time.localeCompare(a.time);
    });
  }, [todayEntries, todayAssessments]);

  // Apply Date and Search Query filters (for top summary counts)
  const dateAndSearchFiltered = useMemo(() => {
    return allHistory.filter((entry) => {
      // Date filter (single date or range)
      if (dateFilter) {
        if (dateFilter.includes("..")) {
          const [start, end] = dateFilter.split("..");
          if (start && entry.date < start) return false;
          if (end && entry.date > end) return false;
        } else {
          if (entry.date !== dateFilter) return false;
        }
      }

      // Search text filter
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase().trim();
        const haystack = `${entry.project} ${entry.task} ${entry.owner} ${entry.note} ${entry.time} ${entry.verdict}`.toLowerCase();
        if (!haystack.includes(q)) return false;
      }

      return true;
    });
  }, [allHistory, dateFilter, searchQuery]);

  // Top summary counts across all pages for the current search/date filters
  const totalFilteredCount = dateAndSearchFiltered.length;
  const okFilteredCount = useMemo(
    () => dateAndSearchFiltered.filter((i) => i.verdict === "ok").length,
    [dateAndSearchFiltered]
  );
  const nokFilteredCount = useMemo(
    () => dateAndSearchFiltered.filter((i) => i.verdict === "nok").length,
    [dateAndSearchFiltered]
  );

  // Apply verdict filter
  const filteredHistory = useMemo(() => {
    if (verdictFilter === "all") return dateAndSearchFiltered;
    return dateAndSearchFiltered.filter((entry) => entry.verdict === verdictFilter);
  }, [dateAndSearchFiltered, verdictFilter]);

  // Pagination calculations
  const totalCount = filteredHistory.length;
  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize));
  const safeCurrentPage = Math.min(Math.max(1, currentPage), totalPages);
  const startIdx = (safeCurrentPage - 1) * pageSize;
  const endIdx = Math.min(startIdx + pageSize, totalCount);
  const paginatedHistory = useMemo(
    () => filteredHistory.slice(startIdx, endIdx),
    [filteredHistory, startIdx, endIdx]
  );

  const pageNumbers = useMemo(() => {
    const pages: (number | "...")[] = [];
    if (totalPages <= 7) {
      for (let i = 1; i <= totalPages; i++) pages.push(i);
    } else {
      pages.push(1);
      if (safeCurrentPage > 3) pages.push("...");
      const start = Math.max(2, safeCurrentPage - 1);
      const end = Math.min(totalPages - 1, safeCurrentPage + 1);
      for (let i = start; i <= end; i++) pages.push(i);
      if (safeCurrentPage < totalPages - 2) pages.push("...");
      pages.push(totalPages);
    }
    return pages;
  }, [totalPages, safeCurrentPage]);

  // Precompute per-date summary stats across the filtered dataset
  const dateStatsMap = useMemo(() => {
    const map = new Map<string, { ok: number; nok: number; total: number }>();
    filteredHistory.forEach((item) => {
      const s = map.get(item.date) || { ok: 0, nok: 0, total: 0 };
      s.total += 1;
      if (item.verdict === "ok") s.ok += 1;
      else if (item.verdict === "nok") s.nok += 1;
      map.set(item.date, s);
    });
    return map;
  }, [filteredHistory]);

  // Group paginated items sequentially by date
  const groupedPageEntries = useMemo(() => {
    const groups: Array<{
      date: string;
      header: string;
      items: HistoricalAssessmentEntry[];
    }> = [];
    let currentGroup: {
      date: string;
      header: string;
      items: HistoricalAssessmentEntry[];
    } | null = null;

    for (const entry of paginatedHistory) {
      if (!currentGroup || currentGroup.date !== entry.date) {
        currentGroup = {
          date: entry.date,
          header: formatDateHeader(entry.date),
          items: [entry],
        };
        groups.push(currentGroup);
      } else {
        currentGroup.items.push(entry);
      }
    }
    return groups;
  }, [paginatedHistory]);

  // Export to CSV Function (exports full filtered dataset across all pages)
  const handleExportCSV = useCallback(() => {
    if (filteredHistory.length === 0) {
      notify.warning("Tidak ada data riwayat yang dapat diekspor.", { id: "export-empty" });
      return;
    }

    const headers = ["ID", "Tanggal", "Waktu", "Project / Sistem", "Tugas Checkpoint", "Status Verdict", "Pemeriksa", "Peran", "Catatan Anomali"];
    const csvRows = [
      headers.join(","),
      ...filteredHistory.map((row) => {
        const clean = (text: string) => `"${(text || "").replace(/"/g, '""')}"`;
        return [
          clean(row.id),
          clean(row.date),
          clean(row.time),
          clean(row.project),
          clean(row.task),
          clean(row.verdict.toUpperCase()),
          clean(row.owner),
          clean(getOwnerRole(row.owner)),
          clean(row.note),
        ].join(",");
      }),
    ];

    const blob = new Blob([csvRows.join("\n")], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `checkpoint-assessment-history-${new Date().toISOString().slice(0, 10)}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    notify.success(`${filteredHistory.length} entri riwayat checkpoint berhasil diekspor ke CSV.`, {
      id: "export-success",
    });
  }, [filteredHistory, notify]);

  return (
    <article className="[background:var(--panel-bg)] [border:1px_solid_var(--panel-border)] rounded-[10px] [box-shadow:var(--shadow-panel)] [scroll-margin-top:var(--sticky-content-offset)] [margin-top:24px] mb-5 min-[1920px]:-mb-9">
      {/* 1. Header & Title */}
      <div className="rounded-t-[10px] [display:flex] [align-items:center] [justify-content:space-between] [gap:14px] [flex-wrap:wrap] [padding:var(--space-4)_var(--space-5)] [border-bottom:1px_solid_var(--line)]">
        <div>
          <div className="panel-title">Riwayat Asesmen Checkpoint</div>
        </div>

        <div className="history-head-actions">
          <button
            type="button"
            className="[height:30px] [display:inline-flex] [align-items:center] [justify-content:center] [gap:6px] [padding:0_10px] [border-radius:7px] [font-size:12px]! [font-weight:600] [transition:all_0.15s_ease] [color:var(--ink-primary)] [border:1px_solid_var(--panel-border)]! [background:var(--panel-bg)]! hover:[background:var(--panel-bg-hover)]!"
            onClick={handleExportCSV}
            title="Download log asesmen ke format CSV"
          >
            <Download size={13} /> Export CSV
          </button>
        </div>
      </div>

      {/* 2. Filter & Search Toolbar */}
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3 p-[16px_20px] bg-[#0f172a] border-b border-[#334155]">
        {/* Search input (order-1 w-full xl:w-[380px], rata kiri di desktop) */}
        <div className="relative flex items-center order-1 w-full xl:w-[380px]">
          <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#64748b] pointer-events-none shrink-0" />
          <input
            type="text"
            className="w-full h-[38px] pl-9 pr-8 bg-[#0f172a] border border-[#334155] rounded-[7px] text-[13px] text-[#f1f5f9] placeholder-[#64748b] transition-all focus-visible:border-[#38bdf8]/60 focus-visible:ring-2 focus-visible:ring-[#38bdf8]/25 focus-visible:outline-none"
            placeholder="Cari checkpoint, sistem, pemeriksa, atau catatan..."
            value={searchDraft.input}
            onChange={(e) => setSearchQuery(e.target.value)}
            aria-label="Cari riwayat checkpoint"
          />
          {searchQuery && (
            <button
              type="button"
              className="absolute right-2.5 top-1/2 -translate-y-1/2 inline-flex items-center justify-center w-5 h-5 text-[#94a3b8] hover:text-[#f8fafc] rounded-full hover:bg-slate-800 transition-colors cursor-pointer"
              onClick={() => setSearchQuery("")}
              aria-label="Bersihkan pencarian"
            >
              <X size={13} />
            </button>
          )}
        </div>

        {/* Filter Group: Segmented Filter + DatePicker (order-2 xl:ml-auto, rata kanan di desktop) */}
        <div className="flex flex-wrap items-center gap-3 order-2 xl:ml-auto max-md:w-full">
          {/* Segmented Filter (Semua / OK / NOK) */}
          <div
            className="inline-flex items-center gap-[3px] p-[3px] rounded-[7px] bg-[#0f172a] border border-[#334155] h-[38px] box-border select-none shrink-0 max-md:w-full max-md:justify-between"
            role="group"
            aria-label="Filter status verdict"
          >
            <button
              type="button"
              className={`inline-flex items-center justify-center gap-1.5 h-full px-3 rounded-[5px] text-[12px] font-semibold transition-all cursor-pointer whitespace-nowrap leading-none max-md:flex-1 ${
                verdictFilter === "all"
                  ? "bg-[#1e293b] text-[#38bdf8] font-bold border border-[#334155]/80 shadow-[0_1px_2px_rgba(0,0,0,0.2)]"
                  : "border border-transparent bg-transparent text-[#94a3b8] hover:text-[#f8fafc] hover:bg-white/[0.04]"
              }`}
              onClick={() => setVerdictFilter("all")}
            >
              <span>Semua</span>
              <span className="font-normal opacity-85">({totalFilteredCount})</span>
            </button>
            <button
              type="button"
              className={`inline-flex items-center justify-center gap-1.5 h-full px-3 rounded-[5px] text-[12px] font-semibold transition-all cursor-pointer whitespace-nowrap leading-none max-md:flex-1 ${
                verdictFilter === "ok"
                  ? "bg-[#1e293b] text-[#4ade80] font-bold border border-[#334155]/80 shadow-[0_1px_2px_rgba(0,0,0,0.2)]"
                : "border border-transparent bg-transparent text-[#94a3b8] hover:text-[#f8fafc] hover:bg-white/[0.04]"
              }`}
              onClick={() => setVerdictFilter("ok")}
            >
              <Check size={13} strokeWidth={2.5} className="shrink-0 text-[#4ade80]" />
              <span>OK</span>
              <span className="font-normal opacity-85">({okFilteredCount})</span>
            </button>
            <button
              type="button"
              className={`inline-flex items-center justify-center gap-1.5 h-full px-3 rounded-[5px] text-[12px] font-semibold transition-all cursor-pointer whitespace-nowrap leading-none max-md:flex-1 ${
                verdictFilter === "nok"
                  ? "bg-[#1e293b] text-[#f87171] font-bold border border-[#334155]/80 shadow-[0_1px_2px_rgba(0,0,0,0.2)]"
                  : "border border-transparent bg-transparent text-[#94a3b8] hover:text-[#f8fafc] hover:bg-white/[0.04]"
              }`}
              onClick={() => setVerdictFilter("nok")}
            >
              <X size={13} strokeWidth={2.5} className="shrink-0 text-[#f87171]" />
              <span>NOK</span>
              <span className="font-normal opacity-85">({nokFilteredCount})</span>
            </button>
          </div>

          {/* Date Filter Picker */}
          <div className="w-[160px] max-md:w-full shrink-0">
            <DatePicker
              value={dateFilter}
              onChange={setDateFilter}
              placeholder="Semua Waktu"
              referenceDate="2026-08-31"
              align="right"
              aria-label="Filter rentang tanggal"
            />
          </div>
        </div>
      </div>

      {/* 3. Grouped History List */}
      {totalCount > 0 ? (
        <div className="rounded-b-[10px] overflow-hidden [display:flex] [flex-direction:column]">
          {groupedPageEntries.map((group) => {
            const stats = dateStatsMap.get(group.date);
            return (
              <div key={group.date} className="[display:flex] [flex-direction:column]">
                <div className="[box-sizing:border-box] [padding:12px_16px_6px] [display:flex] [align-items:center] [background:var(--panel-bg)]">
                  <div className="[width:100%] [display:flex] [align-items:center] [justify-content:space-between] [gap:10px] [padding:6px_12px] [background:color-mix(in_srgb,_var(--accent-blue-soft)_30%,_var(--bg))] [border:1px_solid_var(--line)] [border-radius:6px]">
                    <span className="[font-size:11px] [font-weight:700] [color:var(--ink-primary)] [font-family:var(--font-mono)]">{group.header}</span>
                    <div className="[display:flex] [align-items:center] [gap:6px]">
                      <span className="[font-size:9.5px] [font-weight:700] [font-family:var(--font-mono)] [padding:1px_5px] [border-radius:4px] [color:var(--green)] [background:var(--green-soft)]">✓ {stats?.ok ?? 0} OK</span>
                      <span className="[font-size:9.5px] [font-weight:700] [font-family:var(--font-mono)] [padding:1px_5px] [border-radius:4px] [color:var(--red)] [background:var(--red-soft)]">✗ {stats?.nok ?? 0} NOK</span>
                      <span className="[font-size:9.5px] [font-weight:700] [font-family:var(--font-mono)] [padding:1px_5px] [border-radius:4px] [color:var(--ink-muted)] [background:rgba(148,_163,_184,_0.15)]">{stats?.total ?? 0} total</span>
                    </div>
                  </div>
                </div>

                <div className="history-group-items">
                  {group.items.map((entry) => {
                    const isOk = entry.verdict === "ok";
                    const ownerRole = getOwnerRole(entry.owner);

                    return (
                      <div
                        key={entry.id}
