"use client";

import { Select } from "@/app/components/ui/Select";

import { useEffect, useState } from "react";
import { UserPlus, UserCheck } from "lucide-react";
import { Modal } from "@/app/components/ui/Modal";
import { ModalCloseButton } from "@/app/components/ui/ModalCloseButton";
import { useToast } from "@/app/components/ui/Toast";
import type { RosterMember, RosterRole, RosterMemberStatus } from "@/app/lib/types";

interface MemberCreateModalProps {
  open: boolean;
  onClose: () => void;
  onSaveMember: (member: RosterMember) => void;
  editingMember?: RosterMember | null;
}

export function MemberCreateModal({
  open,
  onClose,
  onSaveMember,
  editingMember,
}: MemberCreateModalProps) {
  const notify = useToast();

  const [name, setName] = useState("");
  const [role, setRole] = useState<RosterRole>("Operator NOC");
  const [employeeId, setEmployeeId] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [currentShift, setCurrentShift] = useState("Shift Malam (16:00–00:30 WIB)");
  const [status, setStatus] = useState<RosterMemberStatus>("Active");

  useEffect(() => {
    if (editingMember) {
      setName(editingMember.name);
      setRole(editingMember.role);
      setEmployeeId(editingMember.employeeId);
      setEmail(editingMember.email);
      setPhone(editingMember.phone);
      setCurrentShift(editingMember.currentShift);
      setStatus(editingMember.status);
    } else {
      setName("");
      setRole("Operator NOC");
      setEmployeeId(`EMP-${Math.floor(1000 + Math.random() * 9000)}`);
      setEmail("");
      setPhone("+62 8");
      setCurrentShift("Shift Malam (16:00–00:30 WIB)");
      setStatus("Active");
    }
  }, [editingMember, open]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    const colors = ["#2563eb", "#7c3aed", "#059669", "#d97706", "#db2777", "#4f46e5", "#0891b2"];
    const randomBg = colors[Math.floor(Math.random() * colors.length)];

    const memberData: RosterMember = {
      id: editingMember?.id ?? `mem-${Date.now()}`,
      name: name.trim(),
      role,
      employeeId: employeeId.trim() || `EMP-${Math.floor(1000 + Math.random() * 9000)}`,
      email: email.trim() || `${name.toLowerCase().replace(/\s+/g, ".")}@company.id`,
      phone: phone.trim() || "+62 812-0000-0000",
      currentShift,
      status,
      joinDate: editingMember?.joinDate ?? "28 Aug 2026",
      avatarBg: editingMember?.avatarBg ?? randomBg,
      weeklySchedule: editingMember?.weeklySchedule ?? [
        { day: "Sen", date: "24 Aug", shift: "Malam", hours: "16:00–00:30" },
        { day: "Sel", date: "25 Aug", shift: "Malam", hours: "16:00–00:30" },
        { day: "Rab", date: "26 Aug", shift: "Malam", hours: "16:00–00:30" },
        { day: "Kam", date: "27 Aug", shift: "Malam", hours: "16:00–00:30" },
        { day: "Jum", date: "28 Aug", shift: "Malam", hours: "16:00–00:30" },
        { day: "Sab", date: "29 Aug", shift: "Off", hours: "Libur" },
        { day: "Min", date: "30 Aug", shift: "Off", hours: "Libur" },
      ],
      stats: editingMember?.stats ?? {
        onTimePercentage: 100,
        shiftsCompleted: 1,
        handoverScore: 100,
      },
      history: editingMember?.history ?? [
        { date: "28 Aug", shift: currentShift, status: "Present", note: "Pendaftaran anggota baru" },
      ],
    };

    onSaveMember(memberData);
    notify.success(
      editingMember
        ? `Data anggota ${memberData.name} berhasil diperbarui.`
        : `Anggota tim baru ${memberData.name} ditambahkan ke roster.`,
      { id: "member-save" },
    );
    onClose();
  };

  return (
    <Modal
      open={open}
      onClose={onClose}
      label={editingMember ? "Edit Anggota Tim" : "Tambah Anggota Tim"}
      width={560}
    >
      <div className="modal-title">
        <div>
          <strong className="[display:flex]! [align-items:center]! [gap:8px]!">
            {editingMember ? (
              <UserCheck size={18} className="[color:var(--accent-blue)]" />
            ) : (
              <UserPlus size={18} className="[color:var(--accent-blue)]" />
            )}
            {editingMember ? "Edit Data Anggota Tim" : "Tambah Anggota Tim Baru"}
          </strong>
          <small>Lengkapi data identitas, peran NOC, dan penugasan shift dinas</small>
        </div>
        <ModalCloseButton onClose={onClose} />
      </div>

      <form onSubmit={handleSubmit} className="[padding:8px_0]!">
        <div className="two-inputs [margin-bottom:12px]!">
          <label>
            <span>Nama Lengkap *</span>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Contoh: Galih Khairi"
              required
            />
          </label>

          <label>
            <span>Role / Posisi *</span>
            <Select size="form" className="w-full" value={role} onChange={(e) => setRole(e.target.value as RosterRole)}>
              <option value="Operator NOC">Operator NOC</option>
              <option value="Shift Lead">Shift Lead</option>
              <option value="Incident Coordinator">Incident Coordinator</option>
              <option value="L2 Specialist">L2 Specialist</option>
              <option value="Infrastructure Engineer">Infrastructure Engineer</option>
            </Select>
          </label>
        </div>

        <div className="two-inputs [margin-bottom:12px]!">
          <label>
            <span>Employee ID</span>
            <input
              type="text"
              value={employeeId}
              onChange={(e) => setEmployeeId(e.target.value)}
              placeholder="EMP-1048"
            />
          </label>

          <label>
            <span>Penugasan Shift</span>
            <Select size="form" className="w-full" value={currentShift} onChange={(e) => setCurrentShift(e.target.value)}>
              <option value="Shift Subuh (00:00–08:30 WIB)">Shift Subuh (00:00–08:30 WIB)</option>
              <option value="Shift Pagi (08:00–16:30 WIB)">Shift Pagi (08:00–16:30 WIB)</option>
              <option value="Shift Malam (16:00–00:30 WIB)">Shift Malam (16:00–00:30 WIB)</option>
              <option value="Cuti Tahunan (On Leave)">Cuti Tahunan (On Leave)</option>
            </Select>
          </label>
        </div>

        <div className="two-inputs [margin-bottom:12px]!">
          <label>
            <span>Email</span>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="nama@company.id"
            />
          </label>

          <label>
            <span>Nomor Telepon</span>
            <input
              type="tel"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              placeholder="+62 812-3456-7890"
            />
          </label>
        </div>

        <label className="[display:grid]! [gap:4px]! [margin-bottom:16px]!">
          <span>Status Kehadiran</span>
          <Select size="form" className="w-full" value={status} onChange={(e) => setStatus(e.target.value as RosterMemberStatus)}>
            <option value="Active">Active (Sedang Dinas)</option>
            <option value="On Break">On Break (Istirahat)</option>
            <option value="Off Duty">Off Duty (Lepas Dinas)</option>
            <option value="On Leave">On Leave (Cuti / Izin)</option>
          </Select>
        </label>

        <div className="modal-actions">
          <button type="button" className="button button-secondary" onClick={onClose}>
            Cancel
          </button>
          <button type="submit" className="button button-primary">
            {editingMember ? "✓ Simpan Perubahan" : "＋ Tambahkan Anggota"}
          </button>
        </div>
      </form>
    </Modal>
  );
}

"use client";

import { useState } from "react";
import { Mail, Phone, Clock, CalendarDays, X } from "lucide-react";
import { Badge } from "@/app/components/ui/Badge";
import { Avatar } from "@/app/components/ui/Avatar";
import { ModalCloseButton } from "@/app/components/ui/ModalCloseButton";
import { useToast } from "@/app/components/ui/Toast";
import { initials } from "@/app/lib/data";
import { statusTone, shiftColor } from "@/app/components/team/RosterTable";
import { useUserStatus, getStatusRingStyle } from "@/app/hooks/useUserStatus";
import type { RosterMember, RosterMemberStatus } from "@/app/lib/types";

/* ─────────────────────────────────────────────────────────────
   HistorySection helpers — defined before the components
───────────────────────────────────────────────────────────── */
const MONTH_DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

function buildAugHeatmap(member: RosterMember) {
  // Aug 1 2026 = Saturday (JS getDay()=6) → Mon-based dow = (6+6)%7 = 5
  const firstDow = 5;
  const days: { day: number; shiftDay: RosterMember["weeklySchedule"][number] | null }[] = [];
  for (let d = 1; d <= 31; d++) {
    const dow = (firstDow + d - 1) % 7;
    const shiftDay = member.weeklySchedule[dow] ?? null;
    days.push({ day: d, shiftDay });
  }
  return { firstDow, days };
}

/* ─────────────────────────────────────────────────────────────
   HistorySection — list view + monthly heatmap toggle
───────────────────────────────────────────────────────────── */
function HistorySection({ member }: { member: RosterMember }) {
  const [mode, setMode] = useState<"list" | "heatmap">("list");
  const { firstDow, days } = buildAugHeatmap(member);

  return (
    <div>
      {/* Header + toggle */}
      <div className="flex justify-between items-center mb-[10px]">
        <span className="block text-[10px] font-mono font-bold tracking-[0.8px] text-[var(--ink-muted)] uppercase m-0">
          SHIFT &amp; ATTENDANCE HISTORY
        </span>
        <div className="inline-flex items-center gap-[2px] h-[36px] box-border p-[3px] bg-[var(--surface,#0f172a)] border border-[var(--panel-border)] rounded-[8px] shrink-0 scale-[0.85] origin-right" aria-label="Toggle history view">
          <button
            type="button"
            className={`inline-flex items-center justify-center h-[28px] px-[12px] text-[11.5px] font-semibold rounded-[6px] gap-[6px] border border-transparent cursor-pointer transition-[color,background-color] duration-150 ease ${
              mode === "list"
                ? "bg-[var(--accent-blue,#2563eb)] text-white shadow-[0_1px_3px_rgba(0,0,0,0.25)]"
                : "bg-transparent text-[var(--ink-muted)] hover:text-[var(--ink-primary)] hover:bg-[rgba(148,163,184,0.08)]"
            }`}
            onClick={() => setMode("list")}
          >
            List
          </button>
          <button
            type="button"
            className={`inline-flex items-center justify-center h-[28px] px-[12px] text-[11.5px] font-semibold rounded-[6px] gap-[6px] border border-transparent cursor-pointer transition-[color,background-color] duration-150 ease ${
              mode === "heatmap"
                ? "bg-[var(--accent-blue,#2563eb)] text-white shadow-[0_1px_3px_rgba(0,0,0,0.25)]"
                : "bg-transparent text-[var(--ink-muted)] hover:text-[var(--ink-primary)] hover:bg-[rgba(148,163,184,0.08)]"
            }`}
            onClick={() => setMode("heatmap")}
          >
            Monthly
          </button>
        </div>
      </div>

      {/* ── List view ── */}
      {mode === "list" && (
        <div className="grid gap-[8px]">
          {member.history.map((h, i) => (
            <div
              key={i}
              className="flex justify-between items-center p-[10px_12px] bg-[rgba(127,127,127,0.05)] border border-[var(--line)] rounded-[8px] text-[12px]"
            >
              <div className="flex gap-[10px] items-center">
                <span className="font-mono font-bold text-[var(--accent-blue)] shrink-0">
                  <Clock size={12} className="inline vertical-middle mr-[4px]" />
                  {h.date}
                </span>
                <div>
                  <strong className="block text-[var(--ink-primary)] text-[12.5px]">{h.shift}</strong>
                  {h.note && <small className="text-[var(--ink-muted)] text-[11px]">{h.note}</small>}
                </div>
              </div>
              <Badge tone={h.status === "Present" ? "success" : h.status === "Leave" ? "critical" : "warning"}>
                {h.status}
              </Badge>
            </div>
          ))}
        </div>
      )}

      {/* ── Monthly heatmap ── */}
      {mode === "heatmap" && (
        <div className="mt-[4px]">
          <p className="m-[0_0_10px] text-[11px] text-[var(--ink-muted)]">
            <CalendarDays size={12} className="inline vertical-middle mr-[4px]" />
            August 2026 — shift pattern based on weekly schedule
          </p>

          <div className="grid grid-cols-[repeat(7,1fr)] gap-[3px] mb-[4px]">
            {MONTH_DAYS.map((d) => (
              <div key={d} className="text-center text-[9px] font-bold font-mono text-[var(--ink-muted)] uppercase py-[2px]">{d}</div>
            ))}
          </div>

          <div className="grid grid-cols-[repeat(7,1fr)] gap-[3px]">
            {Array(firstDow).fill(null).map((_, i) => (
              <div key={`e-${i}`} className="aspect-square rounded-[5px] border border-transparent bg-transparent cursor-default" />
            ))}
            {days.map(({ day, shiftDay }) => {
              const shift = (shiftDay?.shift ?? "Off") as Parameters<typeof shiftColor>[0];
              const sc = shiftColor(shift);
              const isToday = day === 28;
              return (
                <div
                  key={day}
                  className={`aspect-square rounded-[5px] flex flex-col items-center justify-center cursor-default ${
                    isToday
                      ? "border-2 border-[var(--accent-blue)]"
                      : "border border-[var(--line)]"
                  }`}
                  style={{
                    backgroundColor: sc.bg,
                    borderColor: isToday ? "var(--accent-blue)" : sc.border,
                    color: sc.color,
                  }}
                  title={`${day} Aug — ${shift}${shiftDay?.hours ? ` (${shiftDay.hours})` : ""}`}
                >
                  <span className="text-[8px] font-mono font-bold leading-none opacity-75">{day}</span>
                  <span className="text-[10px] font-extrabold leading-none mt-[1px]">
                    {shift === "Off" ? "—" : shift === "Leave" ? "L" : shift[0]}
                  </span>
                </div>
              );
            })}
          </div>

          <div className="flex gap-[10px] flex-wrap mt-[8px] pt-[8px] border-t border-[var(--line)]">
            {(["Subuh", "Pagi", "Malam", "Leave", "Off"] as const).map((shift) => {
              const sc = shiftColor(shift);
              return (
                <span key={shift} className="inline-flex items-center gap-[6px] text-[10.5px]">
                  <i
                    className="block w-[12px] h-[12px] rounded-[3px] border border-[var(--line)]"
                    style={{
                      backgroundColor: sc.bg,
                      borderColor: sc.border,
                    }}
                  />
                  {shift}
                </span>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════
   Main MemberDetailDrawer component
═══════════════════════════════════════════════════════════ */
interface MemberDetailDrawerProps {
  member: RosterMember | null;
  onClose: () => void;
  onUpdateMember: (updated: RosterMember) => void;
  onRequestSwap: (member: RosterMember) => void;
}

export function MemberDetailDrawer({
  member,
  onClose,
  onUpdateMember,
  onRequestSwap,
}: MemberDetailDrawerProps) {
  const notify = useToast();

  const { userStatus } = useUserStatus();
  if (!member) return null;

  const isCurrentUser = member.name.toLowerCase().includes("galih");
  const ringStyle = getStatusRingStyle(member.status, isCurrentUser, userStatus);
  const ringColor = (ringStyle as any)["--status-ring-color"] || "#22c55e";
  const displayStatus = isCurrentUser ? userStatus : member.status;

  const handleStatusChange = (newStatus: RosterMemberStatus) => {
    const updated: RosterMember = { ...member, status: newStatus };
    onUpdateMember(updated);
    notify.success(`Status ${member.name} changed to ${newStatus}.`, { id: `status-${member.id}` });
  };

  const copyToClipboard = (text: string, label: string) => {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(text);
      notify.success(`${label} copied: ${text}`, { id: `copy-${text}` });
    }
  };

  return (
    <div
      className="drawer-backdrop anim-fade"
      role="presentation"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <div
        className="drawer-body anim-slide-left"
        role="dialog"
        aria-modal="true"
        aria-label={`Team Member Detail — ${member.name}`}
      >
        {/* Header */}
        <div className="drawer-header">
          <div className="[display:flex]! [gap:12px]! [align-items:center]!">
            <div
              className="drawer-avatar-ring-wrapper"
              style={ringStyle as React.CSSProperties}
              title={`${member.name} (${displayStatus})`}
            >
              <Avatar size="lg" name={member.name} />
              <span
                className="drawer-avatar-status-badge [background-color:var(--drawer-status-ring-color)]!"
                style={{ "--drawer-status-ring-color": ringColor } as React.CSSProperties}
              />
            </div>
            <div>
              <div className="[display:flex]! [gap:8px]! [align-items:center]! [margin-bottom:4px]!">
                <h2 className="[font-size:17px]! [font-weight:700]! [margin:0]! [color:var(--ink-primary)]!">
                  {member.name}
                </h2>
                {isCurrentUser ? (
                  <Badge tone={userStatus === "Online" ? "success" : userStatus === "Busy" ? "critical" : userStatus === "On Break" ? "warning" : "info"}>
                    {userStatus}
                  </Badge>
                ) : (
                  <Badge tone={statusTone(member.status)}>{member.status}</Badge>
                )}
              </div>
              <span className="[font-size:11.5px]! [color:var(--ink-muted)]! [font-family:var(--font-mono)]!">
                {member.role} · ID: {member.employeeId}
              </span>
            </div>
          </div>
          <ModalCloseButton onClose={onClose} label="Tutup panel" />
        </div>

        {/* Scrollable content */}
        <div className="drawer-content-inner">
          {/* Contact quick-copy */}
          <div className="[display:flex]! [gap:8px]! [margin-bottom:20px]! [flex-wrap:wrap]!">
            <button className="button button-secondary [font-size:11px]! [padding:6px_10px]!" onClick={() => copyToClipboard(member.email, "Email")}>
              <Mail size={13} /> {member.email}
            </button>
            <button className="button button-secondary [font-size:11px]! [padding:6px_10px]!" onClick={() => copyToClipboard(member.phone, "Phone")}>
              <Phone size={13} /> {member.phone}
            </button>
          </div>

          {/* Attendance stats */}
          <div className="[margin-bottom:24px]!">
            <span className="block text-[10px] font-mono font-bold tracking-[0.8px] text-[var(--ink-muted)] uppercase mb-[8px]">ATTENDANCE &amp; PERFORMANCE</span>
            <div className="metrics-grid [grid-template-columns:repeat(3,_1fr)]! [gap:10px]! [margin-top:8px]!">
              <div className="metric-card [padding:12px]!">
                <span className="metric-title [font-size:9px]!">ON-TIME RATE</span>
                <strong className="[font-size:18px]! [color:var(--green)]! [margin-top:4px]!">{member.stats.onTimePercentage}%</strong>
                <small className="[color:var(--ink-muted)]! [font-size:10px]!">On-time attendance</small>
              </div>
              <div className="metric-card [padding:12px]!">
                <span className="metric-title [font-size:9px]!">SHIFTS DONE</span>
                <strong className="[font-size:18px]! [color:var(--accent-blue)]! [margin-top:4px]!">{member.stats.shiftsCompleted}</strong>
                <small className="[color:var(--ink-muted)]! [font-size:10px]!">Completed shifts</small>
              </div>
              <div className="metric-card [padding:12px]!">
                <span className="metric-title [font-size:9px]!">HANDOVER QUALITY</span>
                <strong className="[font-size:18px]! [color:var(--purple)]! [margin-top:4px]!">{member.stats.handoverScore}%</strong>
                <small className="[color:var(--ink-muted)]! [font-size:10px]!">SOP compliance score</small>
              </div>
            </div>
          </div>

          {/* Current shift & status switcher */}
          <div className="[margin-bottom:24px]! [padding:14px]! [background:var(--panel-bg)]! [border:1px_solid_var(--panel-border)]! [border-radius:10px]!">
            <div className="[display:flex]! [justify-content:space-between]! [align-items:center]! [margin-bottom:8px]!">
              <span className="block text-[10px] font-mono font-bold tracking-[0.8px] text-[var(--ink-muted)] uppercase m-0">CURRENT ASSIGNED SHIFT</span>
              <Badge tone="info">
                <Clock size={11} className="[display:inline]! [vertical-align:middle]! [margin-right:3px]!" />
                {member.currentShift}
              </Badge>
            </div>
            <p className="[margin:0_0_12px]! [font-size:12px]! [color:var(--ink-secondary)]!">
              Assigned to Console 01 / NOC Command Desk. Joined <strong>{member.joinDate}</strong>.
            </p>
            <div className="[display:flex]! [gap:6px]! [align-items:center]! [flex-wrap:wrap]!">
              <span className="[font-size:11px]! [color:var(--ink-muted)]! [font-weight:600]! [margin-right:4px]!">Quick Status:</span>
              {(["Active", "On Break", "Off Duty", "On Leave"] as const).map((s) => (
                <button
                  key={s}
                  className={`button ${member.status === s ? "button-primary" : "button-secondary"} [font-size:11px]! [padding:4px_8px]!`}
                  onClick={() => handleStatusChange(s)}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>

          {/* Shift history — list or monthly heatmap */}
          <HistorySection member={member} />
        </div>

        {/* Footer */}
        <div className="drawer-footer">
          <button
            className="button button-secondary"
            onClick={() => { onClose(); onRequestSwap(member); }}
          >
            Request Shift Swap
          </button>
          <button className="button button-primary" onClick={onClose}>
            Done
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useMemo, useState, useCallback } from "react";
import { Avatar } from "@/app/components/ui/Avatar";
import { StatusIndicator } from "@/app/components/ui/StatusIndicator";
import { Moon, Sun, Sunset } from "lucide-react";
import { useActiveShift } from "@/app/hooks/useLiveClock";
import { useUserStatus, getStatusRingStyle } from "@/app/hooks/useUserStatus";
import type { RosterMember } from "@/app/lib/types";

export type CoverageFilterTab = "Semua" | "On Duty" | "Online" | "Offline";

export interface RosterShiftCoverageProps {
  members: RosterMember[];
  onSelectMember: (member: RosterMember) => void;
  matchedHeight?: number;
}

/**
 * Resolves a roster member's status into 3 canonical coverage states:
 * - "On Duty": Actively on duty during the current shift
 * - "Online": Standby, online, or on break
 * - "Offline": Off duty or on leave
 */
export function resolveCoverageStatus(
  member: RosterMember,
  isCurrentUser: boolean,
  userStatus?: string
): "On Duty" | "Online" | "Offline" {
  if (isCurrentUser && userStatus) {
    if (userStatus === "Online" || userStatus === "Busy") return "On Duty";
    if (userStatus === "On Break") return "Online";
    return "Offline";
  }

  const s = (member.status || "").toLowerCase().trim();
  if (s === "active" || s === "on duty" || s === "bertugas" || s === "present") {
    return "On Duty";
  }
  if (s === "on break" || s === "break" || s === "standby" || s === "online") {
    return "Online";
  }
  return "Offline";
}

export function RosterShiftCoverage({
  members,
  onSelectMember,
  matchedHeight,
}: RosterShiftCoverageProps) {
  const activeShift = useActiveShift();
  const { userStatus } = useUserStatus();
  const [activeTab, setActiveTab] = useState<CoverageFilterTab>("Semua");

  const ShiftIcon =
    activeShift.id === "subuh" ? Moon : activeShift.id === "pagi" ? Sun : Sunset;

  // 1. Tally counts for On Duty, Online, Offline
  const counts = useMemo(() => {
    let onDuty = 0;
    let online = 0;
    let offline = 0;

    for (const m of members) {
      const isCurrent = m.name.toLowerCase().includes("galih");
      const status = resolveCoverageStatus(m, isCurrent, userStatus);
      if (status === "On Duty") onDuty++;
      else if (status === "Online") online++;
      else offline++;
    }

    return {
      total: members.length,
      onDuty,
      online,
      offline,
    };
  }, [members, userStatus]);

  // 2. Data for SVG Donut Chart (identical to Overview)
  const chartData = useMemo(
    () => [
      {
        label: "On Duty",
        count: counts.onDuty,
        color: "#22c55e",
        gradientId: "coverage-donut-grad-onduty",
      },
      {
        label: "Online",
        count: counts.online,
        color: "#38bdf8",
        gradientId: "coverage-donut-grad-online",
      },
      {
        label: "Offline",
        count: counts.offline,
        color: "#64748b",
        gradientId: "coverage-donut-grad-offline",
      },
    ],
    [counts]
  );

  const radius = 45;
  const strokeWidth = 11.5;
  const cx = 60;
  const cy = 60;

  const renderDonutSlices = () => {
    const totalVal = chartData.reduce((acc, curr) => acc + curr.count, 0);
    if (totalVal === 0) return null;

    const circumference = 2 * Math.PI * radius;
    const activeSlices = chartData.filter((item) => item.count > 0);

    if (activeSlices.length === 1) {
      const item = activeSlices[0];
      return (
        <circle
          cx={cx}
          cy={cy}
          r={radius}
          fill="none"
          stroke={`url(#${item.gradientId})`}
          strokeWidth={strokeWidth}
          strokeDasharray={`${circumference} ${circumference}`}
          strokeDashoffset={0}
          strokeLinecap="butt"
          transform={`rotate(-90 ${cx} ${cy})`}
        />
      );
    }

    const totalGap = strokeWidth + 4;
    let accumulatedAngle = 0;

    return activeSlices.map((item, idx) => {
      const slicePct = item.count / totalVal;
      const rawLength = slicePct * circumference;
      const visibleLength = Math.max(0.1, rawLength - totalGap);
      const strokeDasharray = `${visibleLength} ${circumference - visibleLength}`;
      const strokeDashoffset = -(
        accumulatedAngle * circumference +
        totalGap / 2
      );
      accumulatedAngle += slicePct;

      return (
        <circle
          key={`${item.label}-${idx}`}
          cx={cx}
          cy={cy}
          r={radius}
          fill="none"
          stroke={`url(#${item.gradientId})`}
          strokeWidth={strokeWidth}
          strokeDasharray={strokeDasharray}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          transform={`rotate(-90 ${cx} ${cy})`}
        />
      );
    });
  };

  // 3. Filter members based on active tab
  const filteredMembers = useMemo(() => {
    if (activeTab === "Semua") return members;

    return members.filter((m) => {
      const isCurrent = m.name.toLowerCase().includes("galih");
      const status = resolveCoverageStatus(m, isCurrent, userStatus);
      return status === activeTab;
    });
  }, [members, activeTab, userStatus]);

  const handleSelectMember = useCallback(
    (member: RosterMember) => {
      onSelectMember(member);
    },
    [onSelectMember]
  );

  return (
    <article
      className="panel flex flex-col h-full box-border p-0 overflow-hidden bg-[var(--panel-bg)] border border-[var(--panel-border)] rounded-[10px] shadow-[var(--shadow-panel)]"
      style={matchedHeight ? { height: `${matchedHeight}px` } : undefined}
    >
      {/* ── Header: Title, Subtitle, Shift Badge ── */}
      <div className="flex flex-col items-center text-center p-[16px_20px_14px] border-b border-[var(--line)] bg-[var(--panel-bg)]">
        <h2 className="m-0 text-[var(--ink-primary)] text-[15px] font-bold leading-[1.2] justify-center text-center">Status Kehadiran Anggota</h2>
        <span className="block mt-[3px] text-[var(--ink-secondary)] text-[11.5px] font-medium leading-[1.2] text-center">Ketersediaan Pegawai</span>
        <div className="flex items-center justify-center mt-[8px]">
          <div
            className={`topbar-shift-badge inline-flex items-center gap-[6px] px-[12px] py-[4px] rounded-[999px] text-[11px] leading-[1.2] shadow-[0_1px_3px_rgba(0,0,0,0.25)] ${activeShift.badgeClass}`}
            title={`Shift Aktif: ${activeShift.name}`}
            aria-label={`Shift aktif ${activeShift.name}`}
          >
            <ShiftIcon size={12} className="shift-badge-icon" />
            <span className="shift-badge-label">
              <strong>{activeShift.label}</strong>
            </span>
          </div>
        </div>
      </div>

      {/* ── Donut Chart (Overview shape & styling) ── */}
      <div className="flex justify-center items-center my-[14px_12px]">
        <div className="w-[124px] h-[124px] relative">
          <svg
            className="w-full h-full overflow-visible pointer-events-none"
            viewBox="0 0 120 120"
            aria-label={`Distribusi status roster: ${counts.onDuty} On Duty, ${counts.online} Online, ${counts.offline} Offline`}
          >
            <defs>
              <linearGradient id="coverage-donut-grad-onduty" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#4ade80" />
                <stop offset="100%" stopColor="#16a34a" />
              </linearGradient>
              <linearGradient id="coverage-donut-grad-online" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#38bdf8" />
                <stop offset="100%" stopColor="#0284c7" />
              </linearGradient>
              <linearGradient id="coverage-donut-grad-offline" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#64748b" />
                <stop offset="100%" stopColor="#334155" />
              </linearGradient>
            </defs>

            {/* Dotted calibration ring */}
            <circle
              cx={cx}
              cy={cy}
              r={radius + strokeWidth / 2 + 2.5}
              fill="none"
              stroke="rgba(255, 255, 255, 0.05)"
              strokeWidth={1}
              strokeDasharray="2 3"
            />

            {/* Background track groove */}
            <circle
              cx={cx}
              cy={cy}
              r={radius}
              fill="none"
              stroke="rgba(255, 255, 255, 0.06)"
              strokeWidth={strokeWidth}
            />

            {/* Inner dial plate */}
            <circle
              cx={cx}
              cy={cy}
              r={radius - strokeWidth / 2 - 1.5}
              fill="rgba(15, 23, 42, 0.55)"
              stroke="rgba(255, 255, 255, 0.04)"
              strokeWidth={1}
            />

            {renderDonutSlices()}
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
            <span className="text-[26px] font-extrabold font-mono text-white leading-none">{counts.total}</span>
            <span className="text-[9px] font-bold font-mono tracking-[1.5px] text-[var(--ink-muted)] mt-[4px]">TOTAL</span>
          </div>
        </div>
      </div>

      {/* ── 3-State Stats Summary Row (On Duty · Online · Offline) ── */}
      <div className="flex flex-wrap items-center justify-center gap-[8px] mt-[6px] mx-[16px] mb-0" aria-label="Ringkasan status roster">
        <span
