"use client";

import { Select } from "@/app/components/ui/Select";

import { useEffect, useState, useMemo } from "react";
import { X, Zap, Check, Ticket, FileText, Layers, AlertTriangle, Activity, Tag, AlignLeft, RefreshCw, Clock, CheckCircle2, Users } from "lucide-react";
import { Modal } from "@/app/components/ui/Modal";
import { Badge } from "@/app/components/ui/Badge";
import { TimePicker } from "@/app/components/ui/TimePicker";
import { OwnerTagInput } from "@/app/components/tickets/OwnerTagInput";
import { makeTicketId, nowClockLabel } from "@/app/lib/data";
import { severityTone, statusTone } from "@/app/components/tickets/TicketTable";
import { useAuth } from "@/app/lib/auth";
import type { Ticket as TicketType } from "@/app/lib/types";
import { useClient } from "@/app/context/ClientContext";
import { getClientSystems } from "@/app/lib/clientData";

interface TicketCreateModalProps {
  open: boolean;
  onClose: () => void;
  onCreate: (ticket: TicketType) => void;
}

const PRIORITY_OPTIONS = ["Low", "Medium", "High", "Critical"];
const STATUS_OPTIONS = ["Open", "Closed", "Activity", "Meeting", "Re-Open", "Pending", "RCA"] as const;

const CATEGORY_OPTIONS = [
  "Ad-hoc Request",
  "Escalation Handling",
  "Incident & Issue Handling",
  "Validate End-to-End Process Flow",
  "Knowledge Management & Documentation",
  "Monitoring VM, Platform & Services",
];

export function TicketCreateModal({ open, onClose, onCreate }: TicketCreateModalProps) {
  const { user } = useAuth();
  const { activeClient, activeClientId, getProjectsForClient } = useClient();
  const clientSystems = useMemo(() => {
    const projs = getProjectsForClient(activeClientId, false).map((p) => p.name);
    if (projs.length > 0) return projs;
    return getClientSystems(activeClientId);
  }, [activeClientId, getProjectsForClient]);

  const operatorName = user?.name || "Mhd. Galih Khairi";
  const [ticketCode, setTicketCode] = useState(() => makeTicketId());
  const [subject, setSubject] = useState("");
  const [owners, setOwners] = useState<string[]>(() => [operatorName]);
  const [project, setProject] = useState(() => clientSystems[0] || "SM");
  const [severity, setSeverity] = useState("Low");
  const [status, setStatus] = useState<string>("Open");
  const [category, setCategory] = useState<string>("");
  const [description, setDescription] = useState("");

  // Conditional Ad-hoc Request fields
  const [requestTime, setRequestTime] = useState("");
  const [responseTime, setResponseTime] = useState("");
  const [completionTime, setCompletionTime] = useState("");
  const [isStillOpen, setIsStillOpen] = useState(false);

  const [error, setError] = useState("");

  // Pre-fill suggested ticket code & current time whenever modal opens
  useEffect(() => {
    if (open) {
      const current = nowClockLabel();
      setTicketCode(makeTicketId());
      setRequestTime(current);
      setResponseTime(current);
      setCompletionTime("");
      setIsStillOpen(false);
      setError("");
      setProject(clientSystems[0] || "SM");
      setOwners([operatorName]);
    }
  }, [open, clientSystems, operatorName]);

  const reset = () => {
    setTicketCode(makeTicketId());
    setSubject("");
    setOwners([operatorName]);
    setProject("SM");
    setSeverity("Low");
    setStatus("Open");
    setCategory("");
    setDescription("");
    setRequestTime("");
    setResponseTime("");
    setCompletionTime("");
    setIsStillOpen(false);
    setError("");
  };

  const submit = () => {
    const cleanCode = ticketCode.trim().replace(/^#/, "");
    const trimmedSubject = subject.trim();

    if (!cleanCode) {
      setError("Kode tiket wajib diisi. Masukkan kode manual atau klik tombol generate.");
      return;
    }
    if (!/^[a-zA-Z0-9_\-]+$/.test(cleanCode) || cleanCode.length < 3) {
      setError("Format kode tiket tidak valid (gunakan minimal 3 karakter alfanumerik atau tanda hubung).");
      return;
    }
    if (!trimmedSubject) {
      setError("Subjek ticket wajib diisi agar tim operasional memahami konteks.");
      return;
    }
    if (!category || category === "--") {
      setError("Silakan pilih salah satu 'Category' yang sesuai.");
      return;
    }
    if (!status) {
      setError("Status ticket wajib dipilih.");
      return;
    }

    // Validation for Ad-hoc Request category
    if (category === "Ad-hoc Request") {
      if (!requestTime.trim()) {
        setError("Request Time wajib diisi untuk kategori Ad-hoc Request.");
        return;
      }
      if (!responseTime.trim()) {
        setError("Response Time wajib diisi untuk kategori Ad-hoc Request.");
        return;
      }
      if (!isStillOpen && !completionTime.trim()) {
        setError("Completion Time wajib diisi, atau centang 'Still Open' jika pekerjaan belum selesai.");
        return;
      }
    }

    const created = nowClockLabel();
    const isAdhoc = category === "Ad-hoc Request";
    const primaryOwner = owners.length > 0 ? owners.join(", ") : "Unassigned";

    onCreate({
      id: cleanCode,
      subject: trimmedSubject,
      project,
      severity,
      requestTime: isAdhoc ? requestTime : undefined,
      responseTime: isAdhoc ? responseTime : undefined,
      completionTime: isAdhoc ? (isStillOpen ? undefined : completionTime) : undefined,
      isStillOpen: isAdhoc ? isStillOpen : undefined,
      owner: primaryOwner,
      owners,
      category: category || "Incident & Issue Handling",
      status,
      created,
      description:
        description.trim() ||
        (isAdhoc
          ? `Permintaan Ad-hoc (Req: ${requestTime}, Resp: ${responseTime}${isStillOpen ? ", Status: Still Open" : `, Selesai: ${completionTime}`}).`
          : `Item aktivitas operasional kategori ${category}.`),
      clientId: activeClientId,
      history: [
        {
          time: created,
          type: "created",
          action: `Ticket #${cleanCode} dibuat oleh ${operatorName} (PIC: ${primaryOwner}, Kategori: ${category}, Status: ${status})`,
          author: operatorName,
        },
      ],
    });

    reset();
    onClose();
  };

  const isAdhoc = category === "Ad-hoc Request";

  return (
    <Modal open={open} onClose={onClose} label="Buat ticket baru" width={640}>
      <div className="modal-title">
        <div>
          <strong>Buat Ticket NOC Baru — {activeClient.shortName}</strong>
          <small>Catat tugas operasional, permintaan ad-hoc, atau penanganan insiden untuk {activeClient.name}.</small>
        </div>
        <button onClick={onClose} aria-label="Tutup modal">
          <X size={15} />
        </button>
      </div>

      <div className="ticket-form-grid">
        {/* ── Section 1: Ticket Identity ── */}
        <div className="ticket-form-section">
          <div className="ticket-section-header">
            <span className="ticket-section-title">Identitas Ticket</span>
          </div>

          <div className="ticket-code-subject-row">
            <label className="ticket-field-code">
              <div className="ticket-field-label-wrapper">
                <span className="ticket-field-label">
                  <Ticket size={12} className="ticket-field-icon" />
                  TICKET CODE
                </span>
              </div>
              <div className="ticket-input-wrapper">
                <span className="ticket-hash-prefix">#</span>
                <input
                  type="text"
                  value={ticketCode}
                  onChange={(event) => {
                    setTicketCode(event.target.value.replace(/^#/, ""));
                    if (error) setError("");
                  }}
                  placeholder="Kode tiket"
                  className="ticket-editable-code-input"
                  title="Kode tiket (dapat diketik manual atau digenerate otomatis)"
                />
                <button
                  type="button"
                  onClick={() => {
                    setTicketCode(makeTicketId());
                    if (error) setError("");
                  }}
                  className="ticket-generate-code-btn"
                  title="Generate Otomatis Kode Baru"
                  aria-label="Generate Otomatis Kode Baru"
                >
                  <RefreshCw size={12} />
                </button>
              </div>
            </label>

            <label className="ticket-field-subject">
              <div className="ticket-field-label-wrapper">
                <span className="ticket-field-label">
                  <FileText size={12} className="ticket-field-icon" />
                  SUBJECT <span className="ticket-required-star" title="Wajib diisi">*</span>
                </span>
              </div>
              <input
                value={subject}
                onChange={(event) => {
                  setSubject(event.target.value);
                  if (error) setError("");
                }}
                placeholder="Judul singkat pekerjaan atau observasi"
                autoFocus
              />
            </label>
          </div>

          {/* Row: Pemilik Tiket / PIC (Multi-chip Tag Input) */}
          <div className="ticket-field-owners">
            <div className="ticket-field-label-wrapper">
              <span className="ticket-field-label">
                <Users size={12} className="ticket-field-icon" />
                PEMILIK TIKET / PIC
              </span>
              <span className="ticket-field-hint">Dapat menambahkan lebih dari satu PIC</span>
            </div>
            <OwnerTagInput
              owners={owners}
              onChange={setOwners}
              placeholder="Ketik nama operator atau pilih dari daftar..."
            />
          </div>
        </div>

        <div className="ticket-form-divider" />

        {/* ── Section 2: Classification ── */}
        <div className="ticket-form-section">
          <div className="ticket-section-header">
            <span className="ticket-section-title">Klasifikasi Layanan</span>
          </div>

          {/* Row: Project + Priority Level + Status (3-Column Grid) */}
          <div className="three-inputs">
            <label>
              <div className="ticket-field-label-wrapper">
                <span className="ticket-field-label">
                  <Layers size={12} className="ticket-field-icon" />
                  PROJECT / SISTEM
                </span>
              </div>
              <Select size="form" className="w-full" value={project} onChange={(event) => setProject(event.target.value)}>
                {clientSystems.map((option) => (
                  <option key={option} value={option}>{option}</option>
                ))}
              </Select>
            </label>

            <label>
              <div className="ticket-field-label-wrapper">
                <span className="ticket-field-label">
                  <AlertTriangle size={12} className="ticket-field-icon" />
                  SEVERITY LEVEL
                </span>
                <Badge tone={severityTone(severity)}>{severity}</Badge>
              </div>
              <Select size="form" className="w-full" value={severity} onChange={(event) => setSeverity(event.target.value)}>
                {PRIORITY_OPTIONS.map((option) => (
                  <option key={option} value={option}>{option}</option>
                ))}
              </Select>
            </label>

            <label>
              <div className="ticket-field-label-wrapper">
                <span className="ticket-field-label">
                  <Activity size={12} className="ticket-field-icon" />
                  STATUS
                </span>
                <Badge tone={statusTone(status)}>{status}</Badge>
              </div>
              <Select
                value={status}
                onChange={(event) => {
                  setStatus(event.target.value);
                  if (error) setError("");
                }}
                className="ticket-status-select"
              >
                {STATUS_OPTIONS.map((option) => (
                  <option key={option} value={option}>{option}</option>
                ))}
              </Select>
            </label>
          </div>

          {/* Category (Full Width) */}
          <label className="ticket-field-category">
            <div className="ticket-field-label-wrapper">
              <span className="ticket-field-label">
                <Tag size={12} className="ticket-field-icon" />
                CATEGORY <span className="ticket-required-star" title="Wajib diisi">*</span>
              </span>
              <span className="ticket-required-hint">Wajib</span>
            </div>
            <Select
              value={category}
              onChange={(event) => {
                setCategory(event.target.value);
                if (error) setError("");
              }}
              className={category && category !== "--" ? "selected-category" : ""}
            >
              <option value="">-- Pilih Kategori Tiket --</option>
              {CATEGORY_OPTIONS.map((option) => (
                <option key={option} value={option}>
                  {option}
                </option>
              ))}
            </Select>
          </label>

          {/* Conditional Fields for "Ad-hoc Request" */}
          {isAdhoc && (
            <div className="adhoc-fields-container">
              <div className="adhoc-fields-header">
                <span className="adhoc-fields-badge">
                  <Zap size={11} className="[display:inline-block]! [vertical-align:middle]! [margin-right:4px]!" />
                  Timeline Permintaan Ad-hoc
                </span>
                <small>Waktu masuk, respon, dan estimasi selesai pekerjaan.</small>
              </div>

              <div className="three-inputs adhoc-inputs-row">
                <label>
                  <div className="ticket-field-label-wrapper">
                    <span className="ticket-field-label">
                      <Clock size={12} className="ticket-field-icon" />
                      REQUEST TIME <span className="ticket-required-star">*</span>
                    </span>
                  </div>
                  <TimePicker
                    value={requestTime}
                    onChange={(val) => {
                      setRequestTime(val);
                      if (error) setError("");
                    }}
                    placeholder="00:00"
                    title="Waktu masuk permintaan ad-hoc"
                  />
                </label>

                <label>
                  <div className="ticket-field-label-wrapper">
                    <span className="ticket-field-label">
                      <Clock size={12} className="ticket-field-icon" />
                      RESPONSE TIME <span className="ticket-required-star">*</span>
                    </span>
                  </div>
                  <TimePicker
                    value={responseTime}
                    onChange={(val) => {
                      setResponseTime(val);
                      if (error) setError("");
                    }}
                    placeholder="00:00"
                    title="Waktu respon pertama penanganan"
                  />
                </label>

                <label>
                  <div className="ticket-field-label-wrapper">
                    <span className="ticket-field-label">
                      <CheckCircle2 size={12} className="ticket-field-icon" />
                      COMPLETION TIME
                    </span>
                    <label className="still-open-toggle-label" title="Centang jika permintaan belum selesai">
                      <input
                        type="checkbox"
                        checked={isStillOpen}
                        onChange={(e) => {
                          setIsStillOpen(e.target.checked);
                          if (error) setError("");
                        }}
                        className="still-open-checkbox"
                      />
                      <span>Still Open</span>
                    </label>
                  </div>
                  <TimePicker
                    value={isStillOpen ? "" : completionTime}
                    onChange={(val) => {
                      setCompletionTime(val);
                      if (error) setError("");
                    }}
                    disabled={isStillOpen}
                    placeholder={isStillOpen ? "Masih berlangsung" : "--:--"}
                    title={isStillOpen ? "Permintaan masih berlangsung" : "Waktu penyelesaian permintaan"}
                  />
                </label>
              </div>
            </div>
          )}
        </div>

        <div className="ticket-form-divider" />

        {/* ── Section 3: Details & Operational Notes ── */}
        <div className="ticket-form-section">
          <div className="ticket-section-header">
            <span className="ticket-section-title">Rincian & Catatan Operasional</span>
          </div>

          <label>
            <div className="ticket-field-label-wrapper">
              <span className="ticket-field-label">
                <AlignLeft size={12} className="ticket-field-icon" />
                OPERATIONAL NOTES
              </span>
            </div>
            <textarea
              rows={3}
              value={description}
              onChange={(event) => setDescription(event.target.value)}
              placeholder="Masukkan observasi rinci, langkah penanganan, kode error, atau instruksi terkait..."
            />
          </label>
        </div>
      </div>

      {error && (
        <div className="form-error-banner">
          <span className="form-error-icon">!</span>
          <span>{error}</span>
        </div>
      )}

      <p className="form-hint">
        Ticket disimpan otomatis dan langsung tersinkronisasi ke daftar antrean operasional.
      </p>

      <div className="modal-actions">
        <button className="button button-secondary" onClick={onClose} type="button">
          Batal
        </button>
        <button className="button button-primary" onClick={submit} type="button">
          <Check size={14} className="[display:inline-block]! [vertical-align:middle]! [margin-right:4px]!" /> Buat Ticket
        </button>
      </div>
    </Modal>
  );
}

"use client";

import { X, PlusCircle, MessageSquare, Headphones, CheckCircle2, Edit3, Clock, Tag, Zap } from "lucide-react";
import { Badge } from "@/app/components/ui/Badge";
import { Avatar } from "@/app/components/ui/Avatar";
import { ConfirmDialog } from "@/app/components/ui/ConfirmDialog";
import { ModalCloseButton } from "@/app/components/ui/ModalCloseButton";
import { TicketEditModal } from "@/app/components/tickets/TicketEditModal";
import { ProjectMark } from "@/app/components/ui/ProjectMark";
import { useToast } from "@/app/components/ui/Toast";
import { severityTone, statusTone } from "@/app/components/tickets/TicketTable";
import { useState } from "react";
import { nowClockLabel, initials } from "@/app/lib/data";
import { useAuth } from "@/app/lib/auth";
import type { Ticket } from "@/app/lib/types";

export type ActivityTypeLabel = "Tiket Dibuat" | "User Request" | "Kita Merespon" | "Tiket Closed" | "Tiket Open";

export interface ActivityTypeConfig {
  label: ActivityTypeLabel;
  icon: React.ComponentType<{ size?: number; strokeWidth?: number; style?: React.CSSProperties; className?: string }>;
  color: string;
  bgColor: string;
  borderColor: string;
}

export function getActivityConfig(type?: string, action?: string, ticketStatus?: string): ActivityTypeConfig {
  const normType = (type || "").toLowerCase().trim();
  const text = (action || "").toLowerCase();
  const normStatus = (ticketStatus || "").toLowerCase();

  // Helper: determine if activity or ticket context represents a Closed resolution
  const isClosingAction =
    text.includes("tutup") ||
    text.includes("closed") ||
    text.includes("selesai") ||
    text.includes("ditutup") ||
    text.includes("resolved") ||
    normType === "closed" ||
    normType === "tiket closed";

  const isOpeningAction =
    text.includes("dibuka kembali") ||
    text.includes("re-open") ||
    text.includes("reopened") ||
    text.includes("masih open") ||
    normType === "open" ||
    normType === "tiket open" ||
    normType === "re-open";

  // 1. Explicit type match
  if (normType === "created" || normType === "tiket dibuat" || normType === "ticket dibuat") {
    return {
      label: "Tiket Dibuat",
      icon: PlusCircle,
      color: "var(--accent-blue)",
      bgColor: "var(--accent-blue-soft)",
      borderColor: "var(--accent-blue-border)",
    };
  }

  if (normType === "user_request" || normType === "user request" || normType === "request") {
    return {
      label: "User Request",
      icon: MessageSquare,
      color: "var(--orange)",
      bgColor: "var(--orange-soft)",
      borderColor: "var(--orange-border)",
    };
  }

  if (normType === "response" || normType === "kita merespon" || normType === "respon") {
    return {
      label: "Kita Merespon",
      icon: Headphones,
      color: "var(--green)",
      bgColor: "var(--green-soft)",
      borderColor: "var(--green-border)",
    };
  }

  if (
    normType === "status_change" ||
    normType === "closed" ||
    normType === "open" ||
    normType === "tiket closed" ||
    normType === "tiket open" ||
    normType === "tiket closed / open"
  ) {
    if (isClosingAction || (!isOpeningAction && normStatus === "closed")) {
      return {
        label: "Tiket Closed",
        icon: CheckCircle2,
        color: "var(--purple)",
        bgColor: "var(--purple-soft)",
        borderColor: "var(--purple-border)",
      };
    }
    return {
      label: "Tiket Open",
      icon: Clock,
      color: "var(--red)",
      bgColor: "var(--red-soft)",
      borderColor: "var(--red-border)",
    };
  }

  // 2. Infer from action text when type is not explicitly provided (legacy or custom actions)
  if (text.includes("dibuat") || text.includes("created") || text.includes("alert trigger")) {
    return {
      label: "Tiket Dibuat",
      icon: PlusCircle,
      color: "var(--accent-blue)",
      bgColor: "var(--accent-blue-soft)",
      borderColor: "var(--accent-blue-border)",
    };
  }

  if (
    text.includes("request") ||
    text.includes("permintaan") ||
    text.includes("user") ||
    text.includes("requester") ||
    text.includes("menanyakan") ||
    text.includes("pemohon")
  ) {
    return {
      label: "User Request",
      icon: MessageSquare,
      color: "var(--orange)",
      bgColor: "var(--orange-soft)",
      borderColor: "var(--orange-border)",
    };
  }

  if (isClosingAction || normStatus === "closed") {
    return {
      label: "Tiket Closed",
      icon: CheckCircle2,
      color: "var(--purple)",
      bgColor: "var(--purple-soft)",
      borderColor: "var(--purple-border)",
    };
  }

  if (isOpeningAction) {
    return {
      label: "Tiket Open",
      icon: Clock,
      color: "var(--red)",
      bgColor: "var(--red-soft)",
      borderColor: "var(--red-border)",
    };
  }

  // Default fallback for operational responses, progress updates, and escalations
  return {
    label: "Kita Merespon",
    icon: Headphones,
    color: "var(--green)",
    bgColor: "var(--green-soft)",
    borderColor: "var(--green-border)",
  };
}

interface TicketDetailDrawerProps {
  ticket: Ticket | null;
  onClose: () => void;
  onUpdate: (ticket: Ticket) => void;
}

export function TicketDetailDrawer({ ticket, onClose, onUpdate }: TicketDetailDrawerProps) {
  const notify = useToast();
  const { user } = useAuth();
  const operatorName = user?.name || "Operator NOC";
  const [confirmClose, setConfirmClose] = useState(false);
  const [editModalOpen, setEditModalOpen] = useState(false);

  if (!ticket) return null;

  const escalate = () => {
    onUpdate({
      ...ticket,
      status: "Escalated",
      history: [
        ...(ticket.history ?? []),
        {
          time: nowClockLabel(),
          type: "response",
          action: "Tim merespon: ticket dieskalasikan ke Lead Operator untuk koordinasi eskalasi penanganan L2",
          author: operatorName,
        },
      ],
    });
    notify.info(`Ticket #${ticket.id} dieskalasikan ke Lead Operator.`, { id: `ticket-${ticket.id}` });
    onClose();
  };

  const markDone = () => {
    setConfirmClose(false);
    onUpdate({
      ...ticket,
      status: "Closed",
      history: [
        ...(ticket.history ?? []),
        {
          time: nowClockLabel(),
          type: "status_change",
          action: `Tiket ditutup oleh ${operatorName}`,
          author: operatorName,
        },
      ],
    });
    notify.success(`Ticket #${ticket.id} ditandai selesai.`, { id: `ticket-${ticket.id}` });
    onClose();
  };

  const sevTone = severityTone(ticket.severity);

  const ownersList: string[] =
    ticket.owners && ticket.owners.length > 0
      ? ticket.owners
      : ticket.owner
      ? ticket.owner
          .split(",")
          .map((s) => s.trim())
          .filter(Boolean)
      : ["Unassigned"];

  const categoryDisplay =
    ticket.category && ticket.category !== "--"
      ? ticket.category
      : ticket.type && ticket.type !== "--"
      ? ticket.type
      : null;

  const hasAdhocTimeline = Boolean(
    ticket.requestTime || ticket.responseTime || ticket.completionTime || ticket.isStillOpen
  );

  return (
    <>
      <div
        className="drawer-backdrop anim-fade"
        role="presentation"
        onMouseDown={(event) => {
          if (event.target === event.currentTarget) onClose();
        }}
      >
        <div className="drawer-body anim-slide-left" role="dialog" aria-modal="true" aria-label="Detail ticket">
          <div className="drawer-header">
            <div>
              <div className="[display:flex]! [gap:8px]! [align-items:center]! [margin-bottom:8px]! [flex-wrap:wrap]!">
                <Badge tone={sevTone}>Severity {ticket.severity}</Badge>
                <Badge tone={statusTone(ticket.status)}>{ticket.status}</Badge>
                {categoryDisplay && (
                  <Badge tone="neutral">
                    <Tag size={10} className="[margin-right:4px]! [vertical-align:middle]!" />
                    {categoryDisplay}
                  </Badge>
                )}
              </div>
              <h2 className="[font-size:18px]! [font-weight:700]! [margin:0]! [color:var(--ink-primary)]!">
                {ticket.subject}
              </h2>
              <span className="[font-size:11px]! [color:var(--ink-muted)]! [font-family:var(--font-mono)]!">
                ID Ticket: #{ticket.id} · Dibuat pukul {ticket.created}
              </span>
            </div>
            <ModalCloseButton onClose={onClose} label="Tutup panel" />
          </div>

          <div className="drawer-content-inner">
            {/* Proyek, Kategori & Penanggung Jawab */}
            <div className="drawer-meta-section [margin-bottom:20px]!">
              <span className="drawer-section-title">
                Proyek &amp; Penanggung Jawab
              </span>

              <div className="[display:flex]! [flex-direction:column]! [gap:12px]! [margin-top:10px]!">
                {/* Project & Category Row */}
                <div className="[display:flex]! [align-items:center]! [gap:16px]! [flex-wrap:wrap]!">
                  <div className="[display:flex]! [align-items:center]! [gap:10px]!">
                    <ProjectMark name={ticket.project} />
                    <div>
                      <strong className="[display:block]! [font-size:13px]! [color:var(--ink-primary)]!">
                        {ticket.project}
                      </strong>
                      <span className="[font-size:11px]! [color:var(--ink-muted)]!">
                        Proyek / Sistem
                      </span>
                    </div>
                  </div>

                  {categoryDisplay && (
                    <div className="[display:flex]! [align-items:center]! [gap:8px]! [padding-left:16px]! [border-left:1px_solid_var(--line,_rgba(255,_255,_255,_0.08))]!">
                      <div>
                        <strong className="[display:flex]! [align-items:center]! [gap:5px]! [font-size:13px]! [color:var(--ink-primary)]!">
                          <Tag size={12} className="[color:var(--accent-blue)]!" />
                          {categoryDisplay}
                        </strong>
                        <span className="[font-size:11px]! [color:var(--ink-muted)]!">
                          Kategori Tiket
                        </span>
                      </div>
                    </div>
                  )}
                </div>

                {/* Assignees (All Owners / PIC) */}
                <div className="[margin-top:2px]!">
                  <span className="[font-size:11px]! [color:var(--ink-muted)]! [display:block]! [margin-bottom:6px]! [font-weight:500]!">
                    Pemilik Tiket ({ownersList.length > 1 ? `${ownersList.length} PIC` : "PIC"}):
                  </span>
                  <div className="drawer-owners-list">
                    {ownersList.map((ownerName, idx) => (
                      <div key={idx} className="drawer-owner-entry">
                        <Avatar size="sm" name={ownerName} className="mini-avatar" />
                        <span className="drawer-owner-name">{ownerName}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {/* Timeline Permintaan Ad-hoc (Explicit Time Fields captured at creation) */}
            {hasAdhocTimeline && (
              <div className="drawer-adhoc-timeline [margin-bottom:22px]!">
                <div className="drawer-adhoc-header">
                  <span className="drawer-adhoc-badge">
                    <Zap size={11} className="[display:inline-block]! [vertical-align:middle]! [margin-right:4px]!" />
                    TIMELINE PERMINTAAN AD-HOC
                  </span>
                  <small className="[color:var(--ink-muted)]! [font-size:11px]!">
                    Waktu masuk, respon, dan penyelesaian operasional
                  </small>
                </div>

                <div className="drawer-adhoc-grid">
                  <div className="drawer-adhoc-cell">
                    <div className="drawer-adhoc-label">
                      <Clock size={11} className="drawer-adhoc-icon" />
                      <span>REQUEST TIME</span>
                    </div>
                    <div className="drawer-adhoc-value">
                      {ticket.requestTime || "—"}
                    </div>
                  </div>

                  <div className="drawer-adhoc-cell">
                    <div className="drawer-adhoc-label">
                      <Clock size={11} className="drawer-adhoc-icon" />
                      <span>RESPONSE TIME</span>
                    </div>
                    <div className="drawer-adhoc-value">
                      {ticket.responseTime || "—"}
                    </div>
                  </div>

                  <div className="drawer-adhoc-cell">
                    <div className="drawer-adhoc-label">
                      <CheckCircle2 size={11} className="drawer-adhoc-icon" />
                      <span>COMPLETION TIME</span>
                    </div>
                    <div className="drawer-adhoc-value">
                      {ticket.isStillOpen ? (
                        <span className="drawer-adhoc-still-open">
                          <span className="drawer-adhoc-pulse-dot" />
                          Masih berlangsung
                        </span>
                      ) : ticket.completionTime ? (
                        ticket.completionTime
                      ) : ticket.status === "Closed" ? (
                        "Selesai"
                      ) : (
                        <span className="drawer-adhoc-still-open">
                          <span className="drawer-adhoc-pulse-dot" />
                          Masih berlangsung
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            )}

            <div className="[margin-bottom:24px]!">
              <span className="drawer-section-title">
                Deskripsi / Catatan Operasional
              </span>
              <p className="[margin:8px_0_0]! [color:var(--ink-secondary)]! [font-size:13px]! [line-height:1.5]!">
                {ticket.description || "Item aktivitas operasional yang memerlukan pemeriksaan dan konfirmasi rutin."}
              </p>
            </div>

            <div>
              <span className="[font-size:11px]! [font-weight:700]! [color:var(--ink-muted)]! [font-family:var(--font-mono)]! [text-transform:uppercase]! [letter-spacing:0.5px]!">
                Riwayat aktivitas
              </span>
              <div className="[margin-top:12px]! [display:flex]! [flex-direction:column]! [gap:8px]!">
                {ticket.history?.length ? (
                  ticket.history.map((entry, index) => {
                    const config = getActivityConfig(entry.type, entry.action, ticket.status);
                    const IconComponent = config.icon;

                    return (
                      <div
                        key={index}
                        className="ticket-activity-entry [display:flex]! [align-items:center]! [justify-content:space-between]! [gap:10px]! [font-size:12px]! [padding:8px_12px]! [background:rgba(255,_255,_255,_0.025)]! [border:1px_solid_var(--line)]! [border-radius:7px]!"
                      >
                        {/* Time & Activity Badge */}
                        <div className="[display:flex]! [align-items:center]! [gap:10px]!">
                          <span className="[color:var(--ink-muted)]! [font-family:var(--font-mono)]! [font-weight:600]! [font-size:11px]! [min-width:40px]!">
                            {entry.time}
                          </span>

                          <span
                            className="activity-type-tag [display:inline-flex]! [align-items:center]! [gap:5px]! [padding:2px_7px]! [border-radius:4px]! [font-size:10.5px]! [font-weight:700]! [font-family:var(--font-mono)]! [line-height:1.3]! [color:var(--activity-tag-color)]! [background-color:var(--activity-tag-background)]! [border:1px_solid_var(--activity-tag-border)]!"
                            style={{
                              "--activity-tag-color": config.color,
                              "--activity-tag-background": config.bgColor,
                              "--activity-tag-border": config.borderColor,
                            } as React.CSSProperties}
                          >
                            <IconComponent size={11} strokeWidth={2.4} />
                            <span>{config.label}</span>
                          </span>
                        </div>

                        {/* Author */}
                        <span className="[color:var(--ink-muted)]! [font-size:11px]!">
                          oleh <strong className="[color:var(--ink-secondary)]! [font-weight:500]!">{entry.author}</strong>
                        </span>
                      </div>
                    );
                  })
                ) : (
                  <div className="[color:var(--ink-muted)]! [font-size:12px]!">
                    Belum ada riwayat aktivitas yang tercatat.
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="drawer-footer">
            <button
              type="button"
              className="button button-secondary [display:inline-flex]! [align-items:center]! [gap:6px]!"
              onClick={() => setEditModalOpen(true)}
            >
              <Edit3 size={13} />
              <span>Edit Ticket</span>
            </button>
            <button type="button" className="button button-secondary" onClick={escalate}>
              Eskalasi
            </button>
            <button
              type="button"
              className="button button-primary"
              onClick={() => {
                if (ticket.status === "Ditutup" || ticket.status === "Closed") {
                  notify.info(`Ticket #${ticket.id} sudah ditutup sebelumnya.`, { id: `ticket-${ticket.id}` });
                  return;
                }
                setConfirmClose(true);
              }}
            >
              Close Ticket
            </button>
          </div>
        </div>
      </div>

      <ConfirmDialog
        open={confirmClose}
        danger
        title={`Tutup ticket #${ticket.id}?`}
        message="Ticket akan ditandai Ditutup dan masuk ke riwayat aktivitas hari ini."
        confirmLabel="Ya, tutup ticket"
        onCancel={() => setConfirmClose(false)}
        onConfirm={markDone}
      />

      <TicketEditModal
        open={editModalOpen}
        ticket={ticket}
        onClose={() => setEditModalOpen(false)}
        onSave={(updated) => onUpdate(updated)}
      />
    </>
  );
}

