                                      {/* Right Bar: Bulan Ini (Sky Blue) */}
                                      <rect
                                        x={xCurr}
                                        y={yCurr}
                                        width={barWidth}
                                        height={Math.max(2, hCurr)}
                                        fill="#38bdf8"
