                                        y={baselineY + 19}
                                        textAnchor="start"
                                        fill={isSelected ? "#38bdf8" : "var(--ink-primary)"}
                                        fontSize="10"
                                        fontWeight={isSelected ? "700" : "600"}
                                      >
                                        {item.project}
                                      </text>
                                    </g>
                                  );
                                })}
                              </svg>
                            </div>
                          );
