                          </defs>

                          {/* ── 1. Horizontal Gridlines & Y-Axis Ticks ── */}
                          {ticks.map((tick) => {
                            const yPos = baselineY - Math.round((tick / yMax) * chartHeight);
                            const isSLA = tick === 60;
                            const isBaseline = tick === 0;

                            return (
                              <g key={`grid-res-${tick}`}>
                                <line
                                  x1={startX - 10}
                                  y1={yPos}
                                  x2={endX + 6}
                                  y2={yPos}
                                  stroke={
