                                        y={rectY}
                                        width={breachWidth}
                                        height={breachHeight}
                                        rx="4"
                                        fill={mobile ? "rgba(15,23,42,0.9)" : "#0f172a"}
                                        stroke="#ef4444"
                                        strokeWidth="1.2"
                                      />
                                      <text
                                        x={clampedX}
                                        y={rectY + breachHeight / 2}
                                        dominantBaseline="central"
                                        textAnchor="middle"
                                        fill="#f87171"
                                        fontSize="8.5"
                                        fontWeight="800"
                                        fontFamily="var(--font-mono)"
