                                  minHeight: `${dotSize}px`,
                                  maxWidth: `${dotSize}px`,
                                  maxHeight: `${dotSize}px`,
                                  borderRadius: "50%",
                                  transform: "translate(-50%, -50%)",
                                  backgroundColor: dotColor,
