                    if (p.count > maxOverallCount && p.count > 0) {
                      maxOverallCount = p.count;
                      foundPeak = { x: p.x, y: p.y, count: p.count, shiftName: series.name, date: p.date };
                    }
                  });
                });
                const peakPointMeta: ShiftPeakPoint | null = foundPeak;

