"use client";

import { useEffect, useState } from "react";
import { Plus } from "lucide-react";

interface FloatingNewTicketButtonProps {
  onClick: () => void;
  isOpen?: boolean;
  scrollHidden?: boolean;
  keyboardOpen?: boolean;
  onReveal?: () => void;
}

export function FloatingNewTicketButton({ onClick, isOpen = false, scrollHidden = false, keyboardOpen = false, onReveal }: FloatingNewTicketButtonProps) {
  const [mounted, setMounted] = useState(false);
  const [isHovered, setIsHovered] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ctrl+N or Cmd+N to open new ticket
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "n") {
        // Don't trigger if user is typing in an input/textarea
        const target = e.target as HTMLElement;
        if (
          target.tagName === "INPUT" ||
          target.tagName === "TEXTAREA" ||
          target.isContentEditable
        ) {
          return;
        }
        e.preventDefault();
        onClick();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [onClick]);

  if (!mounted) return null;

  const isExpanded = isHovered || isOpen;

  return (
    <button
      type="button"
      data-scroll-hidden={scrollHidden}
      data-keyboard-open={keyboardOpen}
      onFocus={onReveal}
      className={`fab-new-ticket group fixed bottom-[28px] right-[28px] z-[90] inline-flex items-center justify-center gap-0 h-[48px] min-w-[48px] border border-[rgba(255,255,255,0.16)] rounded-[9999px] cursor-pointer bg-[linear-gradient(135deg,#6366f1_0%,#7c3aed_100%)] text-[#ffffff] font-['Plus_Jakarta_Sans',sans-serif] text-[13.5px] font-bold tracking-[0.02em] [box-shadow:0_4px_14px_rgba(0,0,0,0.28),_0_1px_3px_rgba(0,0,0,0.15)] [will-change:right,_transform,_padding] [transition:right_0.35s_cubic-bezier(0.16,_1,_0.3,_1),_transform_0.2s_cubic-bezier(0.16,_1,_0.3,_1),_padding_0.3s_cubic-bezier(0.16,_1,_0.3,_1),_background_0.2s_ease,_box-shadow_0.2s_ease] overflow-hidden whitespace-nowrap hover:gap-[8px] hover:p-[0_18px_0_14px] hover:[transform:translateY(-2px)] hover:bg-[linear-gradient(135deg,#6d70f5_0%,#8b5cf6_100%)] hover:[box-shadow:0_6px_18px_rgba(0,0,0,0.35),_0_2px_6px_rgba(0,0,0,0.2)] active:[transform:translateY(0)_scale(0.97)] active:[box-shadow:0_2px_8px_rgba(0,0,0,0.25)] [.shift-panel-is-open_&]:right-[328px] [.shift-panel-is-open_&]:[transition:right_0.35s_cubic-bezier(0.16,_1,_0.3,_1)] max-[940px]:[.shift-panel-is-open_&]:right-[328px] max-[940px]:[.shift-panel-is-open_&]:[transform:none] max-[940px]:[.shift-panel-is-open_&]:opacity-0 max-[940px]:[.shift-panel-is-open_&]:pointer-events-none md:max-[940px]:h-[46px] md:max-[940px]:min-w-[46px] md:max-[940px]:p-[0_14px] md:max-[940px]:bottom-[20px] md:max-[940px]:right-[20px] max-md:bottom-[calc(68px+var(--ctd-safe-bottom,env(safe-area-inset-bottom,0px)))] max-md:right-3 max-md:size-[52px] max-md:min-w-[52px] max-md:p-0 max-md:gap-0 max-md:rounded-full motion-reduce:transition-none motion-reduce:[&.fab-new-ticket]:transition-none max-md:transition-[translate,opacity] max-md:duration-200 max-md:data-[scroll-hidden=true]:translate-y-4 max-md:data-[scroll-hidden=true]:opacity-0 max-md:data-[scroll-hidden=true]:pointer-events-none max-md:focus-visible:translate-y-0 max-md:focus-visible:opacity-100 max-md:focus-visible:pointer-events-auto max-lg:data-[keyboard-open=true]:invisible max-lg:data-[keyboard-open=true]:pointer-events-none [@media(max-height:499px)_and_(max-width:1023px)]:bottom-[calc(56px+env(safe-area-inset-bottom,0px))] [@media(max-height:499px)_and_(max-width:1023px)]:right-3 [@media(max-height:499px)_and_(max-width:1023px)]:data-[scroll-hidden=true]:opacity-0 [@media(max-height:499px)_and_(max-width:1023px)]:data-[scroll-hidden=true]:pointer-events-none ${
        isExpanded ? "fab-expanded gap-[8px] p-[0_18px_0_14px] [transform:translateY(-2px)] bg-[linear-gradient(135deg,#6d70f5_0%,#8b5cf6_100%)] [box-shadow:0_6px_18px_rgba(0,0,0,0.35),_0_2px_6px_rgba(0,0,0,0.2)]" : "p-[0_14px]"
      } ${isHovered ? "fab-hovered gap-[8px] p-[0_18px_0_14px] [transform:translateY(-2px)] bg-[linear-gradient(135deg,#6d70f5_0%,#8b5cf6_100%)] [box-shadow:0_6px_18px_rgba(0,0,0,0.35),_0_2px_6px_rgba(0,0,0,0.2)]" : ""} ${
        isOpen
          ? "fab-modal-open [box-shadow:0_0_0_3px_rgba(99,102,241,0.4),_0_6px_20px_rgba(0,0,0,0.35)]"
          : ""
      }`}
      onClick={onClick}
      onMouseEnter={() => { if (window.matchMedia("(hover: hover)").matches) setIsHovered(true); }}
      onMouseLeave={() => setIsHovered(false)}
      aria-label="Buat tiket baru (Ctrl+N)"
      title="New Ticket (Ctrl+N)"
    >
      <span className="fab-icon-wrap flex items-center justify-center w-[20px] h-[20px] shrink-0 [transition:transform_0.3s_cubic-bezier(0.34,_1.56,_0.64,_1)] group-hover:[transform:rotate(90deg)] [.fab-hovered_&]:[transform:rotate(90deg)]">
        <Plus size={20} strokeWidth={2.5} />
      </span>
      <span
        className={`fab-label inline-block overflow-hidden whitespace-nowrap text-[13.5px] font-bold tracking-[0.02em] text-[#ffffff] leading-none [transition:max-width_0.35s_cubic-bezier(0.16,_1,_0.3,_1),_opacity_0.25s_ease,_margin-left_0.35s_ease] group-hover:max-w-[120px] group-hover:opacity-100 group-hover:ml-[8px] max-md:hidden ${
          isExpanded
            ? "fab-label-visible max-w-[120px] opacity-100 ml-[8px]"
            : "max-w-0 opacity-0 ml-0"
        }`}
      >
        New Ticket
      </span>
    </button>
  );
}

import React from "react";
import { Skeleton as PremiumSkeleton, type SkeletonProps as PremiumSkeletonProps } from "./skeleton/Skeleton";

export type SkeletonProps = PremiumSkeletonProps;
export const Skeleton = PremiumSkeleton;

/**
 * Primitif Spinner:
 * SVG ring 16/20px warna currentColor untuk pengganti loader ad-hoc
 */
export function Spinner({
  size = 16,
  className = "",
}: {
  size?: number;
  className?: string;
}) {
  return (
    <svg
      className={`animate-spin text-current shrink-0 ${className}`}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <circle cx="12" cy="12" r="10" strokeOpacity="0.25" />
      <path d="M12 2a10 10 0 0 1 10 10" />
    </svg>
  );
}

/**
 * Kerangka Halaman: Cards Layout (Dashboard, Overview, Monitoring)
 * Dilengkapi animasi penunda 120ms anti-flicker tanpa JS
 */
export function DashboardCardsSkeleton() {
  return (
    <div
      role="status"
      aria-busy="true"
      className="w-full py-2 animate-fade-in-delayed"
    >
      <span className="sr-only">Memuat konten dashboard…</span>

      <div aria-hidden="true" className="w-full flex flex-col gap-5">
        {/* Row 4 kartu metrik */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map((i) => (
            <div
              key={i}
              className="p-4 rounded-[10px] border border-[#334155] bg-[#1e293b] flex flex-col justify-between min-h-[104px]"
            >
              <div className="flex items-center justify-between mb-3">
                <Skeleton height={14} width="55%" />
                <Skeleton height={20} width={20} borderRadius="50%" />
              </div>
              <Skeleton height={28} width="40%" className="mb-2" />
              <Skeleton height={12} width="75%" />
            </div>
          ))}
        </div>

        {/* Panel konten utama 2-kolom */}
        <div className="grid grid-cols-1 lg:grid-cols-[2fr_1fr] gap-5">
          {/* Panel kiri besar */}
          <div className="p-5 rounded-[10px] border border-[#334155] bg-[#1e293b] flex flex-col gap-4 min-h-[380px]">
            <div className="flex items-center justify-between border-b border-[#334155]/60 pb-3.5">
              <Skeleton height={18} width="35%" />
              <Skeleton height={28} width={90} borderRadius={6} />
            </div>
            {[1, 2, 3, 4, 5].map((i) => (
              <div key={i} className="flex items-center gap-3.5 py-2">
                <Skeleton height={36} width={36} borderRadius="50%" />
                <div className="flex-1 min-w-0 flex flex-col gap-1.5">
                  <Skeleton height={14} width="60%" />
                  <Skeleton height={11} width="35%" />
                </div>
                <Skeleton height={22} width={70} borderRadius={6} />
              </div>
            ))}
          </div>

          {/* Panel kanan kecil */}
          <div className="p-5 rounded-[10px] border border-[#334155] bg-[#1e293b] flex flex-col gap-4 min-h-[380px]">
            <div className="border-b border-[#334155]/60 pb-3.5">
              <Skeleton height={18} width="50%" />
            </div>
            <Skeleton height={140} width="100%" borderRadius={8} />
            <Skeleton height={14} width="75%" />
            <Skeleton height={14} width="90%" />
            <Skeleton height={14} width="60%" />
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Kerangka Halaman: Table Layout (Tickets, Team Roster, Shift Log, Reports)
 */
export function TableSkeleton() {
  return (
    <div
      role="status"
      aria-busy="true"
      className="w-full py-2 animate-fade-in-delayed"
    >
      <span className="sr-only">Memuat tabel data…</span>

      <div aria-hidden="true" className="w-full rounded-[10px] border border-[#334155] bg-[#1e293b] overflow-hidden flex flex-col">
        {/* Toolbar bar */}
        <div className="p-3.5 border-b border-[#334155] flex flex-wrap items-center justify-between gap-3 bg-[#1e293b]">
          <Skeleton height={36} width={260} borderRadius={8} />
          <div className="flex items-center gap-2">
            <Skeleton height={36} width={120} borderRadius={8} />
            <Skeleton height={36} width={120} borderRadius={8} />
          </div>
        </div>

        {/* Table header */}
        <div className="p-3 border-b border-[#334155] bg-[#0f172a] flex items-center justify-between gap-4">
          <Skeleton height={14} width="20%" />
          <Skeleton height={14} width="25%" />
          <Skeleton height={14} width="15%" />
          <Skeleton height={14} width="15%" />
          <Skeleton height={14} width="10%" />
        </div>

        {/* Table rows */}
        {[1, 2, 3, 4, 5, 6].map((i) => (
          <div
            key={i}
            className="p-3.5 border-b border-[#334155]/50 last:border-b-0 flex items-center justify-between gap-4"
          >
            <div className="flex items-center gap-3 w-[20%]">
              <Skeleton height={28} width={28} borderRadius="50%" />
              <Skeleton height={13} width="65%" />
            </div>
            <Skeleton height={13} width="25%" />
            <Skeleton height={20} width="15%" borderRadius={6} />
            <Skeleton height={13} width="15%" />
            <Skeleton height={26} width={60} borderRadius={6} />
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * Kerangka Halaman: Detail / Form Layout (Profile, Runbooks, Handover)
 */
export function DetailSkeleton() {
  return (
    <div
      role="status"
      aria-busy="true"
      className="w-full py-2 animate-fade-in-delayed"
    >
      <span className="sr-only">Memuat informasi formulir…</span>

      <div aria-hidden="true" className="w-full flex flex-col gap-5">
        <div className="p-6 rounded-[10px] border border-[#334155] bg-[#1e293b] flex items-center gap-4">
          <Skeleton height={56} width={56} borderRadius="50%" />
          <div className="flex-1 flex flex-col gap-2">
            <Skeleton height={20} width="35%" />
            <Skeleton height={13} width="20%" />
          </div>
        </div>

        <div className="p-6 rounded-[10px] border border-[#334155] bg-[#1e293b] flex flex-col gap-4">
          <Skeleton height={16} width="25%" />
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="flex flex-col gap-2">
                <Skeleton height={12} width="30%" />
                <Skeleton height={38} width="100%" borderRadius={8} />
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import { DashboardSkeleton } from "./skeleton/DashboardSkeleton";
export * from "./skeleton";

/**
 * Backward-compatible wrapper untuk DashboardViewSkeleton
 */
export function DashboardViewSkeleton() {
  return <DashboardSkeleton />;
}

import React from "react";

interface NoImagePlaceholderProps {
  className?: string;
  width?: number | string;
  height?: number | string;
}

export function NoImagePlaceholder({
  className = "",
  width,
  height,
}: NoImagePlaceholderProps) {
  return (
    <div
      className={`[display:inline-flex] [flex-direction:column] [align-items:center] [justify-content:center] [width:44px] [height:36px] [min-width:44px] [border-radius:6px] [background:rgba(255,_255,_255,_0.04)] [border:1px_solid_rgba(255,_255,_255,_0.12)] [color:var(--ink-muted)] [flex-shrink:0] [box-sizing:border-box] [padding:3px_2px_2px] [gap:2px] [user-select:none] [transition:all_0.2s_ease] [&:hover]:[background:rgba(255,_255,_255,_0.07)] [&:hover]:[border-color:rgba(255,_255,_255,_0.22)] ${className}`}
      style={{
        ...(width ? { width } : {}),
        ...(height ? { height } : {}),
      }}
      aria-label="No Image"
      title="No Image Available"
    >
      <svg
        className="[width:19px] [height:15px] [color:rgba(148,_163,_184,_0.7)] [flex-shrink:0]"
        viewBox="0 0 24 20"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        aria-hidden="true"
      >
        {/* Photo frame outline */}
        <rect
          x="1"
          y="1"
          width="22"
          height="18"
          rx="3"
          stroke="currentColor"
          strokeWidth="1.5"
          className="no-image-frame"
        />
        {/* Sun circle */}
        <circle cx="6.5" cy="5.5" r="1.5" fill="currentColor" className="no-image-sun" />
        {/* Mountain peaks */}
        <path
          d="M2.5 16.5L8.5 9.5L14 15L17.5 11.5L21.5 16.5"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="no-image-mountains"
        />
      </svg>
      <span className="[font-size:7.5px] [font-weight:700] [letter-spacing:0.2px] [line-height:1] [color:rgba(148,_163,_184,_0.85)] [white-space:nowrap] [font-family:var(--font-sans)]">No Image</span>
    </div>
  );
}

