          <div>
            <span className="text-[11px] font-bold text-slate-400 uppercase tracking-wider block">Sinkronisasi</span>
            <div className="flex items-baseline gap-1.5 mt-1">
              <strong className="text-[14px] font-mono font-bold text-emerald-400 flex items-center gap-1.5">
                <CheckCircle2 size={15} />
                <span>Tersimpan {syncTime}</span>
              </strong>
            </div>
            <span className="text-[10px] text-slate-400">Lokal &amp; Multi-tab aktif</span>
          </div>
          <span className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 grid place-items-center">
            <CheckCircle2 size={18} />
          </span>
        </div>
      </div>

      {/* ── Tab Bar Navigation ── */}
      <div
        className="flex items-center gap-2 border-b border-slate-700/80 pb-0 overflow-x-auto [scrollbar-width:none] shrink-0"
        role="tablist"
        aria-label="Navigasi kategori master data"
      >
        <button
          ref={(el) => {
            tabButtonRefs.current[0] = el;
          }}
          type="button"
          role="tab"
          id="tab-clients"
          aria-selected={activeTab === "clients"}
          aria-controls="tabpanel-clients"
          tabIndex={activeTab === "clients" ? 0 : -1}
          onClick={() => switchTab("clients")}
          onKeyDown={(e) => handleTabKeyDown(e, 0)}
          className={`flex items-center gap-2 px-4 py-2.5 text-[13px] font-bold transition-all border-b-2 cursor-pointer select-none whitespace-nowrap ${
            activeTab === "clients"
              ? "border-sky-400 text-sky-400 bg-sky-500/10 rounded-t-lg"
              : "border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/40"
          }`}
        >
          <Building2 size={16} />
          <span>Klien / Organisasi</span>
          <span className="px-1.5 py-0.2 rounded-full text-[10.5px] font-mono bg-slate-800 text-slate-300">
            {allClients.length}
          </span>
        </button>

        <button
          ref={(el) => {
            tabButtonRefs.current[1] = el;
          }}
          type="button"
          role="tab"
          id="tab-projects"
          aria-selected={activeTab === "projects"}
          aria-controls="tabpanel-projects"
          tabIndex={activeTab === "projects" ? 0 : -1}
          onClick={() => switchTab("projects")}
          onKeyDown={(e) => handleTabKeyDown(e, 1)}
          className={`flex items-center gap-2 px-4 py-2.5 text-[13px] font-bold transition-all border-b-2 cursor-pointer select-none whitespace-nowrap ${
            activeTab === "projects"
              ? "border-sky-400 text-sky-400 bg-sky-500/10 rounded-t-lg"
              : "border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/40"
          }`}
        >
          <Layers size={16} />
          <span>Proyek &amp; Layanan</span>
          <span className="px-1.5 py-0.2 rounded-full text-[10.5px] font-mono bg-slate-800 text-slate-300">
            {projects.length}
          </span>
        </button>

        <button
          ref={(el) => {
            tabButtonRefs.current[2] = el;
          }}
          type="button"
          role="tab"
          id="tab-systems"
          aria-selected={activeTab === "systems"}
          aria-controls="tabpanel-systems"
          tabIndex={activeTab === "systems" ? 0 : -1}
          onClick={() => switchTab("systems")}
          onKeyDown={(e) => handleTabKeyDown(e, 2)}
          className={`flex items-center gap-2 px-4 py-2.5 text-[13px] font-bold transition-all border-b-2 cursor-pointer select-none whitespace-nowrap ${
            activeTab === "systems"
              ? "border-sky-400 text-sky-400 bg-sky-500/10 rounded-t-lg"
              : "border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/40"
          }`}
        >
          <Cpu size={16} />
          <span>Sistem &amp; Sub-Layanan</span>
          <span className="px-1.5 py-0.2 rounded-full text-[10.5px] font-mono bg-slate-800 text-slate-300">
            {systems.length}
          </span>
        </button>
      </div>

      {/* ── Active Tab Panel ── */}
      <div
        role="tabpanel"
        id={`tabpanel-${activeTab}`}
        aria-labelledby={`tab-${activeTab}`}
        className="w-full focus:outline-none"
        tabIndex={0}
      >
        {activeTab === "clients" && (
          <ClientListTab
            clients={allClients}
            projects={projects}
            systems={systems}
            search={clientSearch}
            onSearchChange={setClientSearch}
            statusFilter={clientStatusFilter}
            onStatusFilterChange={setClientStatusFilter}
            onAddClient={handleOpenAddClient}
            onEditClient={handleOpenEditClient}
            onManageProjects={handleManageProjectsForClient}
            onToggleArchive={handleToggleArchiveClient}
          />
        )}

        {activeTab === "projects" && (
          <ProjectListTab
            projects={projects}
            clients={allClients}
            systems={systems}
            schedules={getClientMonitoringSchedule(projectClientFilter !== "all" ? projectClientFilter : activeClientId)}
            selectedClientId={projectClientFilter}
            onSelectedClientIdChange={(id) => {
              setInternalProjectClient(id);
              switchTab("projects", id);
            }}
            search={projectSearch}
            onSearchChange={setProjectSearch}
            statusFilter={projectStatusFilter}
            onStatusFilterChange={setProjectStatusFilter}
            onAddProject={() => handleOpenAddProject()}
            onEditProject={handleOpenEditProject}
            onViewProjectDetail={(p) => setDetailProject(p)}
            onToggleArchive={handleToggleArchiveProject}
          />
        )}

        {activeTab === "systems" && (
          <SystemListTab
            systems={systems}
            projects={projects}
            clients={allClients}
            selectedClientId={systemClientFilter}
            onSelectedClientIdChange={(id) => {
              setInternalSystemClient(id);
              switchTab("systems", id);
            }}
            selectedProjectId={systemProjectFilter}
            onSelectedProjectIdChange={setSystemProjectFilter}
            search={systemSearch}
            onSearchChange={setSystemSearch}
            criticalityFilter={systemCritFilter}
            onCriticalityFilterChange={setSystemCritFilter}
            environmentFilter={systemEnvFilter}
            onEnvironmentFilterChange={setSystemEnvFilter}
            statusFilter={systemStatusFilter}
            onStatusFilterChange={setSystemStatusFilter}
            onAddSystem={handleOpenAddSystem}
            onEditSystem={handleOpenEditSystem}
            onToggleStatus={handleToggleSystemStatus}
          />
        )}
      </div>

      {/* ── Modal Dialogs ── */}
      {clientModalOpen && (
        <ClientFormModal
          open={clientModalOpen}
          initialData={editingClient}
          existingClients={allClients}
          onSave={async (data) => {
            if (editingClient) {
              await updateClient(editingClient.id, data as UpdateClientInput);
            } else {
              await addClient(data as CreateClientInput);
            }
          }}
          onClose={() => setClientModalOpen(false)}
        />
      )}

      {projectModalOpen && (
        <ProjectFormModal
          open={projectModalOpen}
          initialData={editingProject}
          defaultClientId={projectDefaultClient}
          clients={activeClients}
          existingProjects={projects}
          onSave={async (data) => {
            if (editingProject) {
              await updateProject(editingProject.id, data as UpdateProjectInput);
            } else {
              await addProject(data as CreateProjectInput);
            }
          }}
          onClose={() => setProjectModalOpen(false)}
        />
      )}

      {systemModalOpen && (
        <SystemFormModal
          open={systemModalOpen}
          initialData={editingSystem}
          defaultClientId={systemClientFilter !== "all" ? systemClientFilter : activeClientId}
          defaultProjectId={systemProjectFilter !== "all" ? systemProjectFilter : ""}
          clients={activeClients}
          projects={projects}
          onSave={async (data) => {
            if (editingSystem) {
              await updateSystem(editingSystem.id, data as UpdateSystemInput);
            } else {
              await addSystem(data as CreateSystemInput);
            }
          }}
          onClose={() => setSystemModalOpen(false)}
        />
      )}

      {/* ── Project Detail Slide-Out Drawer ── */}
      {detailProject && (
        <ProjectDetailDrawer
          project={detailProject}
          client={allClients.find((c) => c.id === detailProject.clientId)}
          systems={systems.filter((s) => s.projectId === detailProject.id)}
          checkpointCount={
            getClientMonitoringSchedule(detailProject.clientId).filter(
              (s) => s.project === detailProject.name,
            ).length
          }
          onClose={() => setDetailProject(null)}
          onEdit={(p) => {
            setDetailProject(null);
            handleOpenEditProject(p);
          }}
          onToggleArchive={(p) => {
            handleToggleArchiveProject(p);
          }}
        />
      )}

      {/* ── Confirm Archive Dialog ── */}
      {archiveDialogConfig.open && (
        <ConfirmArchiveDialog
          open={archiveDialogConfig.open}
          title={archiveDialogConfig.title}
          itemName={archiveDialogConfig.itemName}
          itemType={archiveDialogConfig.itemType}
          action={archiveDialogConfig.action}
          activeTicketsCount={archiveDialogConfig.activeTicketsCount}
          activeCheckpointsCount={archiveDialogConfig.activeCheckpointsCount}
          subItemsCount={archiveDialogConfig.subItemsCount}
          subItemLabel={archiveDialogConfig.subItemLabel}
          onConfirm={archiveDialogConfig.onConfirm}
          onClose={() => setArchiveDialogConfig((prev) => ({ ...prev, open: false }))}
        />
      )}
    </div>
  );
}

"use client";
import Link from "next/link";
import { useUrlQuery } from "@/app/hooks/useUrlQuery";
import { monitoringSchema } from "@/app/lib/query-state";
import { paths, withQuery } from "@/app/lib/routes";

import { useMemo, useState, useEffect, useRef, useCallback } from "react";
import {
  CheckCircle2,
  AlertTriangle,
  Layers,
  Clock,
  Activity,
  Server,
  HardDrive,
  Radio,
  Cpu,
  BookOpen,
  Check,
  ChevronLeft,
  ChevronRight,
  Flame,
  Grid,
  SlidersHorizontal,
} from "lucide-react";
import { MonitoringSchedule, rowKey, matchesProject, CLIENT_MONITORING_SYSTEMS } from "@/app/components/dashboard/MonitoringSchedule";
import { MonitoringHistorySection } from "@/app/components/monitoring/MonitoringHistorySection";
import { StatCard, type StatAccentColor } from "@/app/components/ui/StatCard";
import { useActiveShift } from "@/app/hooks/useLiveClock";
import type { CheckpointAssessment } from "@/app/lib/types";
import { useClient } from "@/app/context/ClientContext";
import { getClientMonitoringSchedule, getClientProjects } from "@/app/lib/clientData";
import { useResource } from "@/app/hooks/useResource";
import { monitoringService } from "@/app/services/monitoring";
import { PanelSkeletonWrapper, MonitoringScheduleSkeleton } from "@/app/components/ui/skeleton";

interface MonitoringViewProps {
  assessments: Record<string, CheckpointAssessment>;
  onAssess: (key: string, verdict: "ok" | "nok" | "adequate" | "not-adequate" | null) => void;
  onRequestNote: (key: string) => void;
  onUpdateNote?: (key: string, note: string) => void;
  onOpenGuide: () => void;
  currentHour: string;
}

export function MonitoringView({
  assessments,
  onAssess,
  onRequestNote,
  onUpdateNote,
  onOpenGuide,
  currentHour,
}: MonitoringViewProps) {
  const { activeClient, activeClientId, projects: masterProjects } = useClient();
  const defaultSchedule = useMemo(() => getClientMonitoringSchedule(activeClientId), [activeClientId]);
  const defaultProjects = useMemo(() => {
    const activeClientProjects = masterProjects.filter((p) => p.clientId === activeClientId && p.status === "active");
    if (activeClientProjects.length > 0) {
      return activeClientProjects.map((p) => ({
        name: p.name,
        detail: p.detail,
        tone: (p.healthDefault === "degraded" ? "warning" : "neutral") as "warning" | "neutral",
        clientId: p.clientId,
      }));
    }
    return getClientProjects(activeClientId);
  }, [activeClientId, masterProjects]);

  const {
    data: fetchedMonitoring,
    isLoading,
    isStale,
    error,
    refetch,
  } = useResource(
    `monitoring-view-${activeClientId}`,
    (signal) => monitoringService.getMonitoringData(activeClientId, signal),
    {
      deps: [activeClientId, masterProjects],
    }
  );

  const schedule = fetchedMonitoring?.schedule ?? defaultSchedule;
  const projects = fetchedMonitoring?.projects ?? defaultProjects;

  const schema = useMemo(() => monitoringSchema(projects.map(p => p.name), CLIENT_MONITORING_SYSTEMS[activeClientId] ?? CLIENT_MONITORING_SYSTEMS.tritronik), [projects, schedule]);
  const url = useUrlQuery(schema, paths.monitoring);
  const activeShift = useActiveShift();
  const shiftAccent: StatAccentColor = activeShift.id === "subuh" ? "blue" : activeShift.id === "pagi" ? "amber" : "purple";
  const activeTab = url.pathname === paths.monitoringHistory ? "history" : "live";
  const selectedProject = url.values.project || null;
  const setSelectedProject = (value: string | null) => url.update({ project: value ?? "" });

  // Status filter for project cards: "all" | "urgent" | "healthy"
  const statusFilter = url.values.health;
  const setStatusFilter = url.field("health", "replace");
  // Expanded mode (multi-row grid) vs carousel mode (single-row with scroll)
  const [isExpanded, setIsExpanded] = useState(false);

  // Carousel scroll ref & states
  const scrollRef = useRef<HTMLDivElement>(null);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(false);
  const [scrollIndex, setScrollIndex] = useState(0);
  const [visibleCardsCount, setVisibleCardsCount] = useState(4);

  // Auto-reset project filter when active client changes


  // Assessed entries list
  const assessedEntries = useMemo(
    () =>
      Object.entries(assessments)
        .map(([key, assessment]) => ({
          key,
          assessment,
          entry: schedule.find((item) => rowKey(item) === key),
        }))
        .filter(
          (item): item is { key: string; assessment: CheckpointAssessment; entry: (typeof schedule)[number] } =>
            Boolean(item.entry),
        )
        .reverse(),
    [assessments, schedule],
  );

  // Summary Metrics
  const totalCheckpoints = schedule.length;
  const adequateCount = assessedEntries.filter(
    (item) => item.assessment.verdict === "ok" || item.assessment.verdict === "adequate",
  ).length;
  const notAdequateCount = assessedEntries.filter(
    (item) => item.assessment.verdict === "nok" || item.assessment.verdict === "not-adequate",
  ).length;
  const totalAssessed = adequateCount + notAdequateCount;

  // Percentage & proportion calculations
  const okRate = totalAssessed > 0 ? Math.round((adequateCount / totalAssessed) * 100) : 100;
  const nokRate = totalAssessed > 0 ? Math.round((notAdequateCount / totalAssessed) * 100) : 0;
  const completedPct = Math.round((totalAssessed / totalCheckpoints) * 100);

  const hours = useMemo(() => Array.from(new Set(schedule.map((item) => item.time))), [schedule]);

  // Project breakdown stats with health and OK/NOK breakdown
  const projectStats = useMemo(() => {
    return projects.map((projEntry) => {
      const projectName = projEntry.name;
      const items = schedule.filter((item) => matchesProject(item.project, projectName));
      const total = items.length;

      let okCount = 0;
      let nokCount = 0;

      items.forEach((item) => {
        const key = rowKey(item);
        const a = assessments[key];
        if (a) {
          if (a.verdict === "ok" || a.verdict === "adequate") okCount++;
          if (a.verdict === "nok" || a.verdict === "not-adequate") nokCount++;
        } else if (item.tone === "warning") {
          // If unassessed but scheduled as warning in base data
          nokCount++;
        }
      });

      const hasNok = nokCount > 0;

      return {
        project: projectName,
        detail: projEntry.detail,
        total,
        okCount,
        nokCount,
        hasNok,
      };
    });
  }, [projects, schedule, assessments]);

  // Tally of projects with NOK vs All OK
  const urgentCount = useMemo(() => projectStats.filter((p) => p.hasNok).length, [projectStats]);
  const healthyCount = useMemo(() => projectStats.filter((p) => !p.hasNok).length, [projectStats]);

  // Distressed/NOK projects first (matching Overview priority triage)
  const sortedProjectStats = useMemo(() => {
    return [...projectStats].sort((a, b) => {
      if (a.hasNok && !b.hasNok) return -1;
      if (!a.hasNok && b.hasNok) return 1;
      return a.project.localeCompare(b.project);
    });
  }, [projectStats]);

  // Apply filter
  const displayStats = useMemo(() => {
    if (statusFilter === "urgent") {
      return sortedProjectStats.filter((p) => p.hasNok);
    }
    if (statusFilter === "healthy") {
      return sortedProjectStats.filter((p) => !p.hasNok);
    }
    return sortedProjectStats;
  }, [sortedProjectStats, statusFilter]);

  const displayCount = displayStats.length;

  const updateScrollState = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;
    const { scrollLeft, scrollWidth, clientWidth } = el;
    // 2px tolerance for subpixel rounding
    setCanScrollLeft(scrollLeft > 2);
    setCanScrollRight(scrollLeft < scrollWidth - clientWidth - 2 && scrollWidth > clientWidth + 2);

    const firstCard = el.querySelector(".system-compact-card") as HTMLElement | null;
    const cardWidth = firstCard ? firstCard.offsetWidth + 12 : 258;
    const visible = firstCard ? Math.max(1, Math.floor((clientWidth + 12) / cardWidth)) : 5;
    setVisibleCardsCount(visible);
    const idx = Math.min(Math.round(scrollLeft / cardWidth), Math.max(0, displayCount - 1));
    setScrollIndex(Math.max(0, idx));
  }, [displayCount]);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;

    updateScrollState();

    el.addEventListener("scroll", updateScrollState, { passive: true });
    window.addEventListener("resize", updateScrollState);

    let ro: ResizeObserver | null = null;
    let roRafId: number | null = null;
    if (typeof ResizeObserver !== "undefined") {
      ro = new ResizeObserver(() => {
        if (roRafId !== null) cancelAnimationFrame(roRafId);
        roRafId = requestAnimationFrame(() => {
          updateScrollState();
        });
      });
      ro.observe(el);
      const firstCard = el.querySelector(".system-compact-card");
      if (firstCard) {
        ro.observe(firstCard);
      }
    }

    return () => {
      if (roRafId !== null) cancelAnimationFrame(roRafId);
      el.removeEventListener("scroll", updateScrollState);
      window.removeEventListener("resize", updateScrollState);
      ro?.disconnect();
    };
  }, [updateScrollState, isExpanded, displayCount]);

  // Recalculate accurately after DOM reflow and 200ms card transition when toggling back from grid to carousel
  useEffect(() => {
    if (isExpanded) return;
    updateScrollState();
    const frameId = requestAnimationFrame(() => {
      updateScrollState();
    });
    const t1 = setTimeout(updateScrollState, 100);
    const t2 = setTimeout(updateScrollState, 250);
    return () => {
      cancelAnimationFrame(frameId);
      clearTimeout(t1);
      clearTimeout(t2);
    };
  }, [isExpanded, updateScrollState]);

  const scroll = (direction: "left" | "right") => {
    const el = scrollRef.current;
    if (!el) return;
    const firstCard = el.querySelector(".system-compact-card") as HTMLElement | null;
    const cardStride = firstCard ? firstCard.offsetWidth + 12 : 258;
    const step = cardStride * Math.max(1, Math.min(3, visibleCardsCount));
    const maxLeft = Math.max(0, el.scrollWidth - el.clientWidth);
    const target = Math.min(
      maxLeft,
      Math.max(0, el.scrollLeft + (direction === "left" ? -step : step)),
    );
    el.scrollTo({ left: target, behavior: "smooth" });
    // Refresh button state once the smooth scroll settles (scroll events can be missed)
    window.setTimeout(updateScrollState, 350);
  };

  // Project icon helper
  const getProjectIcon = (name: string) => {
    switch (name) {
      case "Core Banking":
      case "OCS Billing":
      case "SM":
        return <Server size={14} />;
      case "Switching ATM":
      case "SMSC Core":
      case "B2B":
        return <Radio size={14} />;
      case "BNI Mobile":
      case "MyTelkomsel":
      case "MB":
        return <Activity size={14} />;
      case "Fraud Shield":
      case "5G Edge":
      case "USIEM":
        return <Cpu size={14} />;
      case "Card Mgmt":
      case "HLR/HSS":
      case "DM":
        return <HardDrive size={14} />;
      default:
        return <Layers size={14} />;
    }
  };

  return (
    <>
      {/* ── Page Header ── */}
      <section className="flex flex-wrap justify-between items-end gap-3 mb-6">
        <div>
          <div className="flex items-center gap-2 text-[10px] font-mono font-bold tracking-[1px] text-[#94a3b8] uppercase">
            <span className="w-[7px] h-[7px] rounded-full bg-[#4ade80] animate-pulse shrink-0" />
            <span>MONITORING · {activeClient.code}</span>
          </div>
          <h1 className="text-[24px] font-bold text-[#f8fafc] leading-[1.2] tracking-[-0.4px] my-[6px_4px]">Monitoring</h1>
        </div>
        <div className="flex gap-[9px]">
          <button
            type="button"
            className="inline-flex items-center justify-center gap-2 h-[34px] px-3.5 rounded-[8px] text-[12px] font-semibold text-[#f8fafc] border border-[#334155] bg-[#1e293b] hover:bg-[#243044] hover:border-[#475569] shadow-sm transition-all duration-150 cursor-pointer whitespace-nowrap focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#38bdf8] focus-visible:ring-offset-2 focus-visible:ring-offset-[#0f172a] active:scale-[0.98]"
            onClick={onOpenGuide}
          >
            <BookOpen size={14} className="text-[#38bdf8]" />
            <span>Panduan Penilaian (Guide)</span>
          </button>
        </div>
      </section>

      {/* ── Sub-Navigation Switcher (Monitoring Sekarang / Log Monitoring) ── */}
      <div className="flex items-center gap-2 mb-6 border-b border-[#334155] pb-3 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden" role="tablist" aria-label="Navigasi view monitoring">
        <Link

          role="tab"
          aria-selected={activeTab === "live"}
          className={`inline-flex items-center text-center gap-2 px-3.5 py-[7px] rounded-[8px] border text-[12px] font-semibold transition-all cursor-pointer select-none focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#38bdf8] focus-visible:ring-offset-2 focus-visible:ring-offset-[#0f172a] ${
            activeTab === "live"
              ? "bg-[#1e293b] border-[#334155] text-[#38bdf8] font-bold shadow-[0_1px_3px_rgba(0,0,0,0.2)]"
              : "border-transparent bg-transparent text-[#94a3b8] hover:bg-[#243044] hover:text-[#f8fafc]"
          }`}
          href={withQuery(paths.monitoring, url.query)} scroll={false}
        >
          <Activity size={14} className={activeTab === "live" ? "text-[#38bdf8]" : "text-[#94a3b8]"} />
          <span>Monitoring Sekarang</span>
          <span
            className={`inline-flex items-center px-1.5 py-[1px] rounded-full text-[10px] font-mono font-bold leading-none ${
              activeTab === "live"
                ? "bg-[rgba(56,189,248,0.15)] text-[#38bdf8]"
                : "bg-[rgba(148,163,184,0.12)] text-[#94a3b8]"
            }`}
          >
            {totalCheckpoints}
          </span>
        </Link>

        <Link

          role="tab"
          aria-selected={activeTab === "history"}
          className={`inline-flex items-center text-center gap-2 px-3.5 py-[7px] rounded-[8px] border text-[12px] font-semibold transition-all cursor-pointer select-none focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#38bdf8] focus-visible:ring-offset-2 focus-visible:ring-offset-[#0f172a] ${
            activeTab === "history"
              ? "bg-[#1e293b] border-[#334155] text-[#38bdf8] font-bold shadow-[0_1px_3px_rgba(0,0,0,0.2)]"
              : "border-transparent bg-transparent text-[#94a3b8] hover:bg-[#243044] hover:text-[#f8fafc]"
          }`}
          href={withQuery(paths.monitoringHistory, url.query)} scroll={false}
        >
          <Clock size={14} className={activeTab === "history" ? "text-[#38bdf8]" : "text-[#94a3b8]"} />
          <span>Log Monitoring</span>
          {notAdequateCount > 0 ? (
