/**
 * Mengambil akun testing lokal (hanya aktif di PC/lokal, tidak pernah di-push ke git)
 * Sumber: .env.local (terabaikan git via .gitignore) atau localStorage browser.
 */
export function getLocalTestOperator(): PresetOperator | null {
  const envEmail = process.env.NEXT_PUBLIC_LOCAL_TEST_EMAIL;
  if (envEmail) {
    return {
      id: "op-local-test",
      name: process.env.NEXT_PUBLIC_LOCAL_TEST_NAME || "Local Test Operator",
      employeeId: process.env.NEXT_PUBLIC_LOCAL_TEST_EMPLOYEE_ID || "EMP-LOCAL",
      role: process.env.NEXT_PUBLIC_LOCAL_TEST_ROLE || "Operator NOC",
      email: envEmail,
      avatarBg: "#2563eb",
      shift: (process.env.NEXT_PUBLIC_LOCAL_TEST_SHIFT as "Subuh" | "Pagi" | "Malam") || "Malam",
      title: "Akun Testing Lokal",
      badge: "Testing Lokal",
      demoPassword: process.env.NEXT_PUBLIC_LOCAL_TEST_PASSWORD || "",
    };
  }

  if (typeof window !== "undefined") {
    try {
      const stored = localStorage.getItem("ctd.local_test_account");
      if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed.email && parsed.password) {
          return {
            id: "op-local-test",
            name: parsed.name || "Mhd. Galih Khairi",
            employeeId: parsed.employeeId || "EMP-1001",
            role: parsed.role || "Operator NOC",
            email: parsed.email,
            avatarBg: parsed.avatarBg || "#2563eb",
            shift: parsed.shift || "Malam",
            title: "Akun Testing Lokal",
            badge: "Testing Lokal",
            demoPassword: parsed.password,
          };
        }
      }
    } catch {
      // Ignore parse error
    }
  }

  return null;
}

interface AuthContextValue {
  user: AuthUser | null;
  ready: boolean;
  isAuthenticated: boolean;
  token: string | null;
  login: (token: string, user: AuthUser) => void;
  logout: () => void;
  can: (action: "create" | "edit" | "delete" | "escalate" | "admin", resource: "ticket" | "handover" | "roster" | "system") => boolean;
}

const AuthContext = createContext<AuthContextValue | null>(null);

const TOKEN_STORAGE_KEY = "ctd.auth_token";
const USER_STORAGE_KEY = "ctd.auth_user";
const LOGGED_OUT_KEY = "ctd.is_logged_out";

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(DEFAULT_OPERATOR);
  const [ready, setReady] = useState(false);
  const [token, setToken] = useState<string | null>(null);

  useEffect(() => {
    try {
      const isExplicitlyLoggedOut = localStorage.getItem(LOGGED_OUT_KEY) === "true";
      const storedToken = localStorage.getItem(TOKEN_STORAGE_KEY);
      const storedUser = localStorage.getItem(USER_STORAGE_KEY);

      if (storedToken && storedUser && !isExplicitlyLoggedOut) {
        const parsedUser = JSON.parse(storedUser);
        setToken(storedToken);
        setUser(parsedUser);
        api.setToken(storedToken);
      } else if (isExplicitlyLoggedOut) {
        setUser(null);
        setToken(null);
      } else {
        // Default to local testing operator if configured, otherwise built-in active session
        const localOp = getLocalTestOperator();
        setUser(localOp ?? DEFAULT_OPERATOR);
      }
    } catch {
      const localOp = getLocalTestOperator();
      setUser(localOp ?? DEFAULT_OPERATOR);
    } finally { setReady(true); }
  }, []);

  const login = (newToken: string, newUser: AuthUser) => {
    setToken(newToken);
    setUser(newUser);
    api.setToken(newToken);
    try {
      localStorage.removeItem(LOGGED_OUT_KEY);
      localStorage.setItem(TOKEN_STORAGE_KEY, newToken);
      localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(newUser));
    } catch {
      // Ignore storage errors
    }
  };

  const logout = () => {
    setToken(null);
    setUser(null);
    api.setToken(null);
    try {
      localStorage.setItem(LOGGED_OUT_KEY, "true");
      localStorage.removeItem(TOKEN_STORAGE_KEY);
      localStorage.removeItem(USER_STORAGE_KEY);
    } catch {
      // Ignore storage errors
    }
  };

  const can = (action: string, resource: string): boolean => {
    if (!user) return false;
    // Admins and Shift Leads can do everything
    if (user.role === "Shift Lead" || user.role === "Admin") return true;
    // General operators can create/edit tickets & handovers
    if (action === "delete" && resource === "handover") return user.role === "Shift Lead";
    return true;
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        ready,
        isAuthenticated: Boolean(user),
        token,
        login,
        logout,
        can,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

